      QuizQuestion(id: 'easy_84', question: 'Which animal was sent by Allah to show Qabil (Cain) how to bury his brother?', options: ['A dove', 'A crow (raven)', 'A camel', 'A spider'], correctAnswerIndex: 1, explanation: 'Allah sent a crow scratching the ground to teach Qabil how to hide the dead body of his brother Habil.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_85', question: 'What was the very first word of the Quran revealed to Prophet Muhammad?', options: ['Alhamdulillah (Praise)', 'Bismillah (In the name)', 'Iqra (Read)', 'Qul (Say)'], correctAnswerIndex: 2, explanation: 'The first word revealed was "Iqra" (Read/Recite), emphasizing the importance of knowledge.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_86', question: 'What is the special clothing and state of purity required for Hajj and Umrah called?', options: ['Hijab', 'Ihram', 'Thawb', 'Abaya'], correctAnswerIndex: 1, explanation: 'Ihram involves a state of spiritual purity and wearing specific simple garments (for men, two white unstitched cloths).', difficulty: 'easy'),
      QuizQuestion(id: 'easy_87', question: 'Which prophet was thrown into a massive fire but was saved when Allah made it cool and safe?', options: ['Prophet Musa', 'Prophet Yusuf', 'Prophet Ibrahim', 'Prophet Yunus'], correctAnswerIndex: 2, explanation: 'Prophet Ibrahim was thrown into a fire by King Nimrod, but Allah commanded the fire to be cool and peaceful for him.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_88', question: 'What is the special night of power in Ramadan called?', options: ['Laylat al-Miraj', 'Laylat al-Qadr', 'Ashura', 'Isra'], correctAnswerIndex: 1, explanation: 'Laylat al-Qadr (The Night of Decree) is the night the Quran was first revealed, considered better than a thousand months.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_89', question: 'Which companion was known for his incredible strength and became the second Caliph of Islam?', options: ['Abu Bakr', 'Uthman ibn Affan', 'Ali ibn Abi Talib', 'Umar ibn Al-Khattab'], correctAnswerIndex: 3, explanation: 'Umar ibn Al-Khattab was known for his strong will, justice, and physical strength.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_90', question: 'What is the third holiest site in Islam?', options: ['Al-Masjid an-Nabawi', 'Al-Masjid Al-Haram', 'Al-Masjid Al-Aqsa', 'Quba Mosque'], correctAnswerIndex: 2, explanation: 'Al-Masjid Al-Aqsa, located in Jerusalem, is the third holiest site and the first Qibla in Islam.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_91', question: 'How many times did Prophet Muhammad perform the Hajj pilgrimage?', options: ['Once', 'Twice', 'Three times', 'Five times'], correctAnswerIndex: 0, explanation: 'Prophet Muhammad performed Hajj only once in his lifetime, known as the Farewell Hajj.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_92', question: 'What is the name of the Islamic headscarf often worn by Muslim women?', options: ['Kufi', 'Hijab', 'Thawb', 'Niqab'], correctAnswerIndex: 1, explanation: 'The Hijab is a veil worn by some Muslim women in the presence of any male outside of their immediate family.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_93', question: 'Which uncle of Prophet Muhammad was a major enemy of Islam and is mentioned in Surah Al-Masad?', options: ['Abu Talib', 'Hamza', 'Abbas', 'Abu Lahab'], correctAnswerIndex: 3, explanation: 'Abu Lahab fiercely opposed Islam and a specific chapter (Al-Masad) was revealed condemning him.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_94', question: 'What is the holy book given to Prophet Dawud (David)?', options: ['Injeel (Gospel)', 'Zabur (Psalms)', 'Quran', 'Tawrat (Torah)'], correctAnswerIndex: 1, explanation: 'The Zabur was given to Prophet Dawud, known for its beautiful hymns and praises to Allah.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_95', question: 'Which creature protected Prophet Muhammad and Abu Bakr in the Cave of Thawr by spinning a web?', options: ['A bird', 'A spider', 'A snake', 'A bee'], correctAnswerIndex: 1, explanation: 'A spider spun a web over the cave entrance, misleading the enemies into thinking the cave was empty.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_96', question: 'What is the Arabic word for the global community of Muslims?', options: ['Jamaat', 'Tariqah', 'Ummah', 'Madhab'], correctAnswerIndex: 2, explanation: 'The Ummah refers to the collective community of Islamic peoples globally.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_97', question: 'Who is the Creator and Sustainer of everything in the universe according to Islam?', options: ['The Angels', 'Nature', 'Allah', 'The Prophets'], correctAnswerIndex: 2, explanation: 'In Islam, Allah is the sole creator, master, and sustainer of the entire universe.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_98', question: 'What does the word "Quran" literally translate to?', options: ['The Book', 'The Recitation', 'The Law', 'The Light'], correctAnswerIndex: 1, explanation: 'The word Quran comes from the Arabic root meaning "to read" or "to recite".', difficulty: 'easy'),
      QuizQuestion(id: 'easy_99', question: 'What is the name of the first mosque ever built in Islam?', options: ['Masjid al-Haram', 'Masjid an-Nabawi', 'Quba Mosque', 'Masjid al-Aqsa'], correctAnswerIndex: 2, explanation: 'The Quba Mosque, located just outside Medina, was the first mosque built by the Prophet upon migrating.', difficulty: 'easy'),
      QuizQuestion(id: 'easy_100', question: 'Which Prophet was known for his exceptional patience during a severe illness?', options: ['Prophet Ayub (Job)', 'Prophet Yusuf (Joseph)', 'Prophet Yahya (John)', 'Prophet Zakariya (Zechariah)'], correctAnswerIndex: 0, explanation: 'Prophet Ayub is celebrated in Islam as the ultimate symbol of patience and unwavering faith during hardship.', difficulty: 'easy'),
    ];
  }

  List<QuizQuestion> _getMediumQuestionsEn() {
    return [
      QuizQuestion(id: 'mid_1', question: 'What is the Sunnah?', options: ['The teachings of other religions', 'The practices and traditions of Prophet Muhammad', 'Pilgrimage rituals', 'Islamic legal codes'], correctAnswerIndex: 1, explanation: 'The Sunnah refers to the traditions, practices, and sayings of Prophet Muhammad that serve as a model for Muslims.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_2', question: 'Who was the first Muslim Caliph?', options: ['Umar ibn Al-Khattab', 'Abu Bakr', 'Uthman ibn Affan', 'Ali ibn Abi Talib'], correctAnswerIndex: 1, explanation: 'Abu Bakr (As-Siddiq) was the first Caliph after Prophet Muhammad, ruling from 632-634 CE.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_3', question: 'What is Fiqh in Islamic jurisprudence?', options: ['Memorization of Quran', 'Understanding and interpretation of Islamic law', 'Storytelling traditions', 'Poetic expressions'], correctAnswerIndex: 1, explanation: 'Fiqh is the branch of Islamic knowledge dealing with the deep understanding and application of Sharia law.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_4', question: 'What is Ijma in Islamic law?', options: ['Personal opinion', 'Consensus of Islamic scholars', 'Quranic verses', 'Traditions only'], correctAnswerIndex: 1, explanation: 'Ijma is the consensus of Islamic scholars on a particular religious matter and is a primary source of Islamic law.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_5', question: 'How many companions are known as "Rightly Guided Caliphs" (Khulafa-e-Rashidun)?', options: ['2', '3', '4', '5'], correctAnswerIndex: 2, explanation: 'The four Rightly Guided Caliphs are Abu Bakr, Umar, Uthman, and Ali, who led the Muslim community after the Prophet.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_6', question: 'What is the Night of Power called in Arabic?', options: ['Laylat Al-Qadr', 'Laylat Al-Jinn', 'Laylat Al-Isra', 'Laylat Al-Baraa'], correctAnswerIndex: 0, explanation: 'Laylat Al-Qadr (Night of Power or Decree) is when the Quran was first revealed and is considered the most blessed night.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_7', question: 'Which Surah is dedicated to mentioning the Night of Power?', options: ['Surah Al-Alaq', 'Surah Al-Qadr', 'Surah Ar-Rahman', 'Surah Al-Adiyat'], correctAnswerIndex: 1, explanation: 'Surah Al-Qadr (Chapter 97) is devoted entirely to describing the blessings of the Night of Power.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_8', question: 'What is Qiyas in Islamic jurisprudence?', options: ['Measurement', 'Analogical reasoning', 'Reporting', 'Questioning'], correctAnswerIndex: 1, explanation: 'Qiyas is the method of deriving Islamic rulings for new situations by making analogies to similar cases found in the Quran or Sunnah.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_9', question: 'Approximately how many scribes of revelation did Prophet Muhammad have?', options: ['3', '5', '10', 'Around 40'], correctAnswerIndex: 3, explanation: 'Prophet Muhammad had around 40 to 65 scribes over time who recorded the Quranic revelations, including Zayd ibn Harithah, Ali, and Uthman.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_10', question: 'What does Hijab conceptually mean in an Islamic context?', options: ['Only a headscarf', 'Modesty and modest covering for both men and women', 'A physical screen only', 'A religious prohibition'], correctAnswerIndex: 1, explanation: 'Hijab represents a comprehensive concept of modesty, behavior, and dress that applies to both men and women.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_11', question: 'What is the Isra and Mi\'raj?', options: ['Two different battles', 'The Prophet\'s night journey to Jerusalem and ascension to heaven', 'Two Surahs of the Quran', 'Two names of the Kaaba'], correctAnswerIndex: 1, explanation: 'Isra is the miraculous night journey to Jerusalem, and Mi\'raj is the ascension to the heavens to speak with Allah.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_12', question: 'Which Surah contains the Verse of the Throne (Ayat Al-Kursi)?', options: ['Surah Al-Baqarah', 'Surah Aal-Imran', 'Surah An-Noor', 'Surah Ya-Seen'], correctAnswerIndex: 0, explanation: 'Ayat Al-Kursi is found in Surah Al-Baqarah (2:255) and is considered the greatest verse in the Quran.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_13', question: 'What is the shortest Surah in the Quran?', options: ['Surah Al-Ikhlas', 'Surah An-Nas', 'Surah Al-Kawthar', 'Surah Al-Fil'], correctAnswerIndex: 2, explanation: 'Surah Al-Kawthar (Chapter 108) is the shortest Surah in the Quran, containing only 3 verses.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_14', question: 'How many beautifully known names (Asma ul-Husna) of Allah are traditionally emphasized?', options: ['50', '99', '150', '200'], correctAnswerIndex: 1, explanation: 'While Allah has many names, 99 specific names are famously mentioned in Islamic tradition and Hadith.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_15', question: 'What is the Battle of Badr?', options: ['A location in Medina', 'The first major battle between Muslims and Quraysh', 'A trading route', 'A water well'], correctAnswerIndex: 1, explanation: 'The Battle of Badr (2 AH/624 CE) was the first major and decisive military victory for the early Muslims against the Quraysh.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_16', question: 'What does "Ummah" mean?', options: ['Mother', 'Nation or community', 'Grandmother', 'Tribe'], correctAnswerIndex: 1, explanation: 'Ummah refers to the collective, global Muslim community united by their faith in Islam.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_17', question: 'What are the Six Articles of Islamic Belief (Iman)?', options: ['Allah, Quran, Prayer, Fasting, Zakat, Hajj', 'Belief in Allah, Angels, Books, Prophets, Day of Judgment, and Divine Decree', 'Only the Five Pillars', 'Only the names of Allah'], correctAnswerIndex: 1, explanation: 'The Six Articles of Faith form the theological foundation of Islamic belief.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_18', question: 'Who was Prophet Ibrahim\'s first wife?', options: ['Sarah', 'Hagar', 'Keturah', 'Leah'], correctAnswerIndex: 0, explanation: 'Sarah was Prophet Ibrahim\'s first wife and the mother of Prophet Ishaq (Isaac).', difficulty: 'medium'),
      QuizQuestion(id: 'mid_19', question: 'What is the Islamic month of Muharram heavily known for?', options: ['Being the month of fasting', 'Being the month of Hajj', 'Being a sacred month containing the Day of Ashura', 'Being the month of Eid'], correctAnswerIndex: 2, explanation: 'Muharram is the first month of the Islamic year, a sacred month, and contains the historical Day of Ashura (10th of Muharram).', difficulty: 'medium'),
      QuizQuestion(id: 'mid_20', question: 'What is Zakat Al-Fitr?', options: ['Tax on agricultural property', 'Charity given at the end of Ramadan before the Eid prayer', 'Monthly charity', 'Charity for travelers only'], correctAnswerIndex: 1, explanation: 'Zakat Al-Fitr is an obligatory charity of food given before Eid Al-Fitr so everyone can celebrate the day.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_21', question: 'According to the Quran, how many angels will bear the Throne of Allah on the Day of Judgment?', options: ['4', '6', '8', '10'], correctAnswerIndex: 2, explanation: 'Surah Al-Haqqah (69:17) states that eight angels will bear the Throne of Allah on that Day.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_22', question: 'What is the name of the angel who brought the Quranic revelation to Prophet Muhammad?', options: ['Jibreel (Gabriel)', 'Mikail (Michael)', 'Israfil', 'Malik'], correctAnswerIndex: 0, explanation: 'Angel Jibreel is tasked with delivering Allah\'s revelations to all the Prophets.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_23', question: 'According to Hadith, what is the first action a person will be judged on the Day of Judgment?', options: ['Belief', 'Prayer (Salah)', 'Charity (Zakat)', 'Fasting (Sawm)'], correctAnswerIndex: 1, explanation: 'The Prophet said the first deed for which a person will be brought to account on the Day of Judgment will be their prayer.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_24', question: 'How many times does "O you who believe" (Ya ayyuhal-ladheena amanu) appear in the Quran?', options: ['50', '75', '89', '114'], correctAnswerIndex: 2, explanation: 'This specific phrase addressing the believers directly appears exactly 89 times in the Quran.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_25', question: 'Which companion is famously known as the "Translator of the Quran" (Tarjuman al-Quran)?', options: ['Ali ibn Abi Talib', 'Abdullah ibn Masud', 'Abdullah ibn Abbas', 'Ubayy ibn Ka\'b'], correctAnswerIndex: 2, explanation: 'Abdullah ibn Abbas was a young companion for whom the Prophet prayed for deep understanding of religion, earning him this title.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_26', question: 'How many times did Prophet Muhammad perform Hajj?', options: ['Once', 'Twice', 'Three times', 'Five times'], correctAnswerIndex: 0, explanation: 'Prophet Muhammad performed Hajj only once in his life in 10 AH, known as the Farewell Pilgrimage.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_27', question: 'What is Istikharah?', options: ['A fasting ritual', 'A special prayer seeking Allah\'s guidance in making a decision', 'A pilgrimage ritual', 'A type of charity'], correctAnswerIndex: 1, explanation: 'Istikharah is a two-rakat prayer followed by a specific supplication asking Allah for guidance in a choice.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_28', question: 'What are the angels who record a person\'s good and bad deeds called?', options: ['Hafazah', 'Munkar and Nakir', 'Kiraman Katibin', 'Mu\'aqqibat'], correctAnswerIndex: 2, explanation: 'The Kiraman Katibin (Honorable Scribes) sit on a person\'s right and left shoulders to record their deeds.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_29', question: 'What is the punishment in the grave called in Arabic?', options: ['Athab Al-Qabr', 'Jahim', 'Sakar', 'Lazaa'], correctAnswerIndex: 0, explanation: 'Athab Al-Qabr refers to the trials and punishments in the grave, a concept mentioned in Islamic teachings.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_30', question: 'How many verses are in Surah Al-Baqarah, the longest chapter in the Quran?', options: ['100', '200', '286', '300'], correctAnswerIndex: 2, explanation: 'Surah Al-Baqarah has 286 verses, making it the longest chapter in the Quran.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_31', question: 'What does "Sadaqah Jariyah" mean?', options: ['One-time charity', 'Continuous charity whose benefits continue after a person\'s death', 'Forced charity', 'Holiday charity'], correctAnswerIndex: 1, explanation: 'Sadaqah Jariyah includes acts like building a well, mosque, or school, which generate continuous rewards even after death.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_32', question: 'Which female companion and wife of the Prophet narrated the most Hadiths?', options: ['Aisha bint Abu Bakr', 'Fatima bint Muhammad', 'Hafsa bint Umar', 'Khadijah bint Khuwaylid'], correctAnswerIndex: 0, explanation: 'Aisha narrated over 2,200 Hadiths and was one of the foremost scholars of early Islam.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_33', question: 'What is the name of the battle where Muslims dug a massive trench to defend Medina?', options: ['Battle of Badr', 'Battle of Uhud', 'Battle of Khandaq', 'Battle of Hunayn'], correctAnswerIndex: 2, explanation: 'The Battle of Khandaq (Trench), also known as Al-Ahzab, involved defending Medina using a trench suggested by Salman Al-Farsi.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_34', question: 'Which angel is tasked with blowing the Trumpet to signal the Day of Judgment?', options: ['Jibreel', 'Mikail', 'Israfil', 'Malik'], correctAnswerIndex: 2, explanation: 'Angel Israfil will blow the Trumpet (Soor) twice: once to end the world, and once to resurrect the dead.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_35', question: 'What is the Islamic concept of "Tawakkul"?', options: ['Obligatory prayer', 'Complete reliance on Allah after doing one\'s best', 'Fasting during travel', 'Giving secret charity'], correctAnswerIndex: 1, explanation: 'Tawakkul means tying your camel first, and then placing your complete trust and reliance in Allah\'s plan.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_36', question: 'How many destructive major sins (Al-Mubiqat) did the Prophet explicitly list together in a famous Hadith?', options: ['3', '5', '7', '9'], correctAnswerIndex: 2, explanation: 'The Prophet listed 7 destructive sins, including Shirk, magic, murder, consuming orphan\'s wealth, usury, fleeing the battlefield, and slandering chaste women.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_37', question: 'What is the Islamic concept of "Taqwa"?', options: ['Fear of enemies', 'Piety, righteousness, and God-consciousness', 'Congregational prayer', 'Fasting voluntarily'], correctAnswerIndex: 1, explanation: 'Taqwa is the inner consciousness of Allah, driving a person to do good and avoid evil.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_38', question: 'Who did Prophet Muhammad designate as the best reciter of the Quran among his companions?', options: ['Abdullah ibn Masud', 'Ubayy ibn Ka\'b', 'Ali ibn Abi Talib', 'Zayd ibn Harithah'], correctAnswerIndex: 1, explanation: 'The Prophet explicitly praised Ubayy ibn Ka\'b as the best reciter (Qari) of the Quran among the Ummah.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_39', question: 'What is the significance of the number 19 in Surah Al-Muddaththir?', options: ['Number of prophets', 'Number of chapters in a section', 'The number of angels guarding Hellfire', 'Number of daily prayers initially commanded'], correctAnswerIndex: 2, explanation: 'Surah Al-Muddaththir states that there are 19 fierce angels serving as guardians over Hell.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_40', question: 'What was the first Qibla (direction of prayer) for Muslims before it was changed to Mecca?', options: ['Al-Aqsa Mosque (Jerusalem)', 'Quba Mosque', 'Mount Sinai', 'The Prophet\'s Mosque'], correctAnswerIndex: 0, explanation: 'Muslims originally prayed facing Al-Aqsa Mosque in Jerusalem for about 16-17 months before the Qibla was changed to the Kaaba.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_41', question: 'In which cave did Prophet Muhammad regularly meditate before the first revelation?', options: ['Cave of Thawr', 'Cave of Hira', 'Cave of the Sleepers', 'Cave of Mount Sinai'], correctAnswerIndex: 1, explanation: 'The Prophet used to retreat to the Cave of Hira in Jabal al-Nour (Mountain of Light) near Mecca.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_42', question: 'Which Surah is often referred to as the "Heart of the Quran" by Islamic scholars?', options: ['Surah Ar-Rahman', 'Surah Al-Mulk', 'Surah Ya-Seen', 'Surah Al-Baqarah'], correctAnswerIndex: 2, explanation: 'Surah Ya-Seen is referred to as the heart of the Quran because it powerfully summarizes the core beliefs of Islam.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_43', question: 'How many years did the Prophet preach in Mecca before the migration (Hijra)?', options: ['10 years', '13 years', '15 years', '23 years'], correctAnswerIndex: 1, explanation: 'The Meccan period of revelation and preaching lasted 13 years before the persecution led to the Hijra.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_44', question: 'Which companion was given the title "The Drawn Sword of Allah" (Sayfullah)?', options: ['Ali ibn Abi Talib', 'Umar ibn Al-Khattab', 'Khalid ibn Al-Walid', 'Hamza ibn Abdul-Muttalib'], correctAnswerIndex: 2, explanation: 'Khalid ibn Al-Walid was given this title by the Prophet due to his unmatched military genius and dedication.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_45', question: 'In which battle was Prophet Muhammad injured and his tooth broken?', options: ['Battle of Badr', 'Battle of the Trench', 'Battle of Tabuk', 'Battle of Uhud'], correctAnswerIndex: 3, explanation: 'During the Battle of Uhud, the Muslim army faced a severe setback and the Prophet himself was wounded.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_46', question: 'In what year of the Hijri calendar did the Treaty of Hudaybiyyah take place?', options: ['2 AH', '4 AH', '6 AH', '8 AH'], correctAnswerIndex: 2, explanation: 'The Treaty of Hudaybiyyah, a pivotal peace agreement, was signed in 6 AH.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_47', question: 'What is the collective name given to the two most authentic collections of Hadith (Bukhari and Muslim)?', options: ['Al-Muwatta', 'As-Sunan', 'As-Sahihayn', 'Al-Musnad'], correctAnswerIndex: 2, explanation: 'As-Sahihayn means "The Two Authentics," referring to Sahih al-Bukhari and Sahih Muslim.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_48', question: 'Who was the wet nurse that took care of Prophet Muhammad in his infancy?', options: ['Aminah', 'Halimah as-Sa\'diyah', 'Umm Ayman', 'Fatimah'], correctAnswerIndex: 1, explanation: 'Halimah as-Sa\'diyah of the Banu Sa\'d tribe nursed and raised the Prophet in the desert during his early years.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_49', question: 'What was the name of Prophet Muhammad\'s grandfather, who cared for him after his mother died?', options: ['Abu Talib', 'Abdul Muttalib', 'Hashim', 'Abd Manaf'], correctAnswerIndex: 1, explanation: 'Abdul Muttalib, a respected leader of the Quraysh, took custody of the Prophet until he passed away when the Prophet was eight.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_50', question: 'What was the name of the Prophet Muhammad\'s favorite camel?', options: ['Al-Qaswa', 'Al-Buraq', 'Duldul', 'Ya\'fur'], correctAnswerIndex: 0, explanation: 'Al-Qaswa was his beloved camel, which he rode during the Hijra and the Farewell Pilgrimage.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_51', question: 'In the Battle of Yarmouk, the Muslim army faced which major empire?', options: ['The Persian Empire', 'The Roman (Byzantine) Empire', 'The Mongol Empire', 'The Egyptian Empire'], correctAnswerIndex: 1, explanation: 'The Battle of Yarmouk was a decisive victory for the Muslims against the Byzantine (Eastern Roman) Empire.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_52', question: 'What is the topic of the longest Ayah (verse) in the Quran (2:282)?', options: ['Marriage', 'Fasting', 'Contracts and Debt', 'Inheritance'], correctAnswerIndex: 2, explanation: 'Ayat al-Dayn (The Verse of Debt) details the rules for writing down financial transactions and contracts.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_53', question: 'Which Surah in the Quran does NOT begin with "Bismillah ir-Rahman ir-Rahim"?', options: ['Surah Al-Baqarah', 'Surah At-Tawbah', 'Surah Al-Kahf', 'Surah Al-Mulk'], correctAnswerIndex: 1, explanation: 'Surah At-Tawbah (Chapter 9) is the only chapter that does not start with the Basmalah.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_54', question: 'Which Surah contains the phrase "Bismillah ir-Rahman ir-Rahim" twice?', options: ['Surah An-Naml', 'Surah Al-Qasas', 'Surah Taha', 'Surah Yusuf'], correctAnswerIndex: 0, explanation: 'Surah An-Naml (Chapter 27) has it at the beginning and in verse 30 (in a letter from Prophet Sulaiman).', difficulty: 'medium'),
      QuizQuestion(id: 'mid_55', question: 'Which companion was known as "The Keeper of the Secret of the Prophet"?', options: ['Abu Hurairah', 'Anas ibn Malik', 'Hudhayfah ibn al-Yaman', 'Zayd ibn Thabit'], correctAnswerIndex: 2, explanation: 'The Prophet trusted Hudhayfah with the names of the hypocrites in Medina, a secret he kept fiercely.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_56', question: 'Which Prophet was granted the title "Kalimullah" (The one who spoke to Allah)?', options: ['Prophet Ibrahim', 'Prophet Musa', 'Prophet Isa', 'Prophet Muhammad'], correctAnswerIndex: 1, explanation: 'Prophet Musa (Moses) is called Kalimullah because Allah spoke to him directly on Mount Sinai.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_57', question: 'Which Prophet is mentioned the most times by name in the Quran?', options: ['Prophet Muhammad', 'Prophet Ibrahim', 'Prophet Isa', 'Prophet Musa'], correctAnswerIndex: 3, explanation: 'Prophet Musa is mentioned by name 136 times in the Quran, more than any other prophet.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_58', question: 'How old was Prophet Muhammad when he passed away?', options: ['60 years', '61 years', '63 years', '65 years'], correctAnswerIndex: 2, explanation: 'Prophet Muhammad passed away in Medina at the age of 63 in the lunar calendar.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_59', question: 'Over how many years was the Quran revealed?', options: ['10 years', '15 years', '23 years', '40 years'], correctAnswerIndex: 2, explanation: 'The Quran was revealed in stages over approximately 23 years (13 in Mecca, 10 in Medina).', difficulty: 'medium'),
      QuizQuestion(id: 'mid_60', question: 'Between which two hills did Hagar (Hajar) run back and forth looking for water?', options: ['Safa and Marwa', 'Arafat and Muzdalifah', 'Uhud and Noor', 'Sinai and Judi'], correctAnswerIndex: 0, explanation: 'Hajar ran between Safa and Marwa seven times, an act commemorated by pilgrims during Sa\'i.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_61', question: 'What is Tayammum?', options: ['A type of fasting', 'Dry ablution using clean earth/sand when water is unavailable', 'A special prayer for rain', 'Breaking the fast'], correctAnswerIndex: 1, explanation: 'Tayammum is the Islamic act of dry ablution using purified sand or dust, allowed when water is absent or harmful.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_62', question: 'What is the name of the angel who guards Hellfire?', options: ['Munkar', 'Ridwan', 'Malik', 'Azraeel'], correctAnswerIndex: 2, explanation: 'Angel Malik is the chief guardian of Hellfire, explicitly mentioned by name in Surah Az-Zukhruf.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_63', question: 'What is the name traditionally given to the angel guarding Paradise (Jannah)?', options: ['Ridwan', 'Malik', 'Jibreel', 'Israfil'], correctAnswerIndex: 0, explanation: 'Islamic tradition identifies Ridwan as the angel appointed as the gatekeeper of Paradise.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_64', question: 'What does the word "Sunnah" literally translate to in Arabic?', options: ['The Truth', 'The Book', 'The Path or Way', 'The Law'], correctAnswerIndex: 2, explanation: 'Linguistically, Sunnah means a clear, well-trodden path or a customary practice.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_65', question: 'What prestigious title is given to the wives of Prophet Muhammad?', options: ['Queens of Islam', 'Mothers of the Believers', 'Daughters of the Ummah', 'Leaders of Paradise'], correctAnswerIndex: 1, explanation: 'The Quran (33:6) declares the Prophet\'s wives as the "Mothers of the Believers" (Ummahat al-Mu\'mineen).', difficulty: 'medium'),
      QuizQuestion(id: 'mid_66', question: 'Who was the last of the Prophet\'s wives to pass away?', options: ['Aisha', 'Hafsa', 'Umm Salama', 'Sawda'], correctAnswerIndex: 2, explanation: 'Umm Salama lived a long life, passing away around 61 AH, outliving the other wives.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_67', question: 'Which Islamic month directly precedes Ramadan?', options: ['Rajab', 'Sha\'ban', 'Shawwal', 'Muharram'], correctAnswerIndex: 1, explanation: 'Sha\'ban is the 8th month of the Islamic calendar, immediately before the fasting month of Ramadan.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_68', question: 'Which Islamic month directly follows Ramadan?', options: ['Shawwal', 'Dhul-Qi\'dah', 'Safar', 'Rajab'], correctAnswerIndex: 0, explanation: 'Shawwal is the 10th month; its first day is celebrated as Eid al-Fitr.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_69', question: 'What is the Islamic term for showing off or doing good deeds to gain praise from people?', options: ['Shirk', 'Riya', 'Ghibah', 'Namimah'], correctAnswerIndex: 1, explanation: 'Riya is considered a hidden form of Shirk (polytheism) because the deed is done for people, not for Allah.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_70', question: 'Who was the first person to be martyred for Islam?', options: ['Yasir', 'Sumayyah bint Khayyat', 'Hamza', 'Mus\'ab ibn \'Umair'], correctAnswerIndex: 1, explanation: 'Sumayyah was killed by Abu Jahl for refusing to abandon Islam, becoming the first martyr (Shaheed) in Islam.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_71', question: 'Who was sent as the first ambassador of Islam to teach the people of Medina?', options: ['Ali ibn Abi Talib', 'Uthman ibn Affan', 'Mus\'ab ibn \'Umair', 'Zayd ibn Harithah'], correctAnswerIndex: 2, explanation: 'The Prophet sent Mus\'ab to Medina before the Hijra to teach the Quran and prepare the city for migration.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_72', question: 'Which beloved uncle of the Prophet was famously martyred at the Battle of Uhud?', options: ['Abu Talib', 'Abbas', 'Abu Lahab', 'Hamza ibn Abdul-Muttalib'], correctAnswerIndex: 3, explanation: 'Hamza, known as the "Lion of Allah," was tragically martyred during the Battle of Uhud.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_73', question: 'To which major Arab tribe did Prophet Muhammad belong?', options: ['Banu Nadir', 'Banu Qaynuqa', 'Quraysh', 'Khazraj'], correctAnswerIndex: 2, explanation: 'The Prophet was a member of the Banu Hashim clan, which was part of the prominent Quraysh tribe of Mecca.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_74', question: 'Which Prophet was raised alive to the heavens and will return before the Day of Judgment?', options: ['Prophet Idris', 'Prophet Musa', 'Prophet Isa', 'Prophet Ilyas'], correctAnswerIndex: 2, explanation: 'Islam teaches that Prophet Isa (Jesus) was not crucified, but raised to heaven by Allah.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_75', question: 'Who is prophesied to return to Earth to defeat the Dajjal (Anti-Christ)?', options: ['Prophet Muhammad', 'Prophet Isa', 'Imam Mahdi', 'Angel Jibreel'], correctAnswerIndex: 1, explanation: 'Prophet Isa will descend in Damascus and will ultimately defeat the False Messiah (Dajjal).', difficulty: 'medium'),
      QuizQuestion(id: 'mid_76', question: 'According to Islamic eschatology, what creature will emerge from the earth to speak to people as a major sign of the Last Day?', options: ['The Leviathan', 'Dabbat al-Ard (The Beast of the Earth)', 'Buraq', 'Gog and Magog'], correctAnswerIndex: 1, explanation: 'The emergence of the Beast of the Earth is one of the ten Major Signs of the Day of Judgment.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_77', question: 'Who was the Christian King of Abyssinia who provided refuge to the early Muslims?', options: ['Heraclius', 'Khosrow', 'The Negus (Najashi)', 'Muqawqis'], correctAnswerIndex: 2, explanation: 'Ashama ibn Abjar, the Negus of Aksum, sheltered the Muslims who migrated to Abyssinia to escape persecution.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_78', question: 'What famous treaty signed in 6 AH was initially seen as a setback but was declared a "manifest victory" by the Quran?', options: ['Treaty of Medina', 'Treaty of Hudaybiyyah', 'Treaty of Taif', 'Treaty of Tabuk'], correctAnswerIndex: 1, explanation: 'The Treaty of Hudaybiyyah brought a 10-year peace, allowing Islam to spread rapidly across Arabia.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_79', question: 'Which companion suggested digging a trench around Medina to defend against the coalition army?', options: ['Umar ibn Al-Khattab', 'Salman Al-Farsi', 'Bilal ibn Rabah', 'Abu Ubaidah ibn al-Jarrah'], correctAnswerIndex: 1, explanation: 'Salman the Persian introduced the defensive tactic of digging a trench, a method used in Persia but unknown to Arabs.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_80', question: 'Who is the only companion of the Prophet mentioned by name in the Quran?', options: ['Abu Bakr', 'Zayd ibn Harithah', 'Ali ibn Abi Talib', 'Umar ibn Al-Khattab'], correctAnswerIndex: 1, explanation: 'Zayd ibn Harithah is explicitly named in Surah Al-Ahzab (33:37).', difficulty: 'medium'),
      QuizQuestion(id: 'mid_81', question: 'Approximately how many Sujood of Tilawah (prostrations of recitation) are there in the Quran?', options: ['5', '10', '15', '20'], correctAnswerIndex: 2, explanation: 'Most scholars agree there are 14 or 15 places in the Quran where a prostration is required or highly recommended upon reading.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_82', question: 'Which short Surah is equated in reward to reading one-third of the entire Quran?', options: ['Surah Al-Falaq', 'Surah Al-Kafirun', 'Surah Al-Ikhlas', 'Surah An-Nas'], correctAnswerIndex: 2, explanation: 'The Prophet said that reading Surah Al-Ikhlas (Chapter 112) is equivalent to one-third of the Quran due to its pure declaration of monotheism.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_83', question: 'What is the absolute most unforgivable sin in Islam (if one dies without repenting)?', options: ['Murder', 'Theft', 'Shirk (Polytheism)', 'Disrespecting parents'], correctAnswerIndex: 2, explanation: 'Shirk, associating partners with Allah, is the only sin Allah says He will not forgive if a person dies upon it.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_84', question: 'What is the specific Arabic term for the biography of Prophet Muhammad?', options: ['Hadith', 'Tafsir', 'Seerah', 'Aqeedah'], correctAnswerIndex: 2, explanation: 'Seerah (or Sirat al-Nabi) refers to the traditional Muslim biographies of Muhammad.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_85', question: 'According to Islamic tradition, how many main gates (doors) does Jannah (Paradise) have?', options: ['4', '6', '8', '12'], correctAnswerIndex: 2, explanation: 'Paradise has 8 gates, each designated for people who excelled in different types of worship (prayer, fasting, charity, etc.).', difficulty: 'medium'),
      QuizQuestion(id: 'mid_86', question: 'What is the name of the gate in Paradise designated specifically for those who fast frequently?', options: ['Ar-Rayyan', 'Al-Kawthar', 'Al-Firdaus', 'Al-Adn'], correctAnswerIndex: 0, explanation: 'Ar-Rayyan is the special gate of Heaven that only those who observed fasting will enter through on the Day of Judgment.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_87', question: 'Which Prophet was given the title "Ruhullah" (Spirit from Allah)?', options: ['Prophet Adam', 'Prophet Nuh', 'Prophet Isa', 'Prophet Yahya'], correctAnswerIndex: 2, explanation: 'Prophet Isa (Jesus) is referred to as Ruhullah, as he was created by the command and spirit breathed from Allah.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_88', question: 'Which Prophet is referred to as "Safiyullah" (The Chosen One of Allah)?', options: ['Prophet Adam', 'Prophet Dawud', 'Prophet Sulaiman', 'Prophet Ayyub'], correctAnswerIndex: 0, explanation: 'Prophet Adam, the first man and prophet, is given the title Safiyullah.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_89', question: 'Who was the absolutely first person to accept Islam after the revelation began?', options: ['Abu Bakr', 'Ali ibn Abi Talib', 'Khadijah bint Khuwaylid', 'Zayd ibn Harithah'], correctAnswerIndex: 2, explanation: 'His wife, Khadijah, was the first human being to believe in his prophethood and accept Islam.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_90', question: 'Who was the first youth/child to accept Islam?', options: ['Usama ibn Zayd', 'Ali ibn Abi Talib', 'Abdullah ibn Umar', 'Hasan ibn Ali'], correctAnswerIndex: 1, explanation: 'Ali ibn Abi Talib accepted Islam when he was around 10 years old, making him the first child to convert.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_91', question: 'Which companion famously purchased Bilal ibn Rabah from his cruel master to set him free?', options: ['Uthman ibn Affan', 'Abu Bakr As-Siddiq', 'Abdur Rahman ibn Awf', 'Umar ibn Al-Khattab'], correctAnswerIndex: 1, explanation: 'Abu Bakr spent much of his wealth buying and freeing persecuted Muslim slaves, including Bilal.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_92', question: 'In which famous battle did the Muslim army decisively defeat the Sasanian (Persian) Empire?', options: ['Battle of Yarmouk', 'Battle of Al-Qadisiyyah', 'Battle of Mut\'ah', 'Battle of Hunayn'], correctAnswerIndex: 1, explanation: 'The Battle of Al-Qadisiyyah (15 AH) was a pivotal victory that led to the conquest of the Persian Empire.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_93', question: 'What is the name of the narrow bridge over Hellfire that all humanity must cross on the Day of Judgment?', options: ['Al-Kawthar', 'As-Sirat', 'Al-A\'raf', 'Al-Barzakh'], correctAnswerIndex: 1, explanation: 'As-Sirat is a bridge described as thinner than a hair and sharper than a sword, which believers will cross successfully.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_94', question: 'What is the Arabic term used in the Quran for the Day of Resurrection?', options: ['Yawm al-Jumu\'ah', 'Yawm al-Qiyamah', 'Yawm al-Arafa', 'Yawm al-Nahr'], correctAnswerIndex: 1, explanation: 'Yawm al-Qiyamah translates to the Day of Resurrection or the Day of Standing.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_95', question: 'What is the name of the sacred river/pool granted to Prophet Muhammad in Paradise?', options: ['Zamzam', 'Tasneem', 'Al-Kawthar', 'Salsabil'], correctAnswerIndex: 2, explanation: 'Al-Kawthar is a river of abundance given to the Prophet, and its water is sweeter than honey and whiter than milk.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_96', question: 'Which city served as the very first capital of the Islamic State?', options: ['Mecca', 'Damascus', 'Baghdad', 'Medina'], correctAnswerIndex: 3, explanation: 'Medina (originally Yathrib) became the first political and spiritual capital of the Muslim Ummah after the Hijra.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_97', question: 'Under whose Caliphate was the Quran first compiled into a single manuscript (Suhuf)?', options: ['Abu Bakr', 'Umar', 'Uthman', 'Ali'], correctAnswerIndex: 0, explanation: 'Following the Battle of Yamama, Abu Bakr ordered Zayd ibn Thabit to collect all written and memorized fragments of the Quran into one volume.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_98', question: 'Who was the famous Muslim general who led the conquest of Al-Andalus (Spain)?', options: ['Khalid ibn Al-Walid', 'Amr ibn al-Aas', 'Tariq ibn Ziyad', 'Salahuddin Al-Ayyubi'], correctAnswerIndex: 2, explanation: 'Tariq ibn Ziyad crossed the strait (now named Gibraltar after him) and began the Islamic rule in Spain in 711 CE.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_99', question: 'What is a "Hadith Qudsi"?', options: ['A weak hadith', 'A saying of a companion', 'Meaning from Allah, but worded by the Prophet', 'A chapter of the Quran'], correctAnswerIndex: 2, explanation: 'Hadith Qudsi are sacred hadiths where the Prophet relays a direct message or statement from Allah, distinct from the Quran.', difficulty: 'medium'),
      QuizQuestion(id: 'mid_100', question: 'What was the very first Surah (chapter) revealed to Prophet Muhammad?', options: ['Surah Al-Fatiha', 'Surah Al-Alaq', 'Surah Al-Muddaththir', 'Surah Al-Qalam'], correctAnswerIndex: 1, explanation: 'The first five verses of Surah Al-Alaq (Read in the name of your Lord...) were the very first revelation in the Cave of Hira.', difficulty: 'medium'),
    ];
  }

  List<QuizQuestion> _getHardQuestionsEn() {
    return [
      QuizQuestion(id: 'hard_1', question: 'What is the Tafsir approach that relies heavily on classical Islamic scholars and transmission called?', options: ['Tafsir Bil-Ma\'thur', 'Tafsir Bil-Ra\'y', 'Tafsir Bil-Ijma', 'Tafsir Bil-Ijtihad'], correctAnswerIndex: 0, explanation: 'Tafsir Bil-Ma\'thur is exegesis based on transmitted traditions from the Prophet and his companions.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_2', question: 'What is the term used in Quranic Sciences for the specific historical circumstances or reasons for a verse\'s revelation?', options: ['Tafsir al-Jalalayn', 'Asbab al-Nuzul', 'Al-Nasikh wal-Mansukh', 'Makki wa Madani'], correctAnswerIndex: 1, explanation: 'Asbab al-Nuzul refers to the specific historical events or questions that prompted the revelation of particular verses.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_3', question: 'What is the concept of "Naskh" in Quranic jurisprudence?', options: ['Copying manuscripts', 'Abrogation of earlier revelations by later ones', 'Narration of Hadith', 'Specification of general rulings'], correctAnswerIndex: 1, explanation: 'Naskh refers to the abrogation of earlier Quranic rulings by later, more specific revelations.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_4', question: 'How many times is Prophet Muhammad explicitly mentioned by his name "Muhammad" in the Quran?', options: ['4 times', '5 times', '25 times', '136 times'], correctAnswerIndex: 0, explanation: 'The name "Muhammad" appears exactly 4 times in the Quran (in Surahs Aal-Imran, Al-Ahzab, Muhammad, and Al-Fath).', difficulty: 'hard'),
      QuizQuestion(id: 'hard_5', question: 'What is "Matn" in Hadith terminology?', options: ['The chain of narrators', 'The actual text/body of the hadith', 'The narrator himself', 'The topic discussed'], correctAnswerIndex: 1, explanation: 'Matn refers to the actual text or body of a hadith, as opposed to the Isnad (chain of narration).', difficulty: 'hard'),
      QuizQuestion(id: 'hard_6', question: 'Which Surah contains the longest single verse in the Quran, known as Ayat al-Dayn?', options: ['Surah Al-Baqarah', 'Surah Aal-Imran', 'Surah An-Nisa', 'Surah An-Noor'], correctAnswerIndex: 0, explanation: 'Verse 282 of Surah Al-Baqarah, which details the recording of debts, is the longest single verse in the Quran.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_7', question: 'What is "Ijtihad" in Islamic jurisprudence?', options: ['Following scholarly consensus blindly', 'Independent reasoning by qualified scholars to derive rulings', 'Memorizing the entire Quran', 'Teaching Islamic law'], correctAnswerIndex: 1, explanation: 'Ijtihad is the independent intellectual effort by qualified scholars to derive Islamic rulings from primary sources.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_8', question: 'How many Surahs in the Quran begin with the exact disjointed letters "Alif-Lam-Meem"?', options: ['3', '4', '5', '6'], correctAnswerIndex: 3, explanation: 'Six Surahs begin with Alif-Lam-Meem: Al-Baqarah, Aal-Imran, Al-Ankabut, Ar-Rum, Luqman, and As-Sajdah.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_9', question: 'What is the "Sunnat Allah" mentioned in the Quran?', options: ['The daily routines of angels', 'The unchanging universal laws and patterns established by Allah', 'Prophetic practices only', 'The rules of Islamic finance'], correctAnswerIndex: 1, explanation: 'Sunnat Allah refers to the unchanging, consistent laws and patterns established by Allah in His creation.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_10', question: 'Which Prophet is mentioned by name most frequently in the Quran?', options: ['Prophet Muhammad', 'Prophet Ibrahim', 'Prophet Musa', 'Prophet Isa'], correctAnswerIndex: 2, explanation: 'Prophet Musa (Moses) is mentioned by name 136 times, more frequently than any other prophet in the Quran.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_11', question: 'In Usul al-Fiqh, what is the difference between "Haram" and "Makruh"?', options: ['No difference', 'Haram is strictly forbidden while Makruh is disliked but not sinful', 'Makruh is strictly forbidden, Haram is slightly disliked', 'Both incur major sins'], correctAnswerIndex: 1, explanation: 'Haram is an absolute prohibition incurring sin, while Makruh is an action discouraged by Sharia but not strictly punishable.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_12', question: 'What is "Ikhtilaf" in Islamic jurisprudence?', options: ['Legitimate scholarly disagreement on legal matters', 'Political succession', 'Conflict between nations', 'Difference in prayer timings'], correctAnswerIndex: 0, explanation: 'Ikhtilaf refers to the accepted, legitimate disagreement among Islamic jurists on secondary matters of law.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_13', question: 'Which Surah contains exactly 18 prophets mentioned by name in consecutive verses (Verses 83-86)?', options: ['Surah Al-Anbiya', 'Surah Al-An\'am', 'Surah Maryam', 'Surah Al-Baqarah'], correctAnswerIndex: 1, explanation: 'Surah Al-An\'am lists 18 prophets sequentially, showcasing a profound summary of prophetic lineage.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_14', question: 'What is the principle of "Darurah" in Islamic law?', options: ['General public interest', 'Necessity dictates exceptions, lifting prohibitions temporarily', 'Personal preference', 'Customary law'], correctAnswerIndex: 1, explanation: 'Darurah is a legal maxim where severe necessity permits what is otherwise forbidden to preserve life or prevent great harm.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_15', question: 'How many Surahs in the Quran are named after animals or insects?', options: ['4', '5', '6', '7'], correctAnswerIndex: 2, explanation: 'Six Surahs: Al-Baqarah (Cow), Al-An\'am (Cattle), An-Nahl (Bee), An-Naml (Ant), Al-Ankabut (Spider), Al-Fil (Elephant).', difficulty: 'hard'),
      QuizQuestion(id: 'hard_16', question: 'What is "Tawatur" (Mutawatir) in Hadith studies?', options: ['A single isolated chain of narration', 'A narration reported by so many people at each level that conspiracy to lie is impossible', 'A weak hadith', 'A fabricated hadith'], correctAnswerIndex: 1, explanation: 'A Mutawatir hadith yields absolute certainty because it is transmitted by a massive, diverse group in every generation.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_17', question: 'Which Surah is widely known to contain the most comprehensive laws regarding inheritance (Fara\'id)?', options: ['Surah Al-Baqarah', 'Surah Aal-Imran', 'Surah An-Nisa', 'Surah At-Tawbah'], correctAnswerIndex: 2, explanation: 'Surah An-Nisa (Chapter 4) provides the most detailed and foundational rulings on the Islamic inheritance system.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_18', question: 'What is "Tawhid Ar-Rububiyyah"?', options: ['Believing in all prophets equally', 'Belief in the absolute Lordship, creation, and control of Allah', 'Worshipping Allah alone', 'Belief in the Day of Judgment'], correctAnswerIndex: 1, explanation: 'Tawhid Ar-Rububiyyah affirms that Allah is the sole Creator, Sustainer, and Master of the universe.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_19', question: 'In Mustalah al-Hadith, what constitutes a "Gharib" hadith?', options: ['A bizarre or strange text', 'A hadith narrated by only one narrator at any stage in the chain', 'A hadith missing its final narrator', 'A hadith contradicting the Quran'], correctAnswerIndex: 1, explanation: 'A Gharib hadith is one where the chain relies on a single narrator at some link, making it "isolated."', difficulty: 'hard'),
      QuizQuestion(id: 'hard_20', question: 'What does "Seerah Nabawiyyah" formally mean?', options: ['Islamic dietary laws', 'The comprehensive biography and campaigns of Prophet Muhammad', 'Interpretation of dreams', 'Collection of early poems'], correctAnswerIndex: 1, explanation: 'Seerah is the dedicated study of the Prophet\'s life, character, treaties, battles, and chronological history.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_21', question: 'What is the specific focus of the science known as "Mustalah al-Hadith"?', options: ['Memorizing hadith texts', 'The terminology, rules, and criteria to evaluate the authenticity of Hadith narrators and chains', 'Translating hadith to other languages', 'Applying hadith to modern politics'], correctAnswerIndex: 1, explanation: 'Mustalah al-Hadith systematically studies the chains (Isnad) and text (Matn) to grade a hadith as Sahih, Da\'if, etc.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_22', question: 'According to the majority of scholars, which verse is considered the very last verse of the Quran to be revealed?', options: ['2:281 (Surah Al-Baqarah)', '5:3 (Surah Al-Ma\'idah)', '9:129 (Surah At-Tawbah)', '110:3 (Surah An-Nasr)'], correctAnswerIndex: 0, explanation: 'Most classical scholars agree that verse 2:281 ("And fear a Day when you will be returned to Allah...") was the final revelation.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_23', question: 'What is the doctrine of "Maqasid al-Shari\'ah" (The Five Higher Objectives)?', options: ['The Five Pillars of Islam', 'Preservation of Religion, Life, Intellect, Lineage, and Property', 'The five daily prayers', 'The five major sins'], correctAnswerIndex: 1, explanation: 'Maqasid al-Shari\'ah represents the ultimate goals of Islamic law: protecting faith, life, intellect, family, and wealth.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_24', question: 'How many chapters of the Quran start without the Bismillah?', options: ['0', '1', '2', '5'], correctAnswerIndex: 1, explanation: 'Surah At-Tawbah (Chapter 9) is the only chapter that does not begin with the Basmalah.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_25', question: 'In Quranic exegesis, what is the difference between "Muhkam" and "Mutashabih" verses?', options: ['Meccan vs Medinan', 'Clear, foundational verses vs. ambiguous or allegorical verses', 'Long vs Short verses', 'Abrogating vs Abrogated verses'], correctAnswerIndex: 1, explanation: 'Muhkam verses have clear, unmistakable meanings, while Mutashabih verses are allegorical and their exact reality is known to Allah.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_26', question: 'Which of the following describes "Tafsir bi al-Ra\'y"?', options: ['Tafsir based purely on prophetic traditions', 'Tafsir based on independent rational reasoning and linguistic deduction', 'Tafsir by consensus', 'Tafsir based on Jewish traditions'], correctAnswerIndex: 1, explanation: 'Tafsir bi al-Ra\'y uses intellect, Arabic grammar, and logical deduction, contrasting with Tafsir bil-Ma\'thur (transmission).', difficulty: 'hard'),
      QuizQuestion(id: 'hard_27', question: 'What is "Isnad" in hadith terminology?', options: ['The text of hadith', 'The chain of narrators through which the hadith is transmitted', 'The topic of the hadith', 'The grading of the hadith'], correctAnswerIndex: 1, explanation: 'The Isnad provides the historical lineage of who heard the report from whom, essential for verification.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_28', question: 'In Usul al-Fiqh, what is the \'Illah in a Qiyas (analogy)?', options: ['The new ruling', 'The original case', 'The effective cause or underlying reason that justifies the ruling', 'The consensus'], correctAnswerIndex: 2, explanation: 'The \'Illah is the shared attribute between the original case (Asl) and the new case (Far\') that necessitates the same ruling.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_29', question: 'Which type of Hajj involves performing Umrah, exiting Ihram entirely, and then re-entering Ihram for Hajj later?', options: ['Hajj Ifrad', 'Hajj Qiran', 'Hajj Tamattu\'', 'Hajj Badal'], correctAnswerIndex: 2, explanation: 'Hajj Tamattu\' allows a pilgrim to complete Umrah, enjoy normal restrictions, and assume a new Ihram for Hajj on the 8th of Dhul Hijjah.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_30', question: 'What is the concept of "Tawhid Al-Uluhiyyah"?', options: ['Belief in angels', 'Belief that Allah alone has the exclusive right to be worshipped', 'Belief in fate', 'Belief in prophets'], correctAnswerIndex: 1, explanation: 'Tawhid Al-Uluhiyyah (or Al-Ibadah) asserts that all forms of worship must be directed solely to Allah without partners.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_31', question: 'Which scholar famously compiled "Sahih Al-Bukhari", the most authentic book after the Quran?', options: ['Muslim ibn Al-Hajjaj', 'Muhammad ibn Isma\'il Al-Bukhari', 'At-Tirmidhi', 'Abu Dawood'], correctAnswerIndex: 1, explanation: 'Imam Al-Bukhari sifted through hundreds of thousands of narrations to compile his remarkably rigorous Sahih collection.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_32', question: 'What defines a "Medinan" (Madani) Surah?', options: ['It mentions Medina', 'It was revealed after the Hijra (migration) to Medina, even if geographically outside it', 'It only contains legal rulings', 'It was revealed inside a mosque'], correctAnswerIndex: 1, explanation: 'The classification is temporal: anything revealed after the Prophet\'s migration to Medina is considered Madani.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_33', question: 'What are the four primary sources of Sharia according to the majority of Sunni jurisprudence?', options: ['Quran, Sunnah, Qiyas (Analogy), and Ijma (Consensus)', 'Quran, Sunnah, History, and Logic', 'Quran, Rulings of Caliphs, Logic, and Custom', 'Quran, Sunnah, Dreams, and Philosophy'], correctAnswerIndex: 0, explanation: 'The four agreed-upon foundational sources of Usul al-Fiqh are the Quran, Sunnah, Ijma, and Qiyas.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_34', question: 'What is the minimum threshold (Nisab) for Zakat on pure gold?', options: ['21 grams', '50 grams', '85 grams (or 20 dinars)', '100 grams'], correctAnswerIndex: 2, explanation: 'The Nisab for gold was set by the Prophet as 20 mithqals/dinars, which equals approximately 85 grams of pure gold.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_35', question: 'What is "Fiqh al-Maqasid"?', options: ['Traditional jurisprudence', 'Jurisprudence that interprets rulings based on the overarching objectives and wisdoms of Sharia', 'Modern literalism', 'Abolishing old laws'], correctAnswerIndex: 1, explanation: 'Fiqh al-Maqasid focuses on the "why" behind the law, ensuring legal rulings fulfill the broader goals of justice and preservation.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_36', question: 'Which Surah contains the detailed narrative of Dhu\'l-Qarnayn?', options: ['Surah Al-Kahf', 'Surah Yusuf', 'Surah Luqman', 'Surah As-Safat'], correctAnswerIndex: 0, explanation: 'Surah Al-Kahf (Chapter 18) relates the story of Dhu\'l-Qarnayn and his building of a great barrier.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_37', question: 'What is "Usul Al-Fiqh"?', options: ['The body of Islamic laws', 'The study of the origins, principles, and methodology of deriving Islamic jurisprudence', 'The compilation of Hadith', 'Biographies of jurists'], correctAnswerIndex: 1, explanation: 'Usul Al-Fiqh is the methodology and framework used by scholars to extract practical laws from primary texts.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_38', question: 'What is "Gharar" in Islamic commercial law?', options: ['A fixed profit', 'Interest or Usury', 'Excessive uncertainty, ambiguity, or deception in a contract', 'Charitable giving'], correctAnswerIndex: 2, explanation: 'Gharar refers to hazardous or ambiguous sales where the details of the item, price, or delivery are highly uncertain.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_39', question: 'What is a "Mursal" hadith?', options: ['An authenticated hadith', 'A hadith where a Tabi\'i (Successor) quotes the Prophet directly, omitting the Companion', 'A forged hadith', 'A famously repeated hadith'], correctAnswerIndex: 1, explanation: 'In a Mursal hadith, the link between the Successor and the Prophet (the Companion) is missing from the chain.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_40', question: 'What is "Riba al-Fadl"?', options: ['Interest charged on delayed loans', 'The simultaneous exchange of identical ribawi commodities (like gold for gold) in unequal amounts', 'A tax on agricultural goods', 'Profit from trading currency across borders'], correctAnswerIndex: 1, explanation: 'Riba al-Fadl occurs when specific identical goods (like wheat, dates, gold) are exchanged on the spot in unequal quantities.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_41', question: 'Who is widely considered the founder of the science of Usul Al-Fiqh as an independent documented discipline?', options: ['Imam Abu Hanifa', 'Imam Malik', 'Imam Al-Shafi\'i', 'Imam Ahmad ibn Hanbal'], correctAnswerIndex: 2, explanation: 'Imam Al-Shafi\'i systematized the methodology of deriving Islamic law in his foundational book, "Al-Risala".', difficulty: 'hard'),
      QuizQuestion(id: 'hard_42', question: 'Which Surah is also called "The Exposer" (Al-Fadhihah) because it exposed the hypocrites of Medina?', options: ['Surah Al-Anfal', 'Surah At-Tawbah', 'Surah An-Noor', 'Surah Al-Ahzab'], correctAnswerIndex: 1, explanation: 'Surah At-Tawbah severely reprimanded and exposed the hidden plots of the hypocrites during the Tabuk expedition.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_43', question: 'Which companion suggested the military tactic of digging a trench in the Battle of Al-Ahzab?', options: ['Abu Ubaidah ibn Al-Jarrah', 'Sa\'d ibn Mu\'adh', 'Salman Al-Farsi', 'Ammar ibn Yasir'], correctAnswerIndex: 2, explanation: 'Salman the Persian introduced the defensive trench strategy, which was unknown to the Arabs at the time.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_44', question: 'In the Islamic science of inheritance, what is "Al-Awl"?', options: ['When fixed shares exceed the total estate, so the base is increased, proportionally reducing each share', 'When fixed shares leave a remainder that is given to charity', 'The complete exclusion of a distant relative', 'Equal distribution regardless of gender'], correctAnswerIndex: 0, explanation: 'Al-Awl is a mathematical adjustment applied when the sum of fractional shares totals more than 100% of the estate.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_45', question: 'What is the primary focus of the scholarly science known as "Al-Jarh wa At-Ta\'deel"?', options: ['Explaining difficult Quranic vocabulary', 'Critiquing and evaluating the reliability, memory, and character of Hadith narrators', 'Issuing modern fatwas', 'Reconciling differences in prayer formats'], correctAnswerIndex: 1, explanation: 'This critical science validates (Ta\'deel) or invalidates (Jarh) narrators to ensure only accurate hadiths are accepted.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_46', question: 'Who was officially tasked by Caliph Abu Bakr to lead the initial compilation of the Quran into one master volume?', options: ['Ali ibn Abi Talib', 'Uthman ibn Affan', 'Zayd ibn Thabit', 'Abdullah ibn Masud'], correctAnswerIndex: 2, explanation: 'Zayd ibn Thabit, one of the primary scribes of revelation, was heavily trusted by Abu Bakr for this monumental task.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_47', question: 'What does the term "Ahruf" refer to in the context of the Quran?', options: ['Calligraphic styles', 'The seven divinely permitted dialects/modes in which the Quran was revealed', 'The rules of Tajweed', 'Chapters revealed in Mecca'], correctAnswerIndex: 1, explanation: 'The Prophet stated the Quran was revealed in seven "Ahruf" to accommodate the various dialects of Arabian tribes.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_48', question: 'What is "Idgham" in the rules of Tajweed?', options: ['Clear pronunciation', 'The merging of a non-voweled letter into a voweled letter, making them one emphasized letter', 'Hiding a sound in the nose', 'Stopping at the end of a verse'], correctAnswerIndex: 1, explanation: 'Idgham means assimilation or merging, commonly applied to a silent Nun merging into letters like Yaa or Waw.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_49', question: 'In Hadith terminology, what is a "Mu\'allaq" (Suspended) hadith?', options: ['A hadith lacking a chain altogether', 'A hadith missing one or more consecutive narrators from the beginning of its chain', 'A hadith narrated by a known liar', 'A hadith that has not been acted upon'], correctAnswerIndex: 1, explanation: 'A Mu\'allaq hadith occurs when the collector (like Al-Bukhari) omits the first narrator(s) on his end of the chain.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_50', question: 'Which companion was uniquely titled the "Trustee of this Ummah" (Ameen al-Ummah) by the Prophet?', options: ['Abu Bakr As-Siddiq', 'Umar ibn Al-Khattab', 'Abu Ubaidah ibn al-Jarrah', 'Zubayr ibn al-Awwam'], correctAnswerIndex: 2, explanation: 'Abu Ubaidah was given this specific title due to his profound trustworthiness and unshakeable character.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_51', question: 'In Fiqh, what is the term for water that has changed in color, taste, or smell due to impurities?', options: ['Ma\' Mutlaq', 'Ma\' Musta\'mal', 'Ma\' Najas', 'Ma\' Tahir'], correctAnswerIndex: 2, explanation: 'Ma\' Najas is impure water that cannot be used for Wudu or Ghusl due to being mixed with a najasah (impurity).', difficulty: 'hard'),
      QuizQuestion(id: 'hard_52', question: 'What is "Tawriyah" in Islamic ethics?', options: ['Blatant lying', 'Speaking words that are technically true but convey a different meaning to the listener, used to avoid direct lying in difficult situations', 'Swearing an oath', 'Breaking a promise'], correctAnswerIndex: 1, explanation: 'Tawriyah is permissible in certain circumstances to protect life or prevent harm without resorting to an outright lie.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_53', question: 'Which companion was given the honor that his single testimony was legally equal to the testimony of two men?', options: ['Khuzaymah ibn Thabit', 'Ammar ibn Yasir', 'Bilal ibn Rabah', 'Abu Dharr Al-Ghifari'], correctAnswerIndex: 0, explanation: 'The Prophet made Khuzaymah\'s testimony equal to two men after Khuzaymah testified for the Prophet in a dispute simply based on faith.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_54', question: 'What is "Muwalah" in the context of Wudu (ablution)?', options: ['Intention to purify', 'Washing the prescribed body parts in uninterrupted succession before the previous part dries', 'Wiping over socks', 'Using the Siwak'], correctAnswerIndex: 1, explanation: 'Muwalah (continuity) is an essential element in some schools of Fiqh, meaning one should not take a long break during Wudu.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_55', question: 'What was the primary trigger for the Ridda (Apostasy) Wars during Abu Bakr\'s caliphate?', options: ['Invasion by Rome', 'Several tribes openly refusing to pay Zakat to the central state', 'A dispute over borders', 'Rejection of the Hijri calendar'], correctAnswerIndex: 1, explanation: 'While some falsely claimed prophethood, a major cause was tribes claiming Zakat was only owed to the Prophet, not Abu Bakr.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_56', question: 'Which battle against the Persians is famously known as the "Battle of the Bridge"?', options: ['Battle of Al-Qadisiyyah', 'Battle of the Bridge (Waq\'at al-Jisr)', 'Battle of Nahavand', 'Battle of Yarmouk'], correctAnswerIndex: 1, explanation: 'Led by Abu Ubayd al-Thaqafi, this was a rare, severe defeat for the Muslims due to crossing a bridge into a tactical disadvantage.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_57', question: 'What does "Urf" mean as a secondary source in Islamic Jurisprudence?', options: ['Consensus of scholars', 'The established customary practice or common knowledge of a society that does not contradict Sharia', 'Analogy', 'Public interest'], correctAnswerIndex: 1, explanation: 'Urf allows Islamic law to accommodate local customs and traditions in matters like business contracts or marriage gifts.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_58', question: 'Who was the first Caliph to establish a systematic Bait al-Mal (Public Treasury) and formal state registries (Diwan)?', options: ['Abu Bakr', 'Umar ibn Al-Khattab', 'Uthman ibn Affan', 'Ali ibn Abi Talib'], correctAnswerIndex: 1, explanation: 'Umar instituted complex administrative systems, including pensions and organized treasuries, to manage the expanding empire.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_59', question: 'Which Surah was revealed immediately on the journey back from the Treaty of Hudaybiyyah, declaring it a "manifest victory"?', options: ['Surah Al-Fath', 'Surah Muhammad', 'Surah Al-Hujurat', 'Surah Qaf'], correctAnswerIndex: 0, explanation: 'Surah Al-Fath (The Victory) was revealed to reassure the companions that the seemingly disadvantageous treaty was actually a triumph.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_60', question: 'In the science of Hadith, what is "Tadlis"?', options: ['Memorization of chains', 'A narrator concealing a defect in the chain, often by implying they heard directly from a contemporary they did not meet', 'Writing hadiths down', 'Grading a hadith as fabricated'], correctAnswerIndex: 1, explanation: 'Tadlis is a subtle flaw where a narrator uses ambiguous wording (like "on the authority of") to skip a weak link without explicitly lying.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_61', question: 'What is the severe expiation (Kaffarah) for deliberately breaking a mandatory Ramadan fast by marital relations?', options: ['Fasting 3 days', 'Freeing a slave, OR fasting 60 consecutive days, OR feeding 60 poor people', 'Paying a small fine', 'Making up the single day only'], correctAnswerIndex: 1, explanation: 'This heavy Kaffarah is applied in strict order of ability to emphasize the sanctity of the fasting month.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_62', question: 'What is "Istihsan" primarily used in the Hanafi school of Fiqh?', options: ['Strict literalism', 'Juristic preference: abandoning a strict legal analogy for a more equitable or practical ruling', 'Consensus of Medina', 'Rejection of Hadith'], correctAnswerIndex: 1, explanation: 'Istihsan allows a jurist to seek equity and avoid hardship when applying a strict Qiyas (analogy) would lead to an unfair outcome.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_63', question: 'Which classical scholar authored "Al-Muwatta", the foundational text of his respective school of Fiqh?', options: ['Imam Abu Hanifa', 'Imam Malik ibn Anas', 'Imam Al-Shafi\'i', 'Imam Ahmad ibn Hanbal'], correctAnswerIndex: 1, explanation: 'Imam Malik wrote Al-Muwatta, serving as both an early collection of authentic hadiths and a record of the practices of the people of Medina.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_64', question: 'What is the condition of "Hawl" concerning the payment of Zakat?', options: ['Being free from debt', 'The wealth must meet or exceed the Nisab', 'The wealth must be in possession for one complete lunar year', 'The wealth must be gold'], correctAnswerIndex: 2, explanation: 'Zakat is only due on accumulated wealth that has remained above the minimum threshold (Nisab) for an entire lunar year (Hawl).', difficulty: 'hard'),
      QuizQuestion(id: 'hard_65', question: 'What is "Sujud al-Sahw"?', options: ['Prostration of recitation', 'Two prostrations of forgetfulness performed at the end of the prayer to compensate for minor mistakes', 'Prostration of thankfulness', 'The prostration in the grave'], correctAnswerIndex: 1, explanation: 'If a worshipper adds, omits, or doubts a part of the prayer, Sujud al-Sahw is performed to amend the prayer.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_66', question: 'In the Islamic inheritance system, who are the "Ashab al-Furud"?', options: ['Male relatives only', 'Heirs who have specific, fixed fractional shares prescribed in the Quran (e.g., 1/2, 1/4, 1/8)', 'Charitable organizations', 'Adopted children'], correctAnswerIndex: 1, explanation: 'Ashab al-Furud are the primary heirs whose exact portions are divinely mandated before the remainder goes to the \'Asabah (residuary heirs).', difficulty: 'hard'),
      QuizQuestion(id: 'hard_67', question: 'Which Qira\'ah (Quranic recitation style) is the most widely recited in the world today?', options: ['Warsh \'an Nafi\'', 'Qalun \'an Nafi\'', 'Hafs \'an \'Asim', 'Al-Duri \'an Abu Amr'], correctAnswerIndex: 2, explanation: 'The recitation of Hafs transmitted from Imam \'Asim of Kufa is the standard print and recitation for the vast majority of Muslims.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_68', question: 'What is "Shirk al-Asghar" (Minor Shirk)?', options: ['Worshipping idols', 'Hidden polytheism, such as Riya (showing off good deeds for human praise)', 'Denying the existence of Allah', 'Insulting a Prophet'], correctAnswerIndex: 1, explanation: 'Minor Shirk does not take one out of the fold of Islam but severely nullifies the reward of the deed done for show rather than for Allah.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_69', question: 'What is "Ikhfa" in the rules of Tajweed?', options: ['Clear pronunciation of Nun', 'Hiding the sound of the Nun Sakinah or Tanween by creating a nasal sound (Ghunnah)', 'Bouncing the letter', 'Merging the letters completely'], correctAnswerIndex: 1, explanation: 'Ikhfa involves a state between clear pronunciation (Izhar) and merging (Idgham), retaining a nasal sound.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_70', question: 'Which companion famously defended the Prophet in the Battle of Uhud, taking numerous wounds and catching arrows with his bare hands?', options: ['Talhah ibn Ubaydullah', 'Sa\'d ibn Abi Waqqas', 'Abu Dujana', 'Ali ibn Abi Talib'], correctAnswerIndex: 0, explanation: 'Talhah fought fiercely to protect the Prophet, resulting in a paralyzed hand and the Prophet calling him a "living martyr."', difficulty: 'hard'),
      QuizQuestion(id: 'hard_71', question: 'What is "Al-Wala\' wal-Bara\'" in Islamic theology?', options: ['The balance of fear and hope', 'Loyalty and love for Allah and believers, and disavowal of falsehood and oppression', 'Predestination and free will', 'The physical and spiritual purification'], correctAnswerIndex: 1, explanation: 'This doctrine focuses on internal allegiances, urging Muslims to align their love and disavowal purely with the commands of Allah.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_72', question: 'Which historic event occurred as a direct military response to the breach of the Treaty of Hudaybiyyah by the Quraysh?', options: ['Battle of Tabuk', 'Battle of Hunayn', 'The Conquest of Mecca (Fath Makkah)', 'Battle of Mut\'ah'], correctAnswerIndex: 2, explanation: 'When Quraysh allies attacked Muslim allies, the treaty was voided, leading the Prophet to march on Mecca in 8 AH.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_73', question: 'In Hadith grading, what is a "Munqati\'" hadith?', options: ['A continuously linked chain', 'A hadith with a broken chain at any place (missing a narrator), except the Successor level', 'A perfectly authentic hadith', 'A heavily corroborated hadith'], correctAnswerIndex: 1, explanation: 'A Munqati\' (severed) hadith lacks continuity, making it generally classified as weak due to the unknown missing narrator.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_74', question: 'What is "Waqf" in Islamic law?', options: ['A tax on land', 'A permanent, inalienable religious or charitable endowment of property or assets', 'A divorce proceeding', 'A temporary lease'], correctAnswerIndex: 1, explanation: 'Waqf ensures the corpus of a property is held intact while its generated profits or usages are directed to a charitable cause indefinitely.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_75', question: 'Which prominent scholar authored "Al-Mustasfa min \'Ilm al-Usul", a monumental work in Usul al-Fiqh?', options: ['Ibn Rushd', 'Al-Ghazali', 'Al-Shatibi', 'Ibn Hazm'], correctAnswerIndex: 1, explanation: 'Abu Hamid al-Ghazali authored Al-Mustasfa, which is considered one of the four foundational pillars of Usul al-Fiqh literature.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_76', question: 'In Islamic finance, what describes a "Murabaha" transaction?', options: ['An interest-bearing loan', 'A partnership where one provides capital and the other labor', 'A cost-plus-profit sale where the exact cost and markup are disclosed to the buyer', 'A gambling contract'], correctAnswerIndex: 2, explanation: 'Murabaha is an incredibly common Islamic financing structure acting as a transparent sale rather than an interest-based loan.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_77', question: 'Who was the only companion to narrate a hadith about the Dajjal (from a Christian convert named Tamim Al-Dari) directly to the Prophet, which the Prophet then narrated to the congregation?', options: ['Umar ibn Al-Khattab', 'Abu Hurairah', 'Fatimah bint Qays (reporting the Prophet\'s narration)', 'Anas ibn Malik'], correctAnswerIndex: 2, explanation: 'In a unique inversion, the Prophet narrated the story of the Dajjal and the Beast from the companion Tamim Al-Dari to the congregation, recorded famously in the Hadith of Al-Jassasah.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_78', question: 'What is the specific legal term for a woman\'s waiting period after a divorce or the death of her husband?', options: ['Khula', 'Mahr', '\'Iddah', 'Zihar'], correctAnswerIndex: 2, explanation: 'The \'Iddah is an obligatory waiting period that ensures there is no pregnancy and provides a window for reconciliation in revocable divorces.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_79', question: 'According to the Quran, which Prophet\'s people were destroyed by an awful cry or blast (Al-Sayhah)?', options: ['Prophet Nuh (Noah)', 'Prophet Lut (Lot)', 'Prophet Salih (People of Thamud)', 'Prophet Yunus (Jonah)'], correctAnswerIndex: 2, explanation: 'The people of Thamud were destroyed by a devastating sonic blast (Al-Sayhah) after they killed the miraculous she-camel.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_80', question: 'Who was the overarching military commander for the Muslims at the decisive Battle of Al-Qadisiyyah against the Persians?', options: ['Khalid ibn Al-Walid', 'Sa\'d ibn Abi Waqqas', 'Amr ibn al-Aas', 'Abu Ubaidah ibn al-Jarrah'], correctAnswerIndex: 1, explanation: 'Sa\'d ibn Abi Waqqas directed the battle despite being severely ill, leading to one of the most critical victories in Islamic history.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_81', question: 'Which of the following is NOT a necessary condition for a hadith to be classified strictly as "Sahih"?', options: ['Continuity of the chain', 'Upright character of narrators', 'Narrated by at least ten companions', 'Absence of hidden defects (\'Illah)'], correctAnswerIndex: 2, explanation: 'A Sahih hadith does not need ten companions (that is a Mutawatir hadith). A Sahih hadith can technically be narrated by a single reliable chain.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_82', question: 'What is "Shuf\'a" in Islamic property and contract law?', options: ['A dowry payment', 'The right of pre-emption given to a co-owner or neighbor to buy property before it is sold to a stranger', 'A charitable trust', 'An invalid contract'], correctAnswerIndex: 1, explanation: 'Shuf\'a protects partners and neighbors from the introduction of an unwanted stranger into their shared property or immediate vicinity.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_83', question: 'What does the term "Mawali" refer to in the context of early Islamic history?', options: ['Military generals', 'Non-Arab Muslims who became affiliated clients to an Arab tribe', 'The inhabitants of Mecca', 'Tax collectors'], correctAnswerIndex: 1, explanation: 'As the empire expanded, non-Arabs embraced Islam and integrated into the societal structure as Mawali (clients/affiliates) of existing tribes.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_84', question: 'What is "Tayamun" in the Sunnah?', options: ['Fasting on alternate days', 'The practice of starting from the right side in pure and noble actions (like putting on shoes or entering a mosque)', 'Praying at night', 'Giving charity secretly'], correctAnswerIndex: 1, explanation: 'The Prophet favored starting from the right (Tayamun) in all good things, leaving the left for the removal of impurities.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_85', question: 'In Hadith grading, what primarily distinguishes a "Hasan" (Good) hadith from a "Sahih" (Authentic) hadith?', options: ['A Hasan hadith has a broken chain', 'A Hasan hadith is fabricated', 'In a Hasan hadith, the narrator\'s precision/memory (Dabt) is slightly less than that required for Sahih', 'A Hasan hadith contradicts the Quran'], correctAnswerIndex: 2, explanation: 'A Hasan hadith is perfectly valid for deriving laws, but its narrators are known to be slightly less rigorous in their exact memorization than Sahih narrators.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_86', question: 'Which Surah explicitly mentions the adoptive son of Prophet Muhammad, Zayd, by name?', options: ['Surah Al-Baqarah', 'Surah Al-Ahzab', 'Surah Muhammad', 'Surah At-Talaq'], correctAnswerIndex: 1, explanation: 'Surah Al-Ahzab (33:37) is the only place in the Quran where a companion (Zayd ibn Harithah) is mentioned explicitly by name.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_87', question: 'What is "Mudarabah" in Islamic finance?', options: ['Charging a late fee', 'A partnership where one party provides the capital and the other provides the labor/expertise', 'Renting out agricultural land', 'Selling a debt'], correctAnswerIndex: 1, explanation: 'In a Mudarabah contract, profits are shared at a pre-agreed ratio, but financial losses are borne solely by the capital provider.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_88', question: 'Which companion was sent as a spy into the coalition enemy camp during the freezing winds of the Battle of the Trench?', options: ['Ali ibn Abi Talib', 'Zubayr ibn al-Awwam', 'Hudhayfah ibn al-Yaman', 'Sa\'d ibn Mu\'adh'], correctAnswerIndex: 2, explanation: 'Hudhayfah was tasked by the Prophet with this highly dangerous mission to gather intelligence without breaking his cover.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_89', question: 'What does the foundational Fiqh maxim "Al-Yaqeen la yazulu bil-Shakk" translate to?', options: ['Hardship brings ease', 'Harm must be removed', 'Certainty is not overruled by doubt', 'Custom is authoritative'], correctAnswerIndex: 2, explanation: 'This maxim means that a confirmed state (like having Wudu) cannot be nullified by mere suspicion or doubt.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_90', question: 'Which classical scholar is famously known as the "Sheikh al-Islam" and authored the massive "Majmu\' al-Fatawa"?', options: ['Ibn Hajar Al-Asqalani', 'Ibn Taymiyyah', 'Imam Al-Nawawi', 'Ibn Qayyim Al-Jawziyya'], correctAnswerIndex: 1, explanation: 'Taqi ad-Din Ahmad ibn Taymiyyah was a profoundly influential 13th/14th-century scholar known for his prolific writings and strict reliance on early texts.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_91', question: 'In Usul al-Fiqh, what is "Ijma\' Sukuti"?', options: ['Verbal consensus', 'Consensus established by the silence of all scholars upon knowing of a ruling, implying tacit approval', 'Consensus of the first generation only', 'Consensus of Medina'], correctAnswerIndex: 1, explanation: 'Ijma\' Sukuti (tacit consensus) occurs when a ruling is made public and no scholar objects to it over a reasonable period.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_92', question: 'What is "Khamr" in Islamic jurisprudence?', options: ['Any type of food', 'Strictly wine made from grapes', 'Any substance that intoxicates and clouds the intellect, regardless of its source', 'Gambling'], correctAnswerIndex: 2, explanation: 'The Prophet defined Khamr broadly: "Every intoxicant is Khamr, and every Khamr is Haram."', difficulty: 'hard'),
      QuizQuestion(id: 'hard_93', question: 'What is the term for the expiation paid for accidentally killing a person in Islamic law?', options: ['Qisas', 'Diyyah (Blood money)', 'Kaffarah', 'Zakat'], correctAnswerIndex: 1, explanation: 'Diyyah is the financial compensation paid to the victim\'s family in cases of unintentional death or injury.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_94', question: 'Which of the following describes a "Hadith Qudsi"?', options: ['A hadith narrated by angels', 'A hadith where the meaning is from Allah, but the wording is from the Prophet', 'A chapter of the Quran', 'A fabricated hadith'], correctAnswerIndex: 1, explanation: 'Unlike the Quran (where both meaning and wording are from Allah), a Hadith Qudsi is a divine message phrased in the Prophet\'s own words.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_95', question: 'What was the first formal treaty between Muslims and non-Muslims that established Medina as a pluralistic state?', options: ['Treaty of Hudaybiyyah', 'Constitution of Medina (Sahifat al-Madinah)', 'Treaty of Najran', 'Pledge of Aqabah'], correctAnswerIndex: 1, explanation: 'The Constitution of Medina established mutual defense and civil rights among Muslims, Jews, and allied tribes.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_96', question: 'Which companion compiled the most comprehensive and authoritative commentary (Tafsir) and history in early Islam, earning the title "Imam of the Mufassirin"?', options: ['Abdullah ibn Masud', 'Ibn Jarir Al-Tabari', 'Abdullah ibn Abbas', 'Ibn Kathir'], correctAnswerIndex: 1, explanation: 'Muhammad ibn Jarir Al-Tabari compiled "Jami\' al-Bayan", the most significant early Tafsir relying on chains of narration.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_97', question: 'What is the meaning of "Qalqalah" in Tajweed?', options: ['Merging sounds', 'Stretching vowels', 'Creating an echoing or bouncing sound on certain consonant letters when they are unvoweled (Sakin)', 'Stopping abruptly'], correctAnswerIndex: 2, explanation: 'Qalqalah applies to the letters Qaf, Ta, Ba, Jim, and Dal (قطب جد) to ensure they are heard clearly when they carry a Sukun.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_98', question: 'Which battle is unique because the Prophet commanded three commanders in succession (Zayd, Ja\'far, and Abdullah) who were all martyred?', options: ['Battle of Badr', 'Battle of Uhud', 'Battle of Mut\'ah', 'Battle of Hunayn'], correctAnswerIndex: 2, explanation: 'The Battle of Mut\'ah against the Byzantine forces saw all three appointed commanders fall before Khalid ibn Al-Walid took charge.', difficulty: 'hard'),
      QuizQuestion(id: 'hard_99', question: 'In the methodology of Hadith, who are the "Al-Kutub al-Sittah" (The Six Books) authored by?', options: ['Bukhari, Muslim, Abu Dawood, Tirmidhi, An-Nasa\'i, Ibn Majah', 'Malik, Shafi\'i, Ahmad, Abu Hanifa, Bukhari, Muslim', 'Tabari, Qurtubi, Ibn Kathir, Suyuti, Razi, Baghawi', 'Bukhari, Muslim, Hakim, Bayhaqi, Darimi, Daraqutni'], correctAnswerIndex: 0, explanation: 'These six collections form the canonical core of Sunni Hadith literature, widely accepted for their rigorous standards.', difficulty: 'hard'),
