    QuizQuestion(id: 'mid_14', question: 'كم عدد أسماء الله الحسنى التي يتم التأكيد عليها تقليديًا؟', options: ['50', '99', '150', '200'], correctAnswerIndex: 1, explanation: 'على الرغم من أن لله أسماء كثيرة، إلا أن 99 اسمًا محددة مشهورة في التراث الإسلامي والحديث.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_15', question: 'ما هي غزوة بدر؟', options: ['موقع في المدينة', 'أول معركة كبرى بين المسلمين وقريش', 'طريق تجاري', 'بئر ماء'], correctAnswerIndex: 1, explanation: 'غزوة بدر (2 هـ / 624 م) كانت أول انتصار عسكري كبير وحاسم للمسلمين الأوائل ضد قريش.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_16', question: 'ماذا تعني كلمة "الأمة"؟', options: ['الأم', 'الأمة أو المجتمع', 'الجدة', 'القبيلة'], correctAnswerIndex: 1, explanation: 'تشير الأمة إلى المجتمع الإسلامي العالمي الموحد بإيمانه بالإسلام.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_17', question: 'ما هي أركان الإيمان الستة؟', options: ['الله، القرآن، الصلاة، الصوم، الزكاة، الحج', 'الإيمان بالله، الملائكة، الكتب، الرسل، اليوم الآخر، والقدر', 'الأركان الخمسة فقط', 'أسماء الله فقط'], correctAnswerIndex: 1, explanation: 'أركان الإيمان الستة تشكل الأساس اللاهوتي للعقيدة الإسلامية.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_18', question: 'من هي الزوجة الأولى للنبي إبراهيم؟', options: ['سارة', 'هاجر', 'قطورة', 'ليئة'], correctAnswerIndex: 0, explanation: 'سارة كانت الزوجة الأولى للنبي إبراهيم وأم النبي إسحاق.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_19', question: 'بماذا يُعرف شهر محرم الإسلامي بشكل كبير؟', options: ['كونه شهر الصيام', 'كونه شهر الحج', 'كونه شهرًا حرامًا يحتوي على يوم عاشوراء', 'كونه شهر العيد'], correctAnswerIndex: 2, explanation: 'محرم هو الشهر الأول من السنة الإسلامية، وهو شهر حرام، ويحتوي على يوم عاشوراء التاريخي (10 محرم).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_20', question: 'ما هي زكاة الفطر؟', options: ['ضريبة على الممتلكات الزراعية', 'صدقة تُعطى في نهاية رمضان قبل صلاة العيد', 'صدقة شهرية', 'صدقة للمسافرين فقط'], correctAnswerIndex: 1, explanation: 'زكاة الفطر هي صدقة واجبة من الطعام تُعطى قبل عيد الفطر ليتمكن الجميع من الاحتفال.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_21', question: 'وفقًا للقرآن، كم عدد الملائكة الذين سيحملون عرش الله يوم القيامة؟', options: ['4', '6', '8', '10'], correctAnswerIndex: 2, explanation: 'تذكر سورة الحاقة (69:17) أن ثمانية ملائكة سيحملون عرش الله في ذلك اليوم.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_22', question: 'ما اسم الملك الذي نزل بالوحي على النبي محمد؟', options: ['جبريل', 'ميكائيل', 'إسرافيل', 'مالك'], correctAnswerIndex: 0, explanation: 'الملك جبريل موكل بإبلاغ وحي الله إلى جميع الأنبياء.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_23', question: 'وفقًا للحديث، ما هو أول عمل يُحاسب عليه العبد يوم القيامة؟', options: ['الإيمان', 'الصلاة', 'الزكاة', 'الصوم'], correctAnswerIndex: 1, explanation: 'قال النبي إن أول عمل يُحاسب عليه العبد يوم القيامة هو صلاته.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_24', question: 'كم مرة تظهر عبارة "يا أيها الذين آمنوا" في القرآن؟', options: ['50', '75', '89', '114'], correctAnswerIndex: 2, explanation: 'هذه العبارة المحددة التي تخاطب المؤمنين مباشرة تظهر بالضبط 89 مرة في القرآن.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_25', question: 'أي صحابي يُعرف بلقب "ترجمان القرآن"؟', options: ['علي بن أبي طالب', 'عبد الله بن مسعود', 'عبد الله بن عباس', 'أبي بن كعب'], correctAnswerIndex: 2, explanation: 'عبد الله بن عباس كان صحابيًا صغيرًا دعا له النبي بالفهم العميق للدين، فنال هذا اللقب.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_26', question: 'كم مرة أدى النبي محمد فريضة الحج؟', options: ['مرة واحدة', 'مرتين', 'ثلاث مرات', 'خمس مرات'], correctAnswerIndex: 0, explanation: 'أدى النبي محمد الحج مرة واحدة فقط في حياته في 10 هـ، وتُعرف بحجة الوداع.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_27', question: 'ما هي الاستخارة؟', options: ['طقس صيام', 'صلاة خاصة لطلب التوجيه من الله في اتخاذ قرار', 'طقس حج', 'نوع من الصدقة'], correctAnswerIndex: 1, explanation: 'الاستخارة هي صلاة ركعتين يتبعها دعاء محدد يطلب فيه العبد من الله التوجيه في اختيار ما.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_28', question: 'ماذا تسمى الملائكة التي تسجل أعمال الإنسان الحسنة والسيئة؟', options: ['الحفظة', 'منكر ونكير', 'الكرام الكاتبين', 'المعقبات'], correctAnswerIndex: 2, explanation: 'الكرام الكاتبين (الكتبة الكرام) يجلسون على كتفي الإنسان الأيمن والأيسر لتسجيل أعماله.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_29', question: 'ماذا يسمى العذاب في القبر بالعربية؟', options: ['عذاب القبر', 'الجحيم', 'سقر', 'لظى'], correctAnswerIndex: 0, explanation: 'يشير عذاب القبر إلى الفتن والعقاب في القبر، وهو مفهوم مذكور في التعاليم الإسلامية.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_30', question: 'كم عدد الآيات في سورة البقرة، أطول سورة في القرآن؟', options: ['100', '200', '286', '300'], correctAnswerIndex: 2, explanation: 'تحتوي سورة البقرة على 286 آية، مما يجعلها أطول سورة في القرآن.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_31', question: 'ماذا تعني "الصدقة الجارية"؟', options: ['صدقة لمرة واحدة', 'صدقة مستمرة يستمر نفعها بعد موت الشخص', 'صدقة إجبارية', 'صدقة الأعياد'], correctAnswerIndex: 1, explanation: 'الصدقة الجارية تشمل أعمالًا مثل بناء بئر أو مسجد أو مدرسة، مما يولد أجرًا مستمرًا حتى بعد الموت.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_32', question: 'أي صحابية وزوجة للنبي روت أكبر عدد من الأحاديث؟', options: ['عائشة بنت أبي بكر', 'فاطمة بنت محمد', 'حفصة بنت عمر', 'خديجة بنت خويلد'], correctAnswerIndex: 0, explanation: 'روت عائشة أكثر من 2200 حديث وكانت من أبرز علماء الإسلام الأوائل.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_33', question: 'ما اسم المعركة التي حفر فيها المسلمون خندقًا كبيرًا للدفاع عن المدينة؟', options: ['غزوة بدر', 'غزوة أحد', 'غزوة الخندق', 'غزوة حنين'], correctAnswerIndex: 2, explanation: 'غزوة الخندق (الأحزاب) تضمنت الدفاع عن المدينة باستخدام خندق اقترحه سلمان الفارسي.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_34', question: 'أي ملك موكل بالنفخ في الصور للإعلان عن يوم القيامة؟', options: ['جبريل', 'ميكائيل', 'إسرافيل', 'مالك'], correctAnswerIndex: 2, explanation: 'الملك إسرافيل سينفخ في الصور مرتين: مرة لإنهاء العالم، ومرة لإحياء الموتى.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_35', question: 'ما هو مفهوم "التوكل" في الإسلام؟', options: ['صلاة واجبة', 'الاعتماد الكامل على الله بعد بذل الجهد', 'الصيام أثناء السفر', 'الصدقة السرية'], correctAnswerIndex: 1, explanation: 'التوكل يعني أن تربط جملک أولاً، ثم تضع ثقتك واعتمادك الكامل على خطة الله.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_36', question: 'كم عدد الكبائر المهلكات التي ذكرها النبي صراحة في حديث شهير؟', options: ['3', '5', '7', '9'], correctAnswerIndex: 2, explanation: 'ذكر النبي 7 كبائر مهلكات، منها الشرك، والسحر، والقتل، وأكل مال اليتيم، والربا، والتولي يوم الزحف، وقذف المحصنات.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_37', question: 'ما هو مفهوم "التقوى" في الإسلام؟', options: ['الخوف من الأعداء', 'التقوى والبر والوعي بالله', 'صلاة الجماعة', 'الصوم التطوعي'], correctAnswerIndex: 1, explanation: 'التقوى هي الوعي الداخلي بالله، الذي يدفع الشخص لفعل الخير وتجنب الشر.', difficulty: 'medium'),
