  // --- FRENCH: EASY ---
  List<QuizQuestion> _getEasyQuestionsFr() {
  return [
    QuizQuestion(id: 'easy_1', question: 'Combien de fois par jour les musulmans prient-ils ?', options: ['3 fois', '4 fois', '5 fois', '6 fois'], correctAnswerIndex: 2, explanation: 'Les musulmans sont tenus de prier 5 fois par jour : Fajr, Dhohr, Asr, Maghrib et Icha.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_2', question: 'Comment s\'appelle le mois de jeûne islamique ?', options: ['Shawwal', 'Ramadan', 'Muharram', 'Dhul-Hijjah'], correctAnswerIndex: 1, explanation: 'Le Ramadan est le neuvième mois du calendrier lunaire islamique durant lequel les musulmans jeûnent de l\'aube au coucher du soleil.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_3', question: 'Qui est le dernier Prophète en Islam ?', options: ['Ibrahim', 'Moussa', 'Muhammad', 'Issa'], correctAnswerIndex: 2, explanation: 'Le Prophète Muhammad (paix et bénédictions sur lui) est le dernier messager envoyé par Allah.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_4', question: 'Comment appelle-t-on le pèlerinage islamique ?', options: ['Omra', 'Hajj', 'Tawaf', 'Salat'], correctAnswerIndex: 1, explanation: 'Le Hajj est le pèlerinage à La Mecque, qui est l\'un des cinq piliers de l\'Islam.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_5', question: 'Combien y a-t-il de piliers de l\'Islam ?', options: ['3', '4', '5', '6'], correctAnswerIndex: 2, explanation: 'Il y a 5 piliers de l\'Islam : la Chahada, la Salat, la Zakat, le Siyam (jeûne) et le Hajj.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_6', question: 'Comment s\'appelle la profession de foi en Islam ?', options: ['Salat', 'Chahada', 'Zakat', 'Hajj'], correctAnswerIndex: 1, explanation: 'La Chahada est le credo islamique déclarant qu\'il n\'y a de dieu qu\'Allah et que Muhammad est Son messager.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_7', question: 'Dans quelle direction les musulmans se tournent-ils pour prier ?', options: ['Est', 'Ouest', 'Nord', 'Vers La Mecque (Qibla)'], correctAnswerIndex: 3, explanation: 'Les musulmans font face à la Kaaba à La Mecque pendant la prière, une direction appelée Qibla.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_8', question: 'Qui a construit la Kaaba ?', options: ['Prophète Moussa', 'Prophète Ibrahim et Ismail', 'Prophète Muhammad', 'Prophète Souleymane'], correctAnswerIndex: 1, explanation: 'Selon la tradition islamique, le Prophète Ibrahim et son fils Ismail ont construit la Kaaba.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_9', question: 'Comment appelle-t-on l\'aumône obligatoire en Islam ?', options: ['Siyam', 'Zakat', 'Hajj', 'Tawaf'], correctAnswerIndex: 1, explanation: 'La Zakat est l\'aumône obligatoire qui constitue l\'un des cinq piliers de l\'Islam.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_10', question: 'Combien de chapitres compte le Coran ?', options: ['100', '110', '114', '120'], correctAnswerIndex: 2, explanation: 'Le Coran compte 114 chapitres (Sourates) contenant chacun un ou plusieurs versets (Ayats).', difficulty: 'easy'),
    QuizQuestion(id: 'easy_11', question: 'Sur quoi est basé le calendrier islamique ?', options: ['L\'année solaire', 'L\'année lunaire', 'Solaire et lunaire', 'Les saisons'], correctAnswerIndex: 1, explanation: 'Le calendrier islamique est basé sur l\'année lunaire, également connu sous le nom de calendrier Hégirien.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_12', question: 'Combien de jours compte le Ramadan ?', options: ['25 jours', '28 jours', '29 ou 30 jours', '35 jours'], correctAnswerIndex: 2, explanation: 'Le Ramadan dure 29 ou 30 jours selon l\'observation lunaire du mois.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_13', question: 'Que signifie "Islam" ?', options: ['La paix uniquement', 'La soumission à Dieu', 'La prière', 'La croyance'], correctAnswerIndex: 1, explanation: 'Islam signifie la soumission à la volonté d\'Allah et dérive du mot arabe pour la paix et la soumission.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_14', question: 'Qui fut le premier Prophète en Islam ?', options: ['Muhammad', 'Ibrahim', 'Adam', 'Moussa'], correctAnswerIndex: 2, explanation: 'Le Prophète Adam fut le premier humain et le premier Prophète envoyé par Allah.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_15', question: 'Quelle est la salutation islamique ?', options: ['Bonjour', 'As-salamu alaikum', 'Bienvenue', 'Salut'], correctAnswerIndex: 1, explanation: 'As-salamu alaikum (Que la paix soit sur vous) est la salutation islamique, et la réponse est wa alaikum assalam.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_16', question: 'Combien de Prophètes sont mentionnés par leur nom dans le Coran ?', options: ['19', '25', '31', '50'], correctAnswerIndex: 1, explanation: '25 prophètes sont explicitement nommés dans le Coran, dont Adam, Ibrahim, Moussa, Issa et Muhammad.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_17', question: 'Quelle est la première Sourate du Coran ?', options: ['Sourate Al-Baqarah', 'Sourate Al-Fatiha', 'Sourate An-Nas', 'Sourate Al-Ikhlas'], correctAnswerIndex: 1, explanation: 'La Sourate Al-Fatiha (L\'Ouverture) est le premier chapitre du Coran et est récitée à chaque prière.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_18', question: 'Dans quelle ville est né le Prophète Muhammad ?', options: ['Médine', 'La Mecque', 'Jérusalem', 'Bagdad'], correctAnswerIndex: 1, explanation: 'Le Prophète Muhammad est né à La Mecque (Makkah) en l\'an 570 È.C.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_19', question: 'Quelle viande est interdite à la consommation en Islam ?', options: ['Bœuf', 'Porc', 'Poisson', 'Poulet'], correctAnswerIndex: 1, explanation: 'Le porc et certaines autres viandes sont interdits (Haram) en Islam comme mentionné dans le Coran.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_20', question: 'En quelle année le Prophète Muhammad a-t-il émigré à Médine ?', options: ['610 È.C.', '622 È.C.', '632 È.C.', '650 È.C.'], correctAnswerIndex: 1, explanation: 'L\'Hégire (migration) a eu lieu en 622 È.C., marquant le début du calendrier islamique.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_21', question: 'Combien de fois les musulmans tournent-ils autour de la Kaaba pendant le Hajj ?', options: ['3 fois', '5 fois', '7 fois', '10 fois'], correctAnswerIndex: 2, explanation: 'Les musulmans accomplissent la circumambulation (Tawaf) de la Kaaba 7 fois comme rituel du Hajj.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_22', question: 'Comment appelle-t-on le système juridique islamique ?', options: ['La Charia', 'Les Hadiths', 'Le Fiqh', 'L\'Ijma'], correctAnswerIndex: 0, explanation: 'La Charia (loi islamique) est le cadre juridique basé sur le Coran et la Sunnah.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_23', question: 'Qui a compilé le premier Coran écrit standardisé ?', options: ['Abou Bakr', 'Omar', 'Othman', 'Ali'], correctAnswerIndex: 2, explanation: 'Le Calife Othman a organisé la compilation du Coran standardisé pendant son règne.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_24', question: 'Que signifie le mot Hadith ?', options: ['Récitation', 'Histoires des prophètes', 'Paroles et actions du Prophète Muhammad', 'Jurisprudence'], correctAnswerIndex: 2, explanation: 'Le Hadith fait référence aux paroles, actions et approbations enregistrées du Prophète Muhammad.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_25', question: 'Que signifie "Allahu Akbar" ?', options: ['Allah est Miséricordieux', 'Allah est Unique', 'Allah est le Plus Grand', 'Allah est Pardonneur'], correctAnswerIndex: 2, explanation: 'Allahu Akbar signifie "Allah est le Plus Grand" et est fréquemment récité par les musulmans.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_26', question: 'Comment s\'appelle le repas pris avant l\'aube pendant le Ramadan ?', options: ['Souhour', 'Iftar', 'Tarawih', 'Qiyam'], correctAnswerIndex: 0, explanation: 'Le Souhour est le repas pris avant l\'aube avant de commencer le jeûne à l\'heure du Fajr.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_27', question: 'Comment appelle-t-on la rupture du jeûne au coucher du soleil ?', options: ['Souhour', 'Iftar', 'Tahajjud', 'Witr'], correctAnswerIndex: 1, explanation: 'L\'Iftar est le repas pris au coucher du soleil pour rompre le jeûne pendant le Ramadan.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_28', question: 'Combien de fois un musulman fait-il ses ablutions (Woudou) par jour ?', options: ['Une fois', 'Deux fois', 'Varie - avant chaque prière', '5 fois seulement'], correctAnswerIndex: 2, explanation: 'Les ablutions sont requises avant la prière si les ablutions précédentes sont rompues, donc le nombre varie.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_29', question: 'Comment appelle-t-on la prière nocturne spéciale pendant le Ramadan ?', options: ['Salat Al-Layl', 'Tarawih', 'Qiyam Al-Layl', 'Tahajjud'], correctAnswerIndex: 1, explanation: 'Les Tarawih sont des prières spéciales effectuées pendant les nuits de Ramadan après la prière de l\'Icha.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_30', question: 'Quelle prière obligatoire a exactement 3 Rakat (unités) ?', options: ['Fajr', 'Dhohr', 'Maghrib', 'Icha'], correctAnswerIndex: 2, explanation: 'Le Maghrib, la prière du coucher du soleil, se compose d\'exactement 3 Rakat obligatoires (Fard).', difficulty: 'easy'),
    QuizQuestion(id: 'easy_31', question: 'Combien de Rakat obligatoires (Fard) y a-t-il dans la prière du Dhohr ?', options: ['2', '3', '4', '5'], correctAnswerIndex: 2, explanation: 'La prière du Dhohr (midi) se compose de 4 Rakat obligatoires.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_32', question: 'Comment appelle-t-on le témoignage de foi en arabe ?', options: ['Takbir', 'Chahada', 'Tasbih', 'Tahlil'], correctAnswerIndex: 1, explanation: 'La Chahada est la déclaration de foi islamique témoignant de l\'unicité d\'Allah.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_33', question: 'Quel mois est considéré comme le plus sacré en Islam ?', options: ['Shawwal', 'Ramadan', 'Muharram', 'Rajab'], correctAnswerIndex: 1, explanation: 'Le Ramadan est le mois le plus sacré du calendrier islamique, où les bonnes actions sont multipliées.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_34', question: 'Comment appelle-t-on la charité spéciale donnée à la fin du Ramadan ?', options: ['Zakat al-Fitr', 'Khums', 'Waqf', 'Jizya'], correctAnswerIndex: 0, explanation: 'La Zakat al-Fitr est une charité obligatoire spéciale donnée avant la prière de l\'Aïd al-Fitr.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_35', question: 'Combien de côtés possède la Kaaba ?', options: ['2', '3', '4', '6'], correctAnswerIndex: 2, explanation: 'La Kaaba est un bâtiment en forme de cube à 4 côtés, situé à La Mecque.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_36', question: 'Qu\'est-ce que la Sadaqah en Islam ?', options: ['Charité obligatoire', 'Charité volontaire', 'Taxe', 'Punition'], correctAnswerIndex: 1, explanation: 'La Sadaqah est une charité volontaire donnée dans l\'intention d\'aider les autres et de plaire à Allah.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_37', question: 'Qui est la mère biologique du Prophète Muhammad ?', options: ['Aminah', 'Halimah', 'Khadijah', 'Aicha'], correctAnswerIndex: 0, explanation: 'Aminah bint Wahb était la mère biologique du Prophète Muhammad.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_38', question: 'Sous quel autre nom connaît-on le calendrier islamique ?', options: ['Calendrier Solaire', 'Calendrier Hégirien', 'Calendrier Grégorien', 'Calendrier Julien'], correctAnswerIndex: 1, explanation: 'Le calendrier islamique est aussi appelé calendrier Hégirien, d\'après l\'Hégire (migration).', difficulty: 'easy'),
    QuizQuestion(id: 'easy_39', question: 'Combien de noms d\'Allah sont traditionnellement mémorisés (Asma-ul-Husna) ?', options: ['50', '75', '99', '114'], correctAnswerIndex: 2, explanation: 'Il y a 99 noms magnifiques d\'Allah mentionnés dans la tradition islamique.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_40', question: 'Que signifie "Bismillah" ?', options: ['Gloire à Allah', 'Au nom d\'Allah', 'Allah est grand', 'Louange à Allah'], correctAnswerIndex: 1, explanation: 'Bismillah signifie "Au nom d\'Allah" et est récité avant de commencer toute action.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_41', question: 'Quel est le livre saint révélé au Prophète Muhammad ?', options: ['L\'Évangile', 'La Torah', 'Le Coran', 'Les Psaumes'], correctAnswerIndex: 2, explanation: 'Le Coran est le dernier livre saint révélé par Allah au Prophète Muhammad.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_42', question: 'Combien de Rakat obligatoires y a-t-il dans la prière du Fajr ?', options: ['2 Rakat', '3 Rakat', '4 Rakat', 'Aucune de ces réponses'], correctAnswerIndex: 0, explanation: 'La prière du Fajr se compose de 2 Rakat obligatoires (Fard).', difficulty: 'easy'),
    QuizQuestion(id: 'easy_43', question: 'Quel est le premier mois du calendrier islamique de l\'Hégire ?', options: ['Ramadan', 'Shawwal', 'Muharram', 'Safar'], correctAnswerIndex: 2, explanation: 'Muharram est le premier mois du calendrier lunaire islamique.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_44', question: 'Qui fut le premier des Califes bien guidés ?', options: ['Omar ibn Al-Khattab', 'Ali ibn Abi Talib', 'Othman ibn Affan', 'Abou Bakr As-Siddiq'], correctAnswerIndex: 3, explanation: 'Abou Bakr As-Siddiq fut le premier à devenir Calife après le décès du Prophète Muhammad.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_45', question: 'Où se trouve la Kaaba ?', options: ['Médine', 'La Mecque', 'Jérusalem', 'Riyad'], correctAnswerIndex: 1, explanation: 'La Kaaba est située à l\'intérieur de la Grande Mosquée (Al-Masjid Al-Haram) à La Mecque.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_46', question: 'Qui fut la première épouse du Prophète Muhammad ?', options: ['Aicha', 'Khadijah', 'Hafsa', 'Zaynab'], correctAnswerIndex: 1, explanation: 'Khadijah bint Khuwaylid fut la première épouse du Prophète Muhammad et sa première disciple.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_47', question: 'Quel est le nom de l\'ange qui apportait les révélations aux Prophètes ?', options: ['Mikaeel', 'Israfil', 'Jibreel', 'Azraeel'], correctAnswerIndex: 2, explanation: 'L\'ange Jibreel (Gabriel) était chargé de transmettre les paroles d\'Allah à Ses prophètes.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_48', question: 'Quel prophète fut avalé par un grand poisson ou une baleine ?', options: ['Prophète Nuh', 'Prophète Yunus', 'Prophète Moussa', 'Prophète Issa'], correctAnswerIndex: 1, explanation: 'Le Prophète Yunus (Jonas) fut avalé par une baleine et se repentit auprès d\'Allah dans son ventre.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_49', question: 'Quel est le mot arabe pour l\'Appel à la prière ?', options: ['Iqamah', 'Adhan', 'Khutbah', 'Tasbih'], correctAnswerIndex: 1, explanation: 'L\'Adhan est l\'appel islamique à la prière, récité par un Mu\'adhin pour annoncer les heures de prière.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_50', question: 'Qui fut la première personne à appeler à la prière (Adhan) en Islam ?', options: ['Ali ibn Abi Talib', 'Omar ibn Al-Khattab', 'Bilal ibn Rabah', 'Zayd ibn Harithah'], correctAnswerIndex: 2, explanation: 'Bilal ibn Rabah, connu pour sa belle voix, fut choisi par le Prophète pour être le premier Mu\'adhin.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_51', question: 'Quelle est la Sourate la plus courte du Coran ?', options: ['Sourate Al-Ikhlas', 'Sourate Al-Asr', 'Sourate Al-Kawthar', 'Sourate An-Nas'], correctAnswerIndex: 2, explanation: 'La Sourate Al-Kawthar est le chapitre le plus court du Coran, composé de seulement 3 versets.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_52', question: 'Quel prophète reçut l\'ordre d\'Allah de construire une grande Arche ?', options: ['Prophète Nuh', 'Prophète Ibrahim', 'Prophète Lut', 'Prophète Hud'], correctAnswerIndex: 0, explanation: 'Le Prophète Nuh (Noé) construisit une Arche pour sauver les croyants et des paires d\'animaux d\'un grand déluge.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_53', question: 'Quel est le nom de l\'eau de source sacrée située à La Mecque ?', options: ['Zamzam', 'Kawthar', 'Tasneem', 'Salsabil'], correctAnswerIndex: 0, explanation: 'Zamzam est le puits d\'eau sacrée situé dans la Masjid al-Haram à La Mecque.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_54', question: 'Que signifie "Alhamdulillah" ?', options: ['Si Allah le veut', 'Allah est le plus grand', 'Louange à Allah', 'Gloire à Allah'], correctAnswerIndex: 2, explanation: 'Alhamdulillah se traduit par "Toute louange est due à Allah", utilisé pour exprimer la gratitude.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_55', question: 'Comment appelle-t-on la prière communautaire spéciale du vendredi ?', options: ['Tarawih', 'Jumu\'ah', 'Witr', 'Tahajjud'], correctAnswerIndex: 1, explanation: 'La Salat al-Jumu\'ah est la prière du vendredi où les musulmans se rassemblent pour écouter un sermon (Khutbah) et prier ensemble.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_56', question: 'Combien de Rakat obligatoires y a-t-il dans la prière du Asr ?', options: ['2', '3', '4', '5'], correctAnswerIndex: 2, explanation: 'La prière du Asr (après-midi) se compose de 4 Rakat obligatoires (Fard).', difficulty: 'easy'),
    QuizQuestion(id: 'easy_57', question: 'Combien de Rakat obligatoires y a-t-il dans la prière de l\'Icha ?', options: ['2', '3', '4', '5'], correctAnswerIndex: 2, explanation: 'La prière de l\'Icha (nuit) se compose de 4 Rakat obligatoires (Fard).', difficulty: 'easy'),
    QuizQuestion(id: 'easy_58', question: 'Où se trouve la Mosquée du Prophète (Al-Masjid an-Nabawi) ?', options: ['La Mecque', 'Médine', 'Jérusalem', 'Le Caire'], correctAnswerIndex: 1, explanation: 'La Mosquée du Prophète, deuxième lieu saint de l\'Islam, est située dans la ville de Médine.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_59', question: 'Quel Prophète avait un bâton qui pouvait se transformer en serpent ?', options: ['Prophète Issa', 'Prophète Souleymane', 'Prophète Moussa', 'Prophète Ibrahim'], correctAnswerIndex: 2, explanation: 'Allah donna au Prophète Moussa (Moïse) des miracles, dont un bâton qui se transformait en serpent.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_60', question: 'Que signifie "Insha\'Allah" ?', options: ['Louange à Allah', 'Si Allah le veut', 'Allah sait mieux', 'Pardonne-moi Allah'], correctAnswerIndex: 1, explanation: 'Les musulmans disent Insha\'Allah (Si Allah le veut) lorsqu\'ils parlent de projets ou d\'événements futurs.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_61', question: 'Comment s\'appelle la fête célébrée à la fin du Ramadan ?', options: ['Aïd al-Adha', 'Mawlid', 'Achoura', 'Aïd al-Fitr'], correctAnswerIndex: 3, explanation: 'L\'Aïd al-Fitr est la "Fête de la rupture du jeûne" marquant la fin du Ramadan.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_62', question: 'Comment s\'appelle la fête célébrée pendant la période du Hajj ?', options: ['Aïd al-Fitr', 'Aïd al-Adha', 'Ramadan', 'Laylat al-Qadr'], correctAnswerIndex: 1, explanation: 'L\'Aïd al-Adha est la "Fête du Sacrifice" honorant la volonté du Prophète Ibrahim de sacrifier son fils.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_63', question: 'Dans quelle langue le Saint Coran a-t-il été révélé ?', options: ['Hébreu', 'Araméen', 'Arabe', 'Persan'], correctAnswerIndex: 2, explanation: 'Le Coran a été révélé au Prophète Muhammad en langue arabe.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_64', question: 'Quel ange est chargé de souffler dans la trompette le Jour du Jugement ?', options: ['Jibreel', 'Israfil', 'Mikaeel', 'Azraeel'], correctAnswerIndex: 1, explanation: 'L\'ange Israfil soufflera dans la trompette (Soor) pour signaler le début du Jour du Jugement.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_65', question: 'Quel est le livre saint donné au Prophète Moussa (Moïse) ?', options: ['Injeel (Évangile)', 'Zabur (Psaumes)', 'Tawrat (Torah)', 'Coran'], correctAnswerIndex: 2, explanation: 'La Tawrat (Torah) était la révélation donnée par Allah au Prophète Moussa.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_66', question: 'Quel est le livre saint donné au Prophète Issa (Jésus) ?', options: ['Zabur (Psaumes)', 'Tawrat (Torah)', 'Injeel (Évangile)', 'Coran'], correctAnswerIndex: 2, explanation: 'L\'Injeel (Évangile) était la révélation donnée par Allah au Prophète Issa.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_67', question: 'Quel est le terme pour les actions et aliments permis en Islam ?', options: ['Haram', 'Makruh', 'Halal', 'Bid\'ah'], correctAnswerIndex: 2, explanation: 'Halal signifie permis ou licite dans la loi islamique traditionnelle.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_68', question: 'Qui est connu sous le nom de "Khalilullah" (L\'Ami d\'Allah) ?', options: ['Prophète Muhammad', 'Prophète Moussa', 'Prophète Ibrahim', 'Prophète Issa'], correctAnswerIndex: 2, explanation: 'Le Prophète Ibrahim (Abraham) est hautement vénéré et surnommé Khalilullah en Islam.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_69', question: 'Quel Prophète reçut le pouvoir de parler aux animaux et de contrôler les Djinns ?', options: ['Prophète Dawud', 'Prophète Souleymane', 'Prophète Yusuf', 'Prophète Ayub'], correctAnswerIndex: 1, explanation: 'Le Prophète Souleymane (Salomon) reçut un immense royaume et un pouvoir sur les animaux, le vent et les Djinns.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_70', question: 'Quel est le mot arabe pour le Diable ?', options: ['Malaikah', 'Shaytan', 'Jinn', 'Dajjal'], correctAnswerIndex: 1, explanation: 'Shaytan (Satan) est le terme utilisé en Islam pour le Diable, qui tente les humains de s\'éloigner d\'Allah.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_71', question: 'Dans quelle grotte le Prophète Muhammad reçut-il la première révélation ?', options: ['Grotte de Thawr', 'Grotte de Hira', 'Grotte des Gens de la Caverne', 'Grotte de Uhud'], correctAnswerIndex: 1, explanation: 'Le Prophète reçut les premiers versets du Coran dans la grotte de Hira, située sur une montagne près de La Mecque.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_72', question: 'Que disent traditionnellement les musulmans lorsqu\'ils éternuent ?', options: ['Bismillah', 'SubhanAllah', 'Alhamdulillah', 'Allahu Akbar'], correctAnswerIndex: 2, explanation: 'Lorsqu\'un musulman éternue, il dit Alhamdulillah (Louange à Allah).', difficulty: 'easy'),
    QuizQuestion(id: 'easy_73', question: 'Quelle main un musulman utilise-t-il traditionnellement pour manger et boire ?', options: ['La main droite', 'La main gauche', 'Les deux mains également', 'Cela n\'a pas d\'importance'], correctAnswerIndex: 0, explanation: 'Suivant la Sunnah du Prophète, les musulmans mangent et boivent avec la main droite.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_74', question: 'Quel est le mot islamique pour le Paradis ?', options: ['Jahanam', 'Barzakh', 'Jannah', 'Akhirah'], correctAnswerIndex: 2, explanation: 'Jannah est le Paradis éternel réservé aux justes et aux croyants dans l\'au-delà.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_75', question: 'Quel est le mot islamique pour l\'Enfer ?', options: ['Jannah', 'Jahanam', 'Dunya', 'Sirat'], correctAnswerIndex: 1, explanation: 'Jahanam est le terme pour le Feu de l\'Enfer dans l\'eschatologie islamique.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_76', question: 'Quelle Sourate est souvent appelée le "Cœur du Coran" ?', options: ['Sourate Al-Mulk', 'Sourate Ar-Rahman', 'Sourate Yaseen', 'Sourate Al-Kahf'], correctAnswerIndex: 2, explanation: 'La Sourate Yaseen est largement connue comme le cœur du Coran en raison de ses messages puissants.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_77', question: 'Quel était le nom du père du Prophète Muhammad ?', options: ['Abu Talib', 'Abdullah', 'Abdul Muttalib', 'Hamza'], correctAnswerIndex: 1, explanation: 'Abdullah ibn Abdul Muttalib était le père du Prophète Muhammad ; il est décédé avant la naissance du Prophète.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_78', question: 'Que signifie "SubhanAllah" ?', options: ['Dieu est grand', 'Dieu est pardonneur', 'Gloire à Allah', 'Louange à Allah'], correctAnswerIndex: 2, explanation: 'SubhanAllah est utilisé pour exprimer la perfection absolue et la gloire d\'Allah.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_79', question: 'Que signifie "Astaghfirullah" ?', options: ['Je cherche le pardon d\'Allah', 'Allah est le plus grand', 'Je fais confiance à Allah', 'Merci Allah'], correctAnswerIndex: 0, explanation: 'Les musulmans disent Astaghfirullah pour demander la miséricorde et le pardon d\'Allah pour leurs péchés.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_80', question: 'Quel est le titre de la personne qui dirige la prière en congrégation ?', options: ['Mu\'adhin', 'Imam', 'Qari', 'Cheikh'], correctAnswerIndex: 1, explanation: 'L\'Imam est la personne qui se tient devant et dirige les fidèles dans la prière.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_81', question: 'Quel Prophète est né miraculeusement sans père humain ?', options: ['Prophète Yahya', 'Prophète Moussa', 'Prophète Issa', 'Prophète Ibrahim'], correctAnswerIndex: 2, explanation: 'Le Prophète Issa (Jésus) est né de la Vierge Marie (Maryam) par la volonté d\'Allah.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_82', question: 'Qui a adopté et protégé le Prophète Muhammad après le décès de son grand-père ?', options: ['Abu Lahab', 'Abu Jahl', 'Hamza', 'Abu Talib'], correctAnswerIndex: 3, explanation: 'Son oncle, Abu Talib, l\'a élevé et a fourni une protection vitale durant les premiers jours de l\'Islam.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_83', question: 'Que signifie "JazakAllahu Khairan" ?', options: ['Que la paix soit sur vous', 'Qu\'Allah te récompense par le bien', 'Bienvenue', 'Au revoir'], correctAnswerIndex: 1, explanation: 'C\'est une phrase islamique courante utilisée pour exprimer sa gratitude, demandant à Allah de récompenser la personne.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_84', question: 'Quel animal fut envoyé par Allah pour montrer à Qabil (Caïn) comment enterrer son frère ?', options: ['Une colombe', 'Un corbeau', 'Un chameau', 'Une araignée'], correctAnswerIndex: 1, explanation: 'Allah envoya un corbeau grattant le sol pour enseigner à Qabil comment cacher le corps de son frère Habil.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_85', question: 'Quel fut le tout premier mot du Coran révélé au Prophète Muhammad ?', options: ['Alhamdulillah (Louange)', 'Bismillah (Au nom)', 'Iqra (Lis)', 'Qul (Dis)'], correctAnswerIndex: 2, explanation: 'Le premier mot révélé fut "Iqra" (Lis/Récite), soulignant l\'importance du savoir.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_86', question: 'Comment appelle-t-on les vêtements spéciaux et l\'état de pureté requis pour le Hajj et la Omra ?', options: ['Hijab', 'Ihram', 'Thawb', 'Abaya'], correctAnswerIndex: 1, explanation: 'L\'Ihram implique un état de pureté spirituelle et le port de vêtements simples spécifiques (pour les hommes, deux tissus blancs non cousus).', difficulty: 'easy'),
    QuizQuestion(id: 'easy_87', question: 'Quel prophète fut jeté dans un immense feu mais fut sauvé quand Allah le rendit frais et sûr ?', options: ['Prophète Moussa', 'Prophète Yusuf', 'Prophète Ibrahim', 'Prophète Yunus'], correctAnswerIndex: 2, explanation: 'Le Prophète Ibrahim fut jeté dans un feu par le roi Nimrod, mais Allah ordonna au feu d\'être frais et paisible pour lui.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_88', question: 'Comment appelle-t-on la nuit spéciale du pouvoir pendant le Ramadan ?', options: ['Laylat al-Miraj', 'Laylat al-Qadr', 'Achoura', 'Isra'], correctAnswerIndex: 1, explanation: 'Laylat al-Qadr (La Nuit du Destin) est la nuit où le Coran fut révélé pour la première fois, considérée meilleure que mille mois.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_89', question: 'Quel compagnon était connu pour sa force incroyable et devint le deuxième Calife de l\'Islam ?', options: ['Abou Bakr', 'Othman ibn Affan', 'Ali ibn Abi Talib', 'Omar ibn Al-Khattab'], correctAnswerIndex: 3, explanation: 'Omar ibn Al-Khattab était connu pour sa volonté forte, sa justice et sa force physique.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_90', question: 'Quel est le troisième lieu saint de l\'Islam ?', options: ['Al-Masjid an-Nabawi', 'Al-Masjid Al-Haram', 'Al-Masjid Al-Aqsa', 'Mosquée de Quba'], correctAnswerIndex: 2, explanation: 'Al-Masjid Al-Aqsa, situé à Jérusalem, est le troisième lieu saint et la première Qibla de l\'Islam.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_91', question: 'Combien de fois le Prophète Muhammad a-t-il accompli le pèlerinage du Hajj ?', options: ['Une fois', 'Deux fois', 'Trois fois', 'Cinq fois'], correctAnswerIndex: 0, explanation: 'Le Prophète Muhammad n\'a accompli le Hajj qu\'une seule fois dans sa vie, connu sous le nom de Hajj d\'Adieu.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_92', question: 'Quel est le nom du foulard islamique souvent porté par les femmes musulmanes ?', options: ['Kufi', 'Hijab', 'Thawb', 'Niqab'], correctAnswerIndex: 1, explanation: 'Le Hijab est un voile porté par certaines femmes musulmanes en présence de tout homme en dehors de leur famille immédiate.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_93', question: 'Quel oncle du Prophète Muhammad était un ennemi majeur de l\'Islam et est mentionné dans la Sourate Al-Masad ?', options: ['Abu Talib', 'Hamza', 'Abbas', 'Abu Lahab'], correctAnswerIndex: 3, explanation: 'Abu Lahab s\'opposa farouchement à l\'Islam et un chapitre spécifique (Al-Masad) fut révélé pour le condamner.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_94', question: 'Quel est le livre saint donné au Prophète Dawud (David) ?', options: ['Injeel (Évangile)', 'Zabur (Psaumes)', 'Coran', 'Tawrat (Torah)'], correctAnswerIndex: 1, explanation: 'Le Zabur fut donné au Prophète Dawud, connu pour ses beaux hymnes et louanges à Allah.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_95', question: 'Quelle créature a protégé le Prophète Muhammad et Abu Bakr dans la grotte de Thawr en tissant une toile ?', options: ['Un oiseau', 'Une araignée', 'Un serpent', 'Une abeille'], correctAnswerIndex: 1, explanation: 'Une araignée tissa une toile sur l\'entrée de la grotte, trompant les ennemis qui pensaient la grotte vide.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_96', question: 'Quel est le mot arabe pour la communauté mondiale des musulmans ?', options: ['Jamaat', 'Tariqah', 'Ummah', 'Madhab'], correctAnswerIndex: 2, explanation: 'L\'Ummah désigne la communauté collective des peuples islamiques à travers le monde.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_97', question: 'Qui est le Créateur et le Sustenteur de tout dans l\'univers selon l\'Islam ?', options: ['Les Anges', 'La Nature', 'Allah', 'Les Prophètes'], correctAnswerIndex: 2, explanation: 'En Islam, Allah est le seul créateur, maître et sustenteur de tout l\'univers.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_98', question: 'Que signifie littéralement le mot "Coran" ?', options: ['Le Livre', 'La Récitation', 'La Loi', 'La Lumière'], correctAnswerIndex: 1, explanation: 'Le mot Coran vient de la racine arabe signifiant "lire" ou "réciter".', difficulty: 'easy'),
    QuizQuestion(id: 'easy_99', question: 'Quel est le nom de la première mosquée jamais construite en Islam ?', options: ['Masjid al-Haram', 'Masjid an-Nabawi', 'Mosquée de Quba', 'Masjid al-Aqsa'], correctAnswerIndex: 2, explanation: 'La Mosquée de Quba, située juste à l\'extérieur de Médine, fut la première mosquée construite par le Prophète après son émigration.', difficulty: 'easy'),
    QuizQuestion(id: 'easy_100', question: 'Quel Prophète était connu pour sa patience exceptionnelle durant une grave maladie ?', options: ['Prophète Ayub (Job)', 'Prophète Yusuf (Joseph)', 'Prophète Yahya (Jean)', 'Prophète Zakariya (Zacharie)'], correctAnswerIndex: 0, explanation: 'Le Prophète Ayub est célébré en Islam comme le symbole ultime de patience et de foi inébranlable dans l\'épreuve.', difficulty: 'easy'),
  ];
}

  List<QuizQuestion> _getMediumQuestionsFr() {
  return [
    QuizQuestion(id: 'mid_1', question: 'Qu\'est-ce que la Sunnah ?', options: ['Les enseignements d\'autres religions', 'Les pratiques et traditions du Prophète Muhammad', 'Rituels de pèlerinage', 'Codes juridiques islamiques'], correctAnswerIndex: 1, explanation: 'La Sunnah désigne les traditions, pratiques et paroles du Prophète Muhammad qui servent de modèle aux musulmans.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_2', question: 'Qui fut le premier Calife musulman ?', options: ['Omar ibn Al-Khattab', 'Abou Bakr', 'Othman ibn Affan', 'Ali ibn Abi Talib'], correctAnswerIndex: 1, explanation: 'Abou Bakr (As-Siddiq) fut le premier Calife après le Prophète Muhammad, gouvernant de 632 à 634 È.C.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_3', question: 'Qu\'est-ce que le Fiqh dans la jurisprudence islamique ?', options: ['La mémorisation du Coran', 'La compréhension et l\'interprétation de la loi islamique', 'Les traditions narratives', 'Les expressions poétiques'], correctAnswerIndex: 1, explanation: 'Le Fiqh est la branche de la connaissance islamique traitant de la compréhension profonde et de l\'application de la Charia.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_4', question: 'Qu\'est-ce que l\'Ijma en droit islamique ?', options: ['L\'opinion personnelle', 'Le consensus des savants islamiques', 'Les versets coraniques', 'Les traditions uniquement'], correctAnswerIndex: 1, explanation: 'L\'Ijma est le consensus des savants islamiques sur une question religieuse particulière et est une source primaire du droit islamique.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_5', question: 'Combien de compagnons sont connus sous le nom de "Califes Bien Guidés" (Khulafa-e-Rashidun) ?', options: ['2', '3', '4', '5'], correctAnswerIndex: 2, explanation: 'Les quatre Califes Bien Guidés sont Abou Bakr, Omar, Othman et Ali, qui ont dirigé la communauté musulmane après le Prophète.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_6', question: 'Comment appelle-t-on la Nuit du Destin en arabe ?', options: ['Laylat Al-Qadr', 'Laylat Al-Jinn', 'Laylat Al-Isra', 'Laylat Al-Baraa'], correctAnswerIndex: 0, explanation: 'Laylat Al-Qadr (La Nuit du Destin ou du Décret) est la nuit où le Coran fut révélé pour la première fois et est considérée comme la nuit la plus bénie.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_7', question: 'Quelle Sourate est consacrée à la mention de la Nuit du Destin ?', options: ['Sourate Al-Alaq', 'Sourate Al-Qadr', 'Sourate Ar-Rahman', 'Sourate Al-Adiyat'], correctAnswerIndex: 1, explanation: 'La Sourate Al-Qadr (Chapitre 97) est entièrement consacrée à la description des bénédictions de la Nuit du Destin.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_8', question: 'Qu\'est-ce que le Qiyas dans la jurisprudence islamique ?', options: ['La mesure', 'Le raisonnement par analogie', 'Le rapport', 'Le questionnement'], correctAnswerIndex: 1, explanation: 'Le Qiyas est la méthode pour déduire des règles islamiques pour de nouvelles situations en faisant des analogies avec des cas similaires trouvés dans le Coran ou la Sunnah.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_9', question: 'Combien de scribes de la révélation le Prophète Muhammad avait-il approximativement ?', options: ['3', '5', '10', 'Environ 40'], correctAnswerIndex: 3, explanation: 'Le Prophète Muhammad avait environ 40 à 65 scribes au fil du temps qui enregistraient les révélations coraniques, dont Zayd ibn Harithah, Ali et Uthman.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_10', question: 'Que signifie conceptuellement le Hijab dans un contexte islamique ?', options: ['Seulement un foulard', 'La pudeur et une tenue modeste pour les hommes et les femmes', 'Uniquement un paravent physique', 'Une interdiction religieuse'], correctAnswerIndex: 1, explanation: 'Le Hijab représente un concept global de pudeur, de comportement et de tenue qui s\'applique aux hommes et aux femmes.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_11', question: 'Qu\'est-ce que l\'Isra et le Mi\'raj ?', options: ['Deux batailles différentes', 'Le voyage nocturne du Prophète à Jérusalem et son ascension au ciel', 'Deux Sourates du Coran', 'Deux noms de la Kaaba'], correctAnswerIndex: 1, explanation: 'L\'Isra est le voyage nocturne miraculeux à Jérusalem, et le Mi\'raj est l\'ascension vers les cieux pour parler avec Allah.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_12', question: 'Quelle Sourate contient le Verset du Trône (Ayat Al-Kursi) ?', options: ['Sourate Al-Baqarah', 'Sourate Aal-Imran', 'Sourate An-Noor', 'Sourate Ya-Seen'], correctAnswerIndex: 0, explanation: 'L\'Ayat Al-Kursi se trouve dans la Sourate Al-Baqarah (2:255) et est considéré comme le plus grand verset du Coran.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_13', question: 'Quelle est la Sourate la plus courte du Coran ?', options: ['Sourate Al-Ikhlas', 'Sourate An-Nas', 'Sourate Al-Kawthar', 'Sourate Al-Fil'], correctAnswerIndex: 2, explanation: 'La Sourate Al-Kawthar (Chapitre 108) est la Sourate la plus courte du Coran, ne contenant que 3 versets.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_14', question: 'Combien de noms magnifiques (Asma ul-Husna) d\'Allah sont traditionnellement mis en avant ?', options: ['50', '99', '150', '200'], correctAnswerIndex: 1, explanation: 'Bien qu\'Allah ait de nombreux noms, 99 noms spécifiques sont célèbres dans la tradition islamique et le Hadith.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_15', question: 'Qu\'est-ce que la Bataille de Badr ?', options: ['Un lieu à Médine', 'La première grande bataille entre les Musulmans et les Qurayshites', 'Une route commerciale', 'Un puits d\'eau'], correctAnswerIndex: 1, explanation: 'La Bataille de Badr (2 AH/624 È.C.) fut la première victoire militaire majeure et décisive des premiers Musulmans contre les Qurayshites.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_16', question: 'Que signifie "Oumma" ?', options: ['Mère', 'Nation ou communauté', 'Grand-mère', 'Tribu'], correctAnswerIndex: 1, explanation: 'L\'Oumma désigne la communauté musulmane mondiale unie par sa foi en l\'Islam.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_17', question: 'Quels sont les Six Articles de la Croyance Islamique (Iman) ?', options: ['Allah, Coran, Prière, Jeûne, Zakat, Hajj', 'Croyance en Allah, aux Anges, aux Livres, aux Prophètes, au Jour du Jugement et au Décret Divin', 'Uniquement les Cinq Piliers', 'Uniquement les noms d\'Allah'], correctAnswerIndex: 1, explanation: 'Les Six Articles de la Foi forment le fondement théologique de la croyance islamique.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_18', question: 'Qui était la première épouse du Prophète Ibrahim ?', options: ['Sarah', 'Hagar', 'Keturah', 'Léa'], correctAnswerIndex: 0, explanation: 'Sarah était la première épouse du Prophète Ibrahim et la mère du Prophète Ishaq (Isaac).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_19', question: 'Pour quoi le mois islamique de Muharram est-il particulièrement connu ?', options: ['Être le mois de jeûne', 'Être le mois du Hajj', 'Être un mois sacré contenant le jour d\'Achoura', 'Être le mois de l\'Aïd'], correctAnswerIndex: 2, explanation: 'Muharram est le premier mois de l\'année islamique, un mois sacré, et contient le jour historique d\'Achoura (10 Muharram).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_20', question: 'Qu\'est-ce que la Zakat Al-Fitr ?', options: ['Taxe sur la propriété agricole', 'Charité donnée à la fin du Ramadan avant la prière de l\'Aïd', 'Charité mensuelle', 'Charité pour les voyageurs uniquement'], correctAnswerIndex: 1, explanation: 'La Zakat Al-Fitr est une charité obligatoire de nourriture donnée avant l\'Aïd Al-Fitr pour que chacun puisse célébrer ce jour.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_21', question: 'Selon le Coran, combien d\'anges porteront le Trône d\'Allah le Jour du Jugement ?', options: ['4', '6', '8', '10'], correctAnswerIndex: 2, explanation: 'La Sourate Al-Haqqah (69:17) déclare que huit anges porteront le Trône d\'Allah ce Jour-là.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_22', question: 'Quel est le nom de l\'ange qui a apporté la révélation coranique au Prophète Muhammad ?', options: ['Jibreel (Gabriel)', 'Mikail (Michaël)', 'Israfil', 'Malik'], correctAnswerIndex: 0, explanation: 'L\'ange Jibreel est chargé de transmettre les révélations d\'Allah à tous les Prophètes.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_23', question: 'Selon le Hadith, quelle est la première action sur laquelle une personne sera jugée le Jour du Jugement ?', options: ['La croyance', 'La prière (Salat)', 'La charité (Zakat)', 'Le jeûne (Sawm)'], correctAnswerIndex: 1, explanation: 'Le Prophète a dit que la première œuvre pour laquelle une personne sera amenée à rendre des comptes le Jour du Jugement sera sa prière.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_24', question: 'Combien de fois l\'expression "Ô vous qui croyez" (Ya ayyuhal-ladheena amanu) apparaît-elle dans le Coran ?', options: ['50', '75', '89', '114'], correctAnswerIndex: 2, explanation: 'Cette phrase spécifique s\'adressant directement aux croyants apparaît exactement 89 fois dans le Coran.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_25', question: 'Quel compagnon est célèbre sous le nom de "Traducteur du Coran" (Tarjuman al-Quran) ?', options: ['Ali ibn Abi Talib', 'Abdullah ibn Masud', 'Abdullah ibn Abbas', 'Ubayy ibn Ka\'b'], correctAnswerIndex: 2, explanation: 'Abdullah ibn Abbas était un jeune compagnon pour qui le Prophète a prié pour une compréhension profonde de la religion, lui valant ce titre.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_26', question: 'Combien de fois le Prophète Muhammad a-t-il accompli le Hajj ?', options: ['Une fois', 'Deux fois', 'Trois fois', 'Cinq fois'], correctAnswerIndex: 0, explanation: 'Le Prophète Muhammad n\'a accompli le Hajj qu\'une seule fois dans sa vie en 10 AH, connu sous le nom de Pèlerinage d\'Adieu.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_27', question: 'Qu\'est-ce que l\'Istikharah ?', options: ['Un rituel de jeûne', 'Une prière spéciale pour chercher la guidance d\'Allah dans une décision', 'Un rituel de pèlerinage', 'Un type de charité'], correctAnswerIndex: 1, explanation: 'L\'Istikharah est une prière de deux rakats suivie d\'une supplication spécifique demandant à Allah de guider dans un choix.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_28', question: 'Comment appelle-t-on les anges qui enregistrent les bonnes et mauvaises actions d\'une personne ?', options: ['Hafazah', 'Munkar et Nakir', 'Kiraman Katibin', 'Mu\'aqqibat'], correctAnswerIndex: 2, explanation: 'Les Kiraman Katibin (Nobles Scribes) se tiennent sur les épaules droite et gauche d\'une personne pour enregistrer ses actes.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_29', question: 'Comment appelle-t-on le châtiment dans la tombe en arabe ?', options: ['Athab Al-Qabr', 'Jahim', 'Sakar', 'Lazaa'], correctAnswerIndex: 0, explanation: 'Athab Al-Qabr désigne les épreuves et châtiments dans la tombe, un concept mentionné dans les enseignements islamiques.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_30', question: 'Combien de versets compte la Sourate Al-Baqarah, le chapitre le plus long du Coran ?', options: ['100', '200', '286', '300'], correctAnswerIndex: 2, explanation: 'La Sourate Al-Baqarah compte 286 versets, ce qui en fait le chapitre le plus long du Coran.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_31', question: 'Que signifie "Sadaqah Jariyah" ?', options: ['Charité ponctuelle', 'Charité continue dont les bienfaits se poursuivent après la mort', 'Charité forcée', 'Charité de fête'], correctAnswerIndex: 1, explanation: 'La Sadaqah Jariyah comprend des actes comme la construction d\'un puits, d\'une mosquée ou d\'une école, qui génèrent des récompenses continues même après la mort.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_32', question: 'Quelle compagne et épouse du Prophète a rapporté le plus de Hadiths ?', options: ['Aisha bint Abu Bakr', 'Fatima bint Muhammad', 'Hafsa bint Umar', 'Khadijah bint Khuwaylid'], correctAnswerIndex: 0, explanation: 'Aisha a rapporté plus de 2 200 Hadiths et était l\'une des plus éminentes savantes du début de l\'Islam.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_33', question: 'Quel est le nom de la bataille où les Musulmans ont creusé une immense tranchée pour défendre Médine ?', options: ['Bataille de Badr', 'Bataille de Uhud', 'Bataille de Khandaq', 'Bataille de Hunayn'], correctAnswerIndex: 2, explanation: 'La Bataille de Khandaq (Tranchée), également connue sous le nom d\'Al-Ahzab, impliquait la défense de Médine à l\'aide d\'une tranchée suggérée par Salman Al-Farsi.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_34', question: 'Quel ange est chargé de souffler dans la Trompette pour signaler le Jour du Jugement ?', options: ['Jibreel', 'Mikail', 'Israfil', 'Malik'], correctAnswerIndex: 2, explanation: 'L\'ange Israfil soufflera dans la Trompette (Soor) deux fois : une fois pour mettre fin au monde, et une fois pour ressusciter les morts.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_35', question: 'Quel est le concept islamique de "Tawakkul" ?', options: ['Prière obligatoire', 'Confiance complète en Allah après avoir fait de son mieux', 'Jeûne en voyage', 'Charité secrète'], correctAnswerIndex: 1, explanation: 'Le Tawakkul signifie attacher son chameau d\'abord, puis placer sa confiance et son reliance complètes dans le plan d\'Allah.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_36', question: 'Combien de péchés majeurs destructeurs (Al-Mubiqat) le Prophète a-t-il explicitement listés ensemble dans un Hadith célèbre ?', options: ['3', '5', '7', '9'], correctAnswerIndex: 2, explanation: 'Le Prophète a listé 7 péchés destructeurs, incluant le Shirk, la magie, le meurtre, la consommation des biens de l\'orphelin, l\'usure, la fuite du champ de bataille et la calomnie envers les femmes chastes.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_37', question: 'Quel est le concept islamique de "Taqwa" ?', options: ['Peur des ennemis', 'Piété, droiture et conscience de Dieu', 'Prière en congrégation', 'Jeûne volontaire'], correctAnswerIndex: 1, explanation: 'La Taqwa est la conscience intérieure d\'Allah, poussant une personne à faire le bien et à éviter le mal.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_38', question: 'Qui le Prophète Muhammad a-t-il désigné comme le meilleur récitateur du Coran parmi ses compagnons ?', options: ['Abdullah ibn Masud', 'Ubayy ibn Ka\'b', 'Ali ibn Abi Talib', 'Zayd ibn Harithah'], correctAnswerIndex: 1, explanation: 'Le Prophète a explicitement loué Ubayy ibn Ka\'b comme le meilleur récitateur (Qari) du Coran parmi l\'Oumma.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_39', question: 'Quelle est la signification du nombre 19 dans la Sourate Al-Muddaththir ?', options: ['Nombre de prophètes', 'Nombre de chapitres dans une section', 'Le nombre d\'anges gardant l\'Enfer', 'Nombre de prières quotidiennes initialement ordonnées'], correctAnswerIndex: 2, explanation: 'La Sourate Al-Muddaththir déclare qu\'il y a 19 anges féroces servant de gardiens sur l\'Enfer.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_40', question: 'Quelle était la première Qibla (direction de prière) pour les Musulmans avant qu\'elle ne soit changée vers La Mecque ?', options: ['Mosquée Al-Aqsa (Jérusalem)', 'Mosquée de Quba', 'Mont Sinaï', 'Mosquée du Prophète'], correctAnswerIndex: 0, explanation: 'Les Musulmans priaient initialement en direction de la Mosquée Al-Aqsa à Jérusalem pendant environ 16-17 mois avant que la Qibla ne soit changée vers la Kaaba.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_41', question: 'Dans quelle grotte le Prophète Muhammad méditait-il régulièrement avant la première révélation ?', options: ['Grotte de Thawr', 'Grotte de Hira', 'Grotte des Dormants', 'Grotte du Mont Sinaï'], correctAnswerIndex: 1, explanation: 'Le Prophète avait l\'habitude de se retirer dans la Grotte de Hira à Jabal al-Nour (Montagne de la Lumière) près de La Mecque.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_42', question: 'Quelle Sourate est souvent appelée le "Cœur du Coran" par les savants islamiques ?', options: ['Sourate Ar-Rahman', 'Sourate Al-Mulk', 'Sourate Ya-Seen', 'Sourate Al-Baqarah'], correctAnswerIndex: 2, explanation: 'La Sourate Ya-Seen est appelée le cœur du Coran car elle résume puissamment les croyances fondamentales de l\'Islam.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_43', question: 'Combien d\'années le Prophète a-t-il prêché à La Mecque avant l\'Hégire ?', options: ['10 ans', '13 ans', '15 ans', '23 ans'], correctAnswerIndex: 1, explanation: 'La période mecquoise de révélation et de prédication a duré 13 ans avant que la persécution ne conduise à l\'Hégire.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_44', question: 'Quel compagnon a reçu le titre de "L\'Épée dégainée d\'Allah" (Sayfullah) ?', options: ['Ali ibn Abi Talib', 'Omar ibn Al-Khattab', 'Khalid ibn Al-Walid', 'Hamza ibn Abdul-Muttalib'], correctAnswerIndex: 2, explanation: 'Khalid ibn Al-Walid a reçu ce titre du Prophète en raison de son génie militaire inégalé et de son dévouement.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_45', question: 'Dans quelle bataille le Prophète Muhammad a-t-il été blessé et sa dent cassée ?', options: ['Bataille de Badr', 'Bataille de la Tranchée', 'Bataille de Tabuk', 'Bataille de Uhud'], correctAnswerIndex: 3, explanation: 'Pendant la Bataille de Uhud, l\'armée musulmane a subi un grave revers et le Prophète lui-même a été blessé.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_46', question: 'En quelle année du calendrier hégirien le Traité de Hudaybiyyah a-t-il eu lieu ?', options: ['2 AH', '4 AH', '6 AH', '8 AH'], correctAnswerIndex: 2, explanation: 'Le Traité de Hudaybiyyah, un accord de paix crucial, a été signé en 6 AH.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_47', question: 'Quel est le nom collectif donné aux deux recueils de Hadiths les plus authentiques (Bukhari et Muslim) ?', options: ['Al-Muwatta', 'As-Sunan', 'As-Sahihayn', 'Al-Musnad'], correctAnswerIndex: 2, explanation: 'As-Sahihayn signifie "Les Deux Authentiques", se référant à Sahih al-Bukhari et Sahih Muslim.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_48', question: 'Qui était la nourrice qui a pris soin du Prophète Muhammad dans sa petite enfance ?', options: ['Aminah', 'Halimah as-Sa\'diyah', 'Umm Ayman', 'Fatimah'], correctAnswerIndex: 1, explanation: 'Halimah as-Sa\'diyah de la tribu des Banu Sa\'d a allaité et élevé le Prophète dans le désert durant ses premières années.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_49', question: 'Quel était le nom du grand-père du Prophète Muhammad, qui a pris soin de lui après la mort de sa mère ?', options: ['Abu Talib', 'Abdul Muttalib', 'Hashim', 'Abd Manaf'], correctAnswerIndex: 1, explanation: 'Abdul Muttalib, un chef respecté des Quraysh, a pris la garde du Prophète jusqu\'à son décès lorsque le Prophète avait huit ans.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_50', question: 'Quel était le nom du chameau préféré du Prophète Muhammad ?', options: ['Al-Qaswa', 'Al-Buraq', 'Duldul', 'Ya\'fur'], correctAnswerIndex: 0, explanation: 'Al-Qaswa était son chameau bien-aimé, qu\'il montait pendant l\'Hégire et le Pèlerinage d\'Adieu.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_51', question: 'Lors de la Bataille de Yarmouk, l\'armée musulmane a affronté quel grand empire ?', options: ['L\'Empire perse', 'L\'Empire romain (byzantin)', 'L\'Empire mongol', 'L\'Empire égyptien'], correctAnswerIndex: 1, explanation: 'La Bataille de Yarmouk fut une victoire décisive pour les Musulmans contre l\'Empire byzantin (romain d\'Orient).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_52', question: 'Quel est le sujet du plus long verset du Coran (2:282) ?', options: ['Le mariage', 'Le jeûne', 'Les contrats et les dettes', 'L\'héritage'], correctAnswerIndex: 2, explanation: 'Ayat al-Dayn (Le Verset de la Dette) détaille les règles pour écrire les transactions financières et les contrats.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_53', question: 'Quelle Sourate du Coran ne commence PAS par "Bismillah ir-Rahman ir-Rahim" ?', options: ['Sourate Al-Baqarah', 'Sourate At-Tawbah', 'Sourate Al-Kahf', 'Sourate Al-Mulk'], correctAnswerIndex: 1, explanation: 'La Sourate At-Tawbah (Chapitre 9) est le seul chapitre qui ne commence pas par la Basmalah.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_54', question: 'Quelle Sourate contient la phrase "Bismillah ir-Rahman ir-Rahim" deux fois ?', options: ['Sourate An-Naml', 'Sourate Al-Qasas', 'Sourate Taha', 'Sourate Yusuf'], correctAnswerIndex: 0, explanation: 'La Sourate An-Naml (Chapitre 27) la contient au début et au verset 30 (dans une lettre du Prophète Sulaiman).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_55', question: 'Quel compagnon était connu comme "Le Gardien du Secret du Prophète" ?', options: ['Abu Hurairah', 'Anas ibn Malik', 'Hudhayfah ibn al-Yaman', 'Zayd ibn Thabit'], correctAnswerIndex: 2, explanation: 'Le Prophète a confié à Hudhayfah les noms des hypocrites à Médine, un secret qu\'il a farouchement gardé.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_56', question: 'Quel Prophète a reçu le titre de "Kalimullah" (Celui qui a parlé à Allah) ?', options: ['Prophète Ibrahim', 'Prophète Musa', 'Prophète Isa', 'Prophète Muhammad'], correctAnswerIndex: 1, explanation: 'Le Prophète Musa (Moïse) est appelé Kalimullah parce qu\'Allah lui a parlé directement sur le Mont Sinaï.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_57', question: 'Quel Prophète est mentionné le plus souvent par son nom dans le Coran ?', options: ['Prophète Muhammad', 'Prophète Ibrahim', 'Prophète Isa', 'Prophète Musa'], correctAnswerIndex: 3, explanation: 'Le Prophète Musa est mentionné par son nom 136 fois dans le Coran, plus que tout autre prophète.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_58', question: 'Quel âge avait le Prophète Muhammad lorsqu\'il est décédé ?', options: ['60 ans', '61 ans', '63 ans', '65 ans'], correctAnswerIndex: 2, explanation: 'Le Prophète Muhammad est décédé à Médine à l\'âge de 63 ans dans le calendrier lunaire.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_59', question: 'Sur combien d\'années le Coran a-t-il été révélé ?', options: ['10 ans', '15 ans', '23 ans', '40 ans'], correctAnswerIndex: 2, explanation: 'Le Coran a été révélé par étapes sur environ 23 ans (13 à La Mecque, 10 à Médine).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_60', question: 'Entre quelles deux collines Hagar (Hajar) a-t-elle couru en va-et-vient à la recherche d\'eau ?', options: ['Safa et Marwa', 'Arafat et Muzdalifah', 'Uhud et Noor', 'Sinaï et Judi'], correctAnswerIndex: 0, explanation: 'Hajar a couru entre Safa et Marwa sept fois, un acte commémoré par les pèlerins lors du Sa\'i.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_61', question: 'Qu\'est-ce que le Tayammum ?', options: ['Un type de jeûne', 'Ablution sèche utilisant de la terre/sable propre quand l\'eau est indisponible', 'Une prière spéciale pour la pluie', 'La rupture du jeûne'], correctAnswerIndex: 1, explanation: 'Le Tayammum est l\'acte islamique d\'ablution sèche utilisant du sable ou de la poussière purifiée, autorisé quand l\'eau est absente ou nuisible.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_62', question: 'Quel est le nom de l\'ange qui garde l\'Enfer ?', options: ['Munkar', 'Ridwan', 'Malik', 'Azraeel'], correctAnswerIndex: 2, explanation: 'L\'ange Malik est le gardien en chef de l\'Enfer, explicitement mentionné par son nom dans la Sourate Az-Zukhruf.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_63', question: 'Quel est le nom traditionnellement donné à l\'ange gardant le Paradis (Jannah) ?', options: ['Ridwan', 'Malik', 'Jibreel', 'Israfil'], correctAnswerIndex: 0, explanation: 'La tradition islamique identifie Ridwan comme l\'ange nommé portier du Paradis.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_64', question: 'Que signifie littéralement le mot "Sunnah" en arabe ?', options: ['La Vérité', 'Le Livre', 'Le Chemin ou la Voie', 'La Loi'], correctAnswerIndex: 2, explanation: 'Linguistiquement, Sunnah signifie un chemin clair et bien tracé ou une pratique coutumière.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_65', question: 'Quel titre prestigieux est donné aux épouses du Prophète Muhammad ?', options: ['Reines de l\'Islam', 'Mères des Croyants', 'Filles de l\'Oumma', 'Leaders du Paradis'], correctAnswerIndex: 1, explanation: 'Le Coran (33:6) déclare les épouses du Prophète comme les "Mères des Croyants" (Ummahat al-Mu\'mineen).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_66', question: 'Qui fut la dernière des épouses du Prophète à décéder ?', options: ['Aisha', 'Hafsa', 'Umm Salama', 'Sawda'], correctAnswerIndex: 2, explanation: 'Umm Salama a vécu longtemps, décédant vers 61 AH, survivant aux autres épouses.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_67', question: 'Quel mois islamique précède directement le Ramadan ?', options: ['Rajab', 'Sha\'ban', 'Shawwal', 'Muharram'], correctAnswerIndex: 1, explanation: 'Sha\'ban est le 8ème mois du calendrier islamique, immédiatement avant le mois de jeûne du Ramadan.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_68', question: 'Quel mois islamique suit directement le Ramadan ?', options: ['Shawwal', 'Dhul-Qi\'dah', 'Safar', 'Rajab'], correctAnswerIndex: 0, explanation: 'Shawwal est le 10ème mois ; son premier jour est célébré comme l\'Aïd al-Fitr.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_69', question: 'Quel est le terme islamique pour se montrer ou faire de bonnes actions pour obtenir les louanges des gens ?', options: ['Shirk', 'Riya', 'Ghibah', 'Namimah'], correctAnswerIndex: 1, explanation: 'Le Riya est considéré comme une forme cachée de Shirk (polythéisme) car l\'acte est fait pour les gens, pas pour Allah.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_70', question: 'Qui fut la première personne martyrisée pour l\'Islam ?', options: ['Yasir', 'Sumayyah bint Khayyat', 'Hamza', 'Mus\'ab ibn \'Umair'], correctAnswerIndex: 1, explanation: 'Sumayyah a été tuée par Abu Jahl pour avoir refusé d\'abandonner l\'Islam, devenant la première martyre (Shaheed) en Islam.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_71', question: 'Qui a été envoyé comme premier ambassadeur de l\'Islam pour enseigner aux gens de Médine ?', options: ['Ali ibn Abi Talib', 'Uthman ibn Affan', 'Mus\'ab ibn \'Umair', 'Zayd ibn Harithah'], correctAnswerIndex: 2, explanation: 'Le Prophète a envoyé Mus\'ab à Médine avant l\'Hégire pour enseigner le Coran et préparer la ville à la migration.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_72', question: 'Quel oncle bien-aimé du Prophète a été martyrisé lors de la Bataille de Uhud ?', options: ['Abu Talib', 'Abbas', 'Abu Lahab', 'Hamza ibn Abdul-Muttalib'], correctAnswerIndex: 3, explanation: 'Hamza, connu sous le nom de "Lion d\'Allah", a été tragiquement martyrisé pendant la Bataille de Uhud.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_73', question: 'À quelle grande tribu arabe le Prophète Muhammad appartenait-il ?', options: ['Banu Nadir', 'Banu Qaynuqa', 'Quraysh', 'Khazraj'], correctAnswerIndex: 2, explanation: 'Le Prophète était membre du clan Banu Hashim, qui faisait partie de la tribu proéminente des Quraysh de La Mecque.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_74', question: 'Quel Prophète a été élevé vivant aux cieux et reviendra avant le Jour du Jugement ?', options: ['Prophète Idris', 'Prophète Musa', 'Prophète Isa', 'Prophète Ilyas'], correctAnswerIndex: 2, explanation: 'L\'Islam enseigne que le Prophète Isa (Jésus) n\'a pas été crucifié, mais élevé au ciel par Allah.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_75', question: 'Qui est prophétisé pour revenir sur Terre afin de vaincre le Dajjal (Antéchrist) ?', options: ['Prophète Muhammad', 'Prophète Isa', 'Imam Mahdi', 'Ange Jibreel'], correctAnswerIndex: 1, explanation: 'Le Prophète Isa descendra à Damas et vaincra finalement le Faux Messie (Dajjal).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_76', question: 'Selon l\'eschatologie islamique, quelle créature émergera de la terre pour parler aux gens comme un signe majeur du Dernier Jour ?', options: ['Le Léviathan', 'Dabbat al-Ard (La Bête de la Terre)', 'Buraq', 'Gog et Magog'], correctAnswerIndex: 1, explanation: 'L\'émergence de la Bête de la Terre est l\'un des dix Signes Majeurs du Jour du Jugement.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_77', question: 'Qui était le roi chrétien d\'Abyssinie qui a offert refuge aux premiers Musulmans ?', options: ['Héraclius', 'Khosrow', 'Le Négus (Najashi)', 'Muqawqis'], correctAnswerIndex: 2, explanation: 'Ashama ibn Abjar, le Négus d\'Aksoum, a accueilli les Musulmans qui ont migré en Abyssinie pour échapper à la persécution.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_78', question: 'Quel traité célèbre signé en 6 AH a été initialement considéré comme un revers mais a été déclaré "victoire éclatante" par le Coran ?', options: ['Traité de Médine', 'Traité de Hudaybiyyah', 'Traité de Taif', 'Traité de Tabuk'], correctAnswerIndex: 1, explanation: 'Le Traité de Hudaybiyyah a apporté une paix de 10 ans, permettant à l\'Islam de se répandre rapidement à travers l\'Arabie.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_79', question: 'Quel compagnon a suggéré de creuser une tranchée autour de Médine pour se défendre contre l\'armée de la coalition ?', options: ['Umar ibn Al-Khattab', 'Salman Al-Farsi', 'Bilal ibn Rabah', 'Abu Ubaidah ibn al-Jarrah'], correctAnswerIndex: 1, explanation: 'Salman le Perse a introduit la tactique défensive du creusement d\'une tranchée, une méthode utilisée en Perse mais inconnue des Arabes.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_80', question: 'Qui est le seul compagnon du Prophète mentionné par son nom dans le Coran ?', options: ['Abu Bakr', 'Zayd ibn Harithah', 'Ali ibn Abi Talib', 'Umar ibn Al-Khattab'], correctAnswerIndex: 1, explanation: 'Zayd ibn Harithah est explicitement nommé dans la Sourate Al-Ahzab (33:37).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_81', question: 'Combien y a-t-il approximativement de Sujood of Tilawah (prosternations de récitation) dans le Coran ?', options: ['5', '10', '15', '20'], correctAnswerIndex: 2, explanation: 'La plupart des savants s\'accordent sur 14 ou 15 endroits dans le Coran où une prosternation est requise ou hautement recommandée lors de la lecture.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_82', question: 'Quelle courte Sourate est équivalente en récompense à la lecture du tiers du Coran entier ?', options: ['Sourate Al-Falaq', 'Sourate Al-Kafirun', 'Sourate Al-Ikhlas', 'Sourate An-Nas'], correctAnswerIndex: 2, explanation: 'Le Prophète a dit que lire la Sourate Al-Ikhlas (Chapitre 112) équivaut à un tiers du Coran en raison de sa déclaration pure du monothéisme.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_83', question: 'Quel est le péché absolument le plus impardonnable en Islam (si l\'on meurt sans s\'en repentir) ?', options: ['Le meurtre', 'Le vol', 'Le Shirk (Polythéisme)', 'Le manque de respect envers les parents'], correctAnswerIndex: 2, explanation: 'Le Shirk, associer des partenaires à Allah, est le seul péché dont Allah dit qu\'Il ne le pardonnera pas si une personne meurt dessus.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_84', question: 'Quel est le terme arabe spécifique pour la biographie du Prophète Muhammad ?', options: ['Hadith', 'Tafsir', 'Seerah', 'Aqeedah'], correctAnswerIndex: 2, explanation: 'La Seerah (ou Sirat al-Nabi) désigne les biographies musulmanes traditionnelles de Muhammad.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_85', question: 'Selon la tradition islamique, combien de portes principales (portes) le Jannah (Paradis) a-t-il ?', options: ['4', '6', '8', '12'], correctAnswerIndex: 2, explanation: 'Le Paradis a 8 portes, chacune désignée pour les personnes qui ont excellé dans différents types d\'adoration (prière, jeûne, charité, etc.).', difficulty: 'medium'),
    QuizQuestion(id: 'mid_86', question: 'Quel est le nom de la porte du Paradis spécialement désignée pour ceux qui jeûnent fréquemment ?', options: ['Ar-Rayyan', 'Al-Kawthar', 'Al-Firdaus', 'Al-Adn'], correctAnswerIndex: 0, explanation: 'Ar-Rayyan est la porte spéciale du Paradis par laquelle seuls ceux qui ont observé le jeûne entreront le Jour du Jugement.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_87', question: 'Quel Prophète a reçu le titre de "Ruhullah" (Esprit d\'Allah) ?', options: ['Prophète Adam', 'Prophète Nuh', 'Prophète Isa', 'Prophète Yahya'], correctAnswerIndex: 2, explanation: 'Le Prophète Isa (Jésus) est appelé Ruhullah, car il a été créé par l\'ordre et l\'esprit insufflés par Allah.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_88', question: 'Quel Prophète est appelé "Safiyullah" (L\'Élu d\'Allah) ?', options: ['Prophète Adam', 'Prophète Dawud', 'Prophète Sulaiman', 'Prophète Ayyub'], correctAnswerIndex: 0, explanation: 'Le Prophète Adam, premier homme et prophète, reçoit le titre de Safiyullah.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_89', question: 'Qui a été la toute première personne à accepter l\'Islam après le début de la révélation ?', options: ['Abu Bakr', 'Ali ibn Abi Talib', 'Khadijah bint Khuwaylid', 'Zayd ibn Harithah'], correctAnswerIndex: 2, explanation: 'Son épouse, Khadijah, a été le premier être humain à croire en sa prophétie et à accepter l\'Islam.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_90', question: 'Qui a été le premier jeune/enfant à accepter l\'Islam ?', options: ['Usama ibn Zayd', 'Ali ibn Abi Talib', 'Abdullah ibn Umar', 'Hasan ibn Ali'], correctAnswerIndex: 1, explanation: 'Ali ibn Abi Talib a accepté l\'Islam alors qu\'il avait environ 10 ans, ce qui fait de lui le premier enfant à se convertir.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_91', question: 'Quel compagnon a célèbrement acheté Bilal ibn Rabah à son maître cruel pour le libérer ?', options: ['Uthman ibn Affan', 'Abu Bakr As-Siddiq', 'Abdur Rahman ibn Awf', 'Umar ibn Al-Khattab'], correctAnswerIndex: 1, explanation: 'Abu Bakr a dépensé une grande partie de sa richesse pour acheter et libérer des esclaves musulmans persécutés, y compris Bilal.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_92', question: 'Dans quelle célèbre bataille l\'armée musulmane a-t-elle vaincu de manière décisive l\'Empire sassanide (perse) ?', options: ['Bataille de Yarmouk', 'Bataille d\'Al-Qadisiyyah', 'Bataille de Mut\'ah', 'Bataille de Hunayn'], correctAnswerIndex: 1, explanation: 'La Bataille d\'Al-Qadisiyyah (15 AH) a été une victoire charnière qui a conduit à la conquête de l\'Empire perse.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_93', question: 'Quel est le nom du pont étroit au-dessus de l\'Enfer que toute l\'humanité doit traverser le Jour du Jugement ?', options: ['Al-Kawthar', 'As-Sirat', 'Al-A\'raf', 'Al-Barzakh'], correctAnswerIndex: 1, explanation: 'As-Sirat est un pont décrit comme plus fin qu\'un cheveu et plus tranchant qu\'une épée, que les croyants traverseront avec succès.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_94', question: 'Quel est le terme arabe utilisé dans le Coran pour le Jour de la Résurrection ?', options: ['Yawm al-Jumu\'ah', 'Yawm al-Qiyamah', 'Yawm al-Arafa', 'Yawm al-Nahr'], correctAnswerIndex: 1, explanation: 'Yawm al-Qiyamah se traduit par le Jour de la Résurrection ou le Jour de la Station Debout.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_95', question: 'Quel est le nom de la rivière/du bassin sacré accordé au Prophète Muhammad au Paradis ?', options: ['Zamzam', 'Tasneem', 'Al-Kawthar', 'Salsabil'], correctAnswerIndex: 2, explanation: 'Al-Kawthar est une rivière d\'abondance donnée au Prophète, et son eau est plus douce que le miel et plus blanche que le lait.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_96', question: 'Quelle ville a servi de toute première capitale de l\'État islamique ?', options: ['La Mecque', 'Damas', 'Bagdad', 'Médine'], correctAnswerIndex: 3, explanation: 'Médine (à l\'origine Yathrib) est devenue la première capitale politique et spirituelle de l\'Oumma musulmane après l\'Hégire.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_97', question: 'Sous quel Calife le Coran a-t-il été compilé pour la première fois en un seul manuscrit (Suhuf) ?', options: ['Abu Bakr', 'Umar', 'Uthman', 'Ali'], correctAnswerIndex: 0, explanation: 'Après la Bataille de Yamama, Abu Bakr a ordonné à Zayd ibn Thabit de rassembler tous les fragments écrits et mémorisés du Coran en un seul volume.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_98', question: 'Qui était le célèbre général musulman qui a mené la conquête d\'Al-Andalus (Espagne) ?', options: ['Khalid ibn Al-Walid', 'Amr ibn al-Aas', 'Tariq ibn Ziyad', 'Salahuddin Al-Ayyubi'], correctAnswerIndex: 2, explanation: 'Tariq ibn Ziyad a traversé le détroit (maintenant nommé Gibraltar d\'après lui) et a commencé la domination islamique en Espagne en 711 È.C.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_99', question: 'Qu\'est-ce qu\'un "Hadith Qudsi" ?', options: ['Un hadith faible', 'Une parole d\'un compagnon', 'Un sens d\'Allah, mais formulé par le Prophète', 'Un chapitre du Coran'], correctAnswerIndex: 2, explanation: 'Les Hadiths Qudsi sont des hadiths sacrés où le Prophète relaie un message ou une déclaration directe d\'Allah, distinct du Coran.', difficulty: 'medium'),
    QuizQuestion(id: 'mid_100', question: 'Quelle a été la toute première Sourate (chapitre) révélée au Prophète Muhammad ?', options: ['Sourate Al-Fatiha', 'Sourate Al-Alaq', 'Sourate Al-Muddaththir', 'Sourate Al-Qalam'], correctAnswerIndex: 1, explanation: 'Les cinq premiers versets de la Sourate Al-Alaq (Lis au nom de ton Seigneur...) ont été la toute première révélation dans la Grotte de Hira.', difficulty: 'medium'),
  ];
}

  // --- FRENCH: HARD ---
List<QuizQuestion> _getHardQuestionsFr() {
  return [
    QuizQuestion(id: 'hard_1', question: 'Comment appelle-t-on l\'approche du Tafsir qui s\'appuie fortement sur les savants islamiques classiques et la transmission ?', options: ['Tafsir Bil-Ma\'thour', 'Tafsir Bil-Ra\'y', 'Tafsir Bil-Ijma', 'Tafsir Bil-Ijtihad'], correctAnswerIndex: 0, explanation: 'Le Tafsir Bil-Ma\'thour est l\'exégèse basée sur les traditions transmises du Prophète et de ses compagnons.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_2', question: 'Quel est le terme utilisé dans les sciences coraniques pour désigner les circonstances historiques spécifiques ou les raisons de la révélation d\'un verset ?', options: ['Tafsir al-Jalalayn', 'Asbab al-Nouzoul', 'Al-Nasikh wal-Mansoukh', 'Makki wa Madani'], correctAnswerIndex: 1, explanation: 'Asbab al-Nouzoul désigne les événements historiques spécifiques ou les questions qui ont provoqué la révélation de versets particuliers.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_3', question: 'Qu\'est-ce que le concept de "Naskh" dans la jurisprudence coranique ?', options: ['Copie de manuscrits', 'L\'abrogation des révélations antérieures par des révélations ultérieures', 'La narration du Hadith', 'La spécification des règles générales'], correctAnswerIndex: 1, explanation: 'Le Naskh désigne l\'abrogation de règles coraniques antérieures par des révélations plus tardives et plus spécifiques.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_4', question: 'Combien de fois le Prophète Muhammad est-il explicitement mentionné par son nom "Muhammad" dans le Coran ?', options: ['4 fois', '5 fois', '25 fois', '136 fois'], correctAnswerIndex: 0, explanation: 'Le nom "Muhammad" apparaît exactement 4 fois dans le Coran (dans les Sourates Aal-Imran, Al-Ahzab, Muhammad et Al-Fath).', difficulty: 'hard'),
    QuizQuestion(id: 'hard_5', question: 'Qu\'est-ce que le "Matn" dans la terminologie du Hadith ?', options: ['La chaîne des narrateurs', 'Le texte/corps réel du hadith', 'Le narrateur lui-même', 'Le sujet discuté'], correctAnswerIndex: 1, explanation: 'Le Matn désigne le texte ou le corps réel d\'un hadith, par opposition à l\'Isnad (chaîne de narration).', difficulty: 'hard'),
    QuizQuestion(id: 'hard_6', question: 'Quelle Sourate contient le plus long verset unique du Coran, connu sous le nom d\'Ayat al-Dayn ?', options: ['Sourate Al-Baqarah', 'Sourate Aal-Imran', 'Sourate An-Nisa', 'Sourate An-Noor'], correctAnswerIndex: 0, explanation: 'Le verset 282 de la Sourate Al-Baqarah, qui détaille l\'enregistrement des dettes, est le plus long verset unique du Coran.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_7', question: 'Qu\'est-ce que l\'"Ijtihad" dans la jurisprudence islamique ?', options: ['Suivre aveuglément le consensus des savants', 'Le raisonnement indépendant par des savants qualifiés pour déduire des règles', 'Mémoriser tout le Coran', 'Enseigner la loi islamique'], correctAnswerIndex: 1, explanation: 'L\'Ijtihad est l\'effort intellectuel indépendant de savants qualifiés pour déduire des règles islamiques à partir des sources primaires.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_8', question: 'Combien de Sourates du Coran commencent par les lettres disjointes exactes "Alif-Lam-Mim" ?', options: ['3', '4', '5', '6'], correctAnswerIndex: 3, explanation: 'Six Sourates commencent par Alif-Lam-Mim : Al-Baqarah, Aal-Imran, Al-Ankabut, Ar-Rum, Luqman et As-Sajdah.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_9', question: 'Qu\'est-ce que la "Sunnat Allah" mentionnée dans le Coran ?', options: ['Les routines quotidiennes des anges', 'Les lois et modèles universels immuables établis par Allah', 'Uniquement les pratiques prophétiques', 'Les règles de la finance islamique'], correctAnswerIndex: 1, explanation: 'La Sunnat Allah désigne les lois et modèles immuables et constants établis par Allah dans Sa création.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_10', question: 'Quel Prophète est mentionné par son nom le plus fréquemment dans le Coran ?', options: ['Prophète Muhammad', 'Prophète Ibrahim', 'Prophète Moussa', 'Prophète Issa'], correctAnswerIndex: 2, explanation: 'Le Prophète Moussa (Moïse) est mentionné par son nom 136 fois, plus fréquemment que tout autre prophète dans le Coran.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_11', question: 'Dans les Ousoul al-Fiqh, quelle est la différence entre "Haram" et "Makrouh" ?', options: ['Aucune différence', 'Haram est strictement interdit tandis que Makrouh est détesté mais non pécheur', 'Makrouh est strictement interdit, Haram est légèrement détesté', 'Les deux entraînent des péchés majeurs'], correctAnswerIndex: 1, explanation: 'Haram est une interdiction absolue entraînant un péché, tandis que Makrouh est une action déconseillée par la Charia mais non strictement punissable.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_12', question: 'Qu\'est-ce que l\'"Ikhtilaf" dans la jurisprudence islamique ?', options: ['Un désaccord académique légitime sur des questions juridiques', 'La succession politique', 'Le conflit entre nations', 'La différence dans les horaires de prière'], correctAnswerIndex: 0, explanation: 'L\'Ikhtilaf désigne le désaccord accepté et légitime entre les juristes islamiques sur des questions secondaires de droit.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_13', question: 'Quelle Sourate contient exactement 18 prophètes mentionnés par leur nom dans des versets consécutifs (versets 83-86) ?', options: ['Sourate Al-Anbiya', 'Sourate Al-An\'am', 'Sourate Maryam', 'Sourate Al-Baqarah'], correctAnswerIndex: 1, explanation: 'La Sourate Al-An\'am énumère 18 prophètes séquentiellement, présentant un résumé profond de la lignée prophétique.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_14', question: 'Quel est le principe de "Darourah" en droit islamique ?', options: ['L\'intérêt public général', 'La nécessité dicte des exceptions, levant temporairement les interdictions', 'La préférence personnelle', 'Le droit coutumier'], correctAnswerIndex: 1, explanation: 'La Darourah est une maxime juridique où une nécessité grave permet ce qui est autrement interdit pour préserver la vie ou prévenir un grand préjudice.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_15', question: 'Combien de Sourates du Coran portent le nom d\'animaux ou d\'insectes ?', options: ['4', '5', '6', '7'], correctAnswerIndex: 2, explanation: 'Six Sourates : Al-Baqarah (Vache), Al-An\'am (Bestiaux), An-Nahl (Abeille), An-Naml (Fourmi), Al-Ankabut (Araignée), Al-Fil (Éléphant).', difficulty: 'hard'),
    QuizQuestion(id: 'hard_16', question: 'Qu\'est-ce que le "Tawatur" (Mutawatir) dans les études du Hadith ?', options: ['Une chaîne de narration isolée unique', 'Une narration rapportée par tant de personnes à chaque niveau qu\'une conspiration pour mentir est impossible', 'Un hadith faible', 'Un hadith fabriqué'], correctAnswerIndex: 1, explanation: 'Un hadith Mutawatir produit une certitude absolue car il est transmis par un groupe massif et diversifié à chaque génération.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_17', question: 'Quelle Sourate est largement connue pour contenir les lois les plus complètes concernant l\'héritage (Fara\'id) ?', options: ['Sourate Al-Baqarah', 'Sourate Aal-Imran', 'Sourate An-Nisa', 'Sourate At-Tawbah'], correctAnswerIndex: 2, explanation: 'La Sourate An-Nisa (Chapitre 4) fournit les règles les plus détaillées et fondamentales sur le système d\'héritage islamique.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_18', question: 'Qu\'est-ce que le "Tawhid Ar-Rouboubiyyah" ?', options: ['Croire en tous les prophètes également', 'La croyance en la Seigneurie absolue, la création et le contrôle d\'Allah', 'Adorer Allah seul', 'La croyance au Jour du Jugement'], correctAnswerIndex: 1, explanation: 'Le Tawhid Ar-Rouboubiyyah affirme qu\'Allah est le seul Créateur, Soutien et Maître de l\'univers.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_19', question: 'Dans le Moustalah al-Hadith, qu\'est-ce qui constitue un hadith "Gharib" ?', options: ['Un texte bizarre ou étrange', 'Un hadith rapporté par un seul narrateur à n\'importe quel stade de la chaîne', 'Un hadith dont le dernier narrateur est manquant', 'Un hadith contredisant le Coran'], correctAnswerIndex: 1, explanation: 'Un hadith Gharib est celui où la chaîne repose sur un seul narrateur à un certain maillon, ce qui le rend "isolé".', difficulty: 'hard'),
    QuizQuestion(id: 'hard_20', question: 'Que signifie formellement "Seerah Nabawiyyah" ?', options: ['Les lois alimentaires islamiques', 'La biographie complète et les campagnes du Prophète Muhammad', 'L\'interprétation des rêves', 'La collection de poèmes anciens'], correctAnswerIndex: 1, explanation: 'La Seerah est l\'étude dédiée de la vie, du caractère, des traités, des batailles et de l\'histoire chronologique du Prophète.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_21', question: 'Quel est le focus spécifique de la science connue sous le nom de "Moustalah al-Hadith" ?', options: ['Mémoriser les textes de hadiths', 'La terminologie, les règles et les critères pour évaluer l\'authenticité des narrateurs et des chaînes de Hadith', 'Traduire les hadiths dans d\'autres langues', 'Appliquer les hadiths à la politique moderne'], correctAnswerIndex: 1, explanation: 'Le Moustalah al-Hadith étudie systématiquement les chaînes (Isnad) et le texte (Matn) pour classer un hadith comme Sahih, Da\'if, etc.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_22', question: 'Selon la majorité des savants, quel verset est considéré comme le tout dernier verset du Coran révélé ?', options: ['2:281 (Sourate Al-Baqarah)', '5:3 (Sourate Al-Ma\'idah)', '9:129 (Sourate At-Tawbah)', '110:3 (Sourate An-Nasr)'], correctAnswerIndex: 0, explanation: 'La plupart des savants classiques s\'accordent sur le fait que le verset 2:281 ("Et craignez un jour où vous serez ramenés vers Allah...") fut la dernière révélation.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_23', question: 'Qu\'est-ce que la doctrine des "Maqasid al-Chari\'ah" (Les Cinq Objectifs Supérieurs) ?', options: ['Les Cinq Piliers de l\'Islam', 'La préservation de la Religion, la Vie, l\'Intellect, la Lignée et la Propriété', 'Les cinq prières quotidiennes', 'Les cinq péchés majeurs'], correctAnswerIndex: 1, explanation: 'Les Maqasid al-Chari\'ah représentent les objectifs ultimes de la loi islamique : protéger la foi, la vie, l\'intellect, la famille et la richesse.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_24', question: 'Combien de chapitres du Coran commencent sans la Bismillah ?', options: ['0', '1', '2', '5'], correctAnswerIndex: 1, explanation: 'La Sourate At-Tawbah (Chapitre 9) est le seul chapitre qui ne commence pas par la Basmalah.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_25', question: 'Dans l\'exégèse coranique, quelle est la différence entre les versets "Mouhkam" et "Moutachabih" ?', options: ['Mecquois vs Médinois', 'Versets clairs et fondamentaux vs versets ambigus ou allégoriques', 'Versets longs vs courts', 'Versets abrogeant vs abrogés'], correctAnswerIndex: 1, explanation: 'Les versets Mouhkam ont des significations claires et sans équivoque, tandis que les versets Moutachabih sont allégoriques et leur réalité exacte est connue d\'Allah.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_26', question: 'Lequel des éléments suivants décrit le "Tafsir bi al-Ra\'y" ?', options: ['Tafsir basé uniquement sur les traditions prophétiques', 'Tafsir basé sur le raisonnement rationnel indépendant et la déduction linguistique', 'Tafsir par consensus', 'Tafsir basé sur les traditions juives'], correctAnswerIndex: 1, explanation: 'Le Tafsir bi al-Ra\'y utilise l\'intellect, la grammaire arabe et la déduction logique, contrastant avec le Tafsir bil-Ma\'thour (transmission).', difficulty: 'hard'),
    QuizQuestion(id: 'hard_27', question: 'Qu\'est-ce que l\'"Isnad" dans la terminologie du hadith ?', options: ['Le texte du hadith', 'La chaîne des narrateurs par laquelle le hadith est transmis', 'Le sujet du hadith', 'La classification du hadith'], correctAnswerIndex: 1, explanation: 'L\'Isnad fournit la lignée historique de qui a entendu le rapport de qui, essentielle pour la vérification.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_28', question: 'Dans les Ousoul al-Fiqh, qu\'est-ce que la \'Illah dans un Qiyas (analogie) ?', options: ['La nouvelle règle', 'Le cas original', 'La cause effective ou la raison sous-jacente qui justifie la règle', 'Le consensus'], correctAnswerIndex: 2, explanation: 'La \'Illah est l\'attribut partagé entre le cas original (Asl) et le nouveau cas (Far\') qui nécessite la même règle.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_29', question: 'Quel type de Hajj implique d\'accomplir la Omra, de sortir complètement de l\'Ihram, puis de rentrer en Ihram pour le Hajj plus tard ?', options: ['Hajj Ifrad', 'Hajj Qiran', 'Hajj Tamattou\'', 'Hajj Badal'], correctAnswerIndex: 2, explanation: 'Le Hajj Tamattou\' permet à un pèlerin d\'accomplir la Omra, de profiter des restrictions normales, puis d\'assumer un nouvel Ihram pour le Hajj le 8 Dhoul-Hijjah.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_30', question: 'Qu\'est-ce que le concept de "Tawhid Al-Oulouhiyyah" ?', options: ['La croyance aux anges', 'La croyance qu\'Allah seul a le droit exclusif d\'être adoré', 'La croyance au destin', 'La croyance aux prophètes'], correctAnswerIndex: 1, explanation: 'Le Tawhid Al-Oulouhiyyah (ou Al-Ibadah) affirme que toutes les formes d\'adoration doivent être dirigées uniquement vers Allah sans associés.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_31', question: 'Quel savant a compilé "Sahih Al-Boukhari", le livre le plus authentique après le Coran ?', options: ['Mouslim ibn Al-Hajjaj', 'Muhammad ibn Isma\'il Al-Boukhari', 'At-Tirmidhi', 'Abou Dawood'], correctAnswerIndex: 1, explanation: 'L\'Imam Al-Boukhari a passé au crible des centaines de milliers de narrations pour compiler sa collection Sahih remarquablement rigoureuse.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_32', question: 'Qu\'est-ce qui définit une Sourate "Médinoise" (Madani) ?', options: ['Elle mentionne Médine', 'Elle a été révélée après l\'Hégire (migration) à Médine, même si géographiquement en dehors', 'Elle contient uniquement des règles juridiques', 'Elle a été révélée à l\'intérieur d\'une mosquée'], correctAnswerIndex: 1, explanation: 'La classification est temporelle : tout ce qui a été révélé après la migration du Prophète à Médine est considéré comme Madani.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_33', question: 'Quelles sont les quatre sources primaires de la Charia selon la majorité de la jurisprudence sunnite ?', options: ['Coran, Sunnah, Qiyas (Analogie) et Ijma (Consensus)', 'Coran, Sunnah, Histoire et Logique', 'Coran, Règles des Califes, Logique et Coutume', 'Coran, Sunnah, Rêves et Philosophie'], correctAnswerIndex: 0, explanation: 'Les quatre sources fondamentales convenues des Ousoul al-Fiqh sont le Coran, la Sunnah, l\'Ijma et le Qiyas.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_34', question: 'Quel est le seuil minimum (Nisab) pour la Zakat sur l\'or pur ?', options: ['21 grammes', '50 grammes', '85 grammes (ou 20 dinars)', '100 grammes'], correctAnswerIndex: 2, explanation: 'Le Nisab pour l\'or a été fixé par le Prophète à 20 mithqals/dinars, ce qui équivaut à environ 85 grammes d\'or pur.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_35', question: 'Qu\'est-ce que le "Fiqh al-Maqasid" ?', options: ['La jurisprudence traditionnelle', 'La jurisprudence qui interprète les règles en fonction des objectifs et sagesses globaux de la Charia', 'Le littéralisme moderne', 'L\'abolition des anciennes lois'], correctAnswerIndex: 1, explanation: 'Le Fiqh al-Maqasid se concentre sur le "pourquoi" derrière la loi, garantissant que les règles juridiques remplissent les objectifs plus larges de justice et de préservation.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_36', question: 'Quelle Sourate contient le récit détaillé de Dhou\'l-Qarnayn ?', options: ['Sourate Al-Kahf', 'Sourate Youssouf', 'Sourate Luqman', 'Sourate As-Saffat'], correctAnswerIndex: 0, explanation: 'La Sourate Al-Kahf (Chapitre 18) relate l\'histoire de Dhou\'l-Qarnayn et sa construction d\'une grande barrière.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_37', question: 'Qu\'est-ce que les "Ousoul Al-Fiqh" ?', options: ['Le corpus des lois islamiques', 'L\'étude des origines, principes et méthodologie de dérivation de la jurisprudence islamique', 'La compilation du Hadith', 'Les biographies des juristes'], correctAnswerIndex: 1, explanation: 'Les Ousoul Al-Fiqh constituent la méthodologie et le cadre utilisés par les savants pour extraire les lois pratiques des textes primaires.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_38', question: 'Qu\'est-ce que le "Gharar" dans le droit commercial islamique ?', options: ['Un profit fixe', 'L\'intérêt ou l\'usure', 'L\'incertitude excessive, l\'ambiguïté ou la tromperie dans un contrat', 'Le don caritatif'], correctAnswerIndex: 2, explanation: 'Le Gharar désigne les ventes hasardeuses ou ambiguës où les détails de l\'article, du prix ou de la livraison sont très incertains.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_39', question: 'Qu\'est-ce qu\'un hadith "Moursal" ?', options: ['Un hadith authentifié', 'Un hadith où un Tabi\'i (Successeur) cite directement le Prophète, omettant le Compagnon', 'Un hadith forgé', 'Un hadith célèbre répété'], correctAnswerIndex: 1, explanation: 'Dans un hadith Moursal, le lien entre le Successeur et le Prophète (le Compagnon) est manquant dans la chaîne.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_40', question: 'Qu\'est-ce que le "Riba al-Fadl" ?', options: ['L\'intérêt facturé sur les prêts différés', 'L\'échange simultané de marchandises ribawiyyah identiques (comme l\'or contre l\'or) en quantités inégales', 'Une taxe sur les produits agricoles', 'Le profit du commerce de devises transfrontalières'], correctAnswerIndex: 1, explanation: 'Le Riba al-Fadl se produit lorsque des marchandises identiques spécifiques (comme le blé, les dattes, l\'or) sont échangées sur place en quantités inégales.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_41', question: 'Qui est largement considéré comme le fondateur de la science des Ousoul Al-Fiqh en tant que discipline documentée indépendante ?', options: ['Imam Abou Hanifa', 'Imam Malik', 'Imam Ach-Chafi\'i', 'Imam Ahmad ibn Hanbal'], correctAnswerIndex: 2, explanation: 'L\'Imam Ach-Chafi\'i a systématisé la méthodologie de dérivation de la loi islamique dans son livre fondateur, "Al-Risala".', difficulty: 'hard'),
    QuizQuestion(id: 'hard_42', question: 'Quelle Sourate est aussi appelée "Celle qui dénonce" (Al-Fadhihah) parce qu\'elle a exposé les hypocrites de Médine ?', options: ['Sourate Al-Anfal', 'Sourate At-Tawbah', 'Sourate An-Noor', 'Sourate Al-Ahzab'], correctAnswerIndex: 1, explanation: 'La Sourate At-Tawbah a sévèrement réprimandé et exposé les complots cachés des hypocrites lors de l\'expédition de Tabuk.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_43', question: 'Quel compagnon a suggéré la tactique militaire de creuser une tranchée lors de la Bataille d\'Al-Ahzab ?', options: ['Abou Oubaida ibn Al-Jarrah', 'Sa\'d ibn Mou\'adh', 'Salman Al-Farsi', 'Ammar ibn Yasir'], correctAnswerIndex: 2, explanation: 'Salman le Perse a introduit la stratégie défensive de la tranchée, qui était inconnue des Arabes à l\'époque.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_44', question: 'Dans la science islamique de l\'héritage, qu\'est-ce que "Al-Awl" ?', options: ['Quand les parts fixes dépassent la succession totale, donc la base est augmentée, réduisant proportionnellement chaque part', 'Quand les parts fixes laissent un reste donné à la charité', 'L\'exclusion complète d\'un parent éloigné', 'La distribution égale indépendamment du sexe'], correctAnswerIndex: 0, explanation: 'Al-Awl est un ajustement mathématique appliqué lorsque la somme des parts fractionnaires totalise plus de 100% de la succession.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_45', question: 'Quel est le focus principal de la science savante connue sous le nom de "Al-Jarh wa At-Ta\'deel" ?', options: ['Expliquer le vocabulaire coranique difficile', 'Critiquer et évaluer la fiabilité, la mémoire et le caractère des narrateurs de Hadith', 'Émettre des fatwas modernes', 'Réconcilier les différences dans les formats de prière'], correctAnswerIndex: 1, explanation: 'Cette science critique valide (Ta\'deel) ou invalide (Jarh) les narrateurs pour garantir que seuls les hadiths exacts sont acceptés.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_46', question: 'Qui a été officiellement chargé par le Calife Abou Bakr de diriger la compilation initiale du Coran en un seul volume maître ?', options: ['Ali ibn Abi Talib', 'Othman ibn Affan', 'Zayd ibn Thabit', 'Abdullah ibn Masoud'], correctAnswerIndex: 2, explanation: 'Zayd ibn Thabit, l\'un des principaux scribes de la révélation, était grandement digne de confiance pour cette tâche monumentale.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_47', question: 'À quoi le terme "Ahrouf" fait-il référence dans le contexte du Coran ?', options: ['Les styles calligraphiques', 'Les sept dialectes/modes divinement permis dans lesquels le Coran a été révélé', 'Les règles du Tajweed', 'Les chapitres révélés à La Mecque'], correctAnswerIndex: 1, explanation: 'Le Prophète a déclaré que le Coran a été révélé en sept "Ahrouf" pour accommoder les divers dialectes des tribus arabes.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_48', question: 'Qu\'est-ce que l\'"Idgham" dans les règles du Tajweed ?', options: ['Prononciation claire', 'La fusion d\'une lettre non vocalisée dans une lettre vocalisée, les rendant une seule lettre accentuée', 'Cacher un son dans le nez', 'S\'arrêter à la fin d\'un verset'], correctAnswerIndex: 1, explanation: 'Idgham signifie assimilation ou fusion, généralement appliqué à un Noun silencieux fusionnant dans des lettres comme Ya ou Waw.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_49', question: 'Dans la terminologie du Hadith, qu\'est-ce qu\'un hadith "Mou\'allaq" (Suspendu) ?', options: ['Un hadith manquant totalement de chaîne', 'Un hadith manquant un ou plusieurs narrateurs consécutifs depuis le début de sa chaîne', 'Un hadith rapporté par un menteur connu', 'Un hadith qui n\'a pas été mis en pratique'], correctAnswerIndex: 1, explanation: 'Un hadith Mou\'allaq se produit lorsque le collectionneur (comme Al-Boukhari) omet le(s) premier(s) narrateur(s) de son côté de la chaîne.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_50', question: 'Quel compagnon a été uniquement titré "Le Gardien de confiance de cette Oumma" (Ameen al-Oummah) par le Prophète ?', options: ['Abou Bakr As-Siddiq', 'Omar ibn Al-Khattab', 'Abou Oubaida ibn al-Jarrah', 'Zoubayr ibn al-Awwam'], correctAnswerIndex: 2, explanation: 'Abou Oubaida a reçu ce titre spécifique en raison de sa fiabilité profonde et de son caractère inébranlable.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_51', question: 'En Fiqh, quel est le terme pour l\'eau qui a changé de couleur, de goût ou d\'odeur à cause d\'impuretés ?', options: ['Ma\' Moutlaq', 'Ma\' Mousta\'mal', 'Ma\' Najas', 'Ma\' Tahir'], correctAnswerIndex: 2, explanation: 'Ma\' Najas est une eau impure qui ne peut pas être utilisée pour le Woudou ou le Ghusl en raison d\'être mélangée à une najasah (impureté).', difficulty: 'hard'),
    QuizQuestion(id: 'hard_52', question: 'Qu\'est-ce que la "Tawriyah" dans l\'éthique islamique ?', options: ['Mensonge flagrant', 'Dire des mots techniquement vrais mais transmettant un sens différent à l\'auditeur, utilisé pour éviter le mensonge direct dans des situations difficiles', 'Prêter serment', 'Rompre une promesse'], correctAnswerIndex: 1, explanation: 'La Tawriyah est permise dans certaines circonstances pour protéger la vie ou prévenir un préjudice sans recourir à un mensonge pur et simple.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_53', question: 'Quel compagnon a reçu l\'honneur que son seul témoignage soit légalement égal au témoignage de deux hommes ?', options: ['Khouzaymah ibn Thabit', 'Ammar ibn Yasir', 'Bilal ibn Rabah', 'Abou Dharr Al-Ghifari'], correctAnswerIndex: 0, explanation: 'Le Prophète a rendu le témoignage de Khouzaymah égal à deux hommes après que Khouzaymah ait témoigné pour le Prophète dans un différend simplement par foi.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_54', question: 'Qu\'est-ce que la "Mouwalah" dans le contexte du Woudou (ablution) ?', options: ['L\'intention de purifier', 'Laver les parties du corps prescrites en succession ininterrompue avant que la partie précédente ne sèche', 'Essuyer sur les chaussettes', 'Utiliser le Siwak'], correctAnswerIndex: 1, explanation: 'La Mouwalah (continuité) est un élément essentiel dans certaines écoles de Fiqh, signifiant qu\'il ne faut pas faire une longue pause pendant le Woudou.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_55', question: 'Quel a été le déclencheur principal des guerres de Ridda (Apostasie) durant le califat d\'Abou Bakr ?', options: ['L\'invasion de Rome', 'Plusieurs tribus refusant ouvertement de payer la Zakat à l\'État central', 'Un différend frontalier', 'Le rejet du calendrier hégirien'], correctAnswerIndex: 1, explanation: 'Bien que certains aient faussement prétendu à la prophétie, une cause majeure était des tribus prétendant que la Zakat n\'était due qu\'au Prophète, pas à Abou Bakr.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_56', question: 'Quelle bataille contre les Perses est célèbre sous le nom de "Bataille du Pont" ?', options: ['Bataille d\'Al-Qadissiyyah', 'Bataille du Pont (Waq\'at al-Jisr)', 'Bataille de Nahavand', 'Bataille de Yarmouk'], correctAnswerIndex: 1, explanation: 'Dirigée par Abou Oubayd al-Thaqafi, ce fut une défaite rare et sévère pour les Musulmans en raison d\'avoir traversé un pont vers un désavantage tactique.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_57', question: 'Que signifie "Ourf" comme source secondaire dans la jurisprudence islamique ?', options: ['Le consensus des savants', 'La pratique coutumière établie ou la connaissance commune d\'une société qui ne contredit pas la Charia', 'L\'analogie', 'L\'intérêt public'], correctAnswerIndex: 1, explanation: 'L\'Ourf permet à la loi islamique d\'accommoder les coutumes et traditions locales dans des matières comme les contrats commerciaux ou les cadeaux de mariage.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_58', question: 'Qui a été le premier Calife à établir un Bait al-Mal (Trésor Public) systématique et des registres d\'État formels (Diwan) ?', options: ['Abou Bakr', 'Omar ibn Al-Khattab', 'Othman ibn Affan', 'Ali ibn Abi Talib'], correctAnswerIndex: 1, explanation: 'Omar a institué des systèmes administratifs complexes, y compris des pensions et des trésors organisés, pour gérer l\'empire en expansion.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_59', question: 'Quelle Sourate a été révélée immédiatement lors du voyage de retour du Traité de Hudaybiyyah, le déclarant une "victoire éclatante" ?', options: ['Sourate Al-Fath', 'Sourate Muhammad', 'Sourate Al-Houjourat', 'Sourate Qaf'], correctAnswerIndex: 0, explanation: 'La Sourate Al-Fath (La Victoire) a été révélée pour rassurer les compagnons que le traité apparemment désavantageux était en fait un triomphe.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_60', question: 'Dans la science du Hadith, qu\'est-ce que le "Tadlis" ?', options: ['Mémorisation des chaînes', 'Un narrateur dissimulant un défaut dans la chaîne, souvent en impliquant qu\'il a entendu directement d\'un contemporain qu\'il n\'a pas rencontré', 'Écrire les hadiths', 'Classer un hadith comme fabriqué'], correctAnswerIndex: 1, explanation: 'Le Tadlis est un défaut subtil où un narrateur utilise un libellé ambigu (comme "d\'après") pour sauter un maillon faible sans mentir explicitement.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_61', question: 'Quelle est l\'expiation sévère (Kaffarah) pour avoir délibérément rompu un jeûne obligatoire de Ramadan par des relations conjugales ?', options: ['Jeûner 3 jours', 'Affranchir un esclave, OU jeûner 60 jours consécutifs, OU nourrir 60 pauvres', 'Payer une petite amende', 'Rattraper uniquement le jour unique'], correctAnswerIndex: 1, explanation: 'Cette lourde Kaffarah est appliquée dans un ordre strict de capacité pour souligner la sainteté du mois de jeûne.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_62', question: 'Qu\'est-ce que l\'"Istihsan" principalement utilisé dans l\'école hanafite de Fiqh ?', options: ['Littéralisme strict', 'Préférence jurisprudentielle : abandonner une analogie légale stricte pour une règle plus équitable ou pratique', 'Consensus de Médine', 'Rejet du Hadith'], correctAnswerIndex: 1, explanation: 'L\'Istihsan permet à un juriste de rechercher l\'équité et d\'éviter les difficultés lorsque l\'application d\'un Qiyas strict conduirait à un résultat injuste.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_63', question: 'Quel savant classique a rédigé "Al-Mouwatta", le texte fondateur de son école respective de Fiqh ?', options: ['Imam Abou Hanifa', 'Imam Malik ibn Anas', 'Imam Ach-Chafi\'i', 'Imam Ahmad ibn Hanbal'], correctAnswerIndex: 1, explanation: 'L\'Imam Malik a écrit Al-Mouwatta, servant à la fois de première collection de hadiths authentiques et de recueil des pratiques des gens de Médine.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_64', question: 'Quelle est la condition du "Hawl" concernant le paiement de la Zakat ?', options: ['Être libre de dettes', 'La richesse doit atteindre ou dépasser le Nisab', 'La richesse doit être en possession pendant une année lunaire complète', 'La richesse doit être de l\'or'], correctAnswerIndex: 2, explanation: 'La Zakat n\'est due que sur la richesse accumulée qui est restée au-dessus du seuil minimum (Nisab) pendant une année lunaire entière (Hawl).', difficulty: 'hard'),
    QuizQuestion(id: 'hard_65', question: 'Qu\'est-ce que le "Sujoud al-Sahw" ?', options: ['Prosternation de récitation', 'Deux prosternations d\'oubli effectuées à la fin de la prière pour compenser des erreurs mineures', 'Prosternation de remerciement', 'La prosternation dans la tombe'], correctAnswerIndex: 1, explanation: 'Si un adorateur ajoute, omet ou doute d\'une partie de la prière, le Sujoud al-Sahw est effectué pour amender la prière.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_66', question: 'Dans le système d\'héritage islamique, qui sont les "Ashab al-Fouroud" ?', options: ['Les parents masculins uniquement', 'Les héritiers qui ont des parts fractionnaires spécifiques et fixes prescrites dans le Coran (par exemple, 1/2, 1/4, 1/8)', 'Les organisations caritatives', 'Les enfants adoptés'], correctAnswerIndex: 1, explanation: 'Les Ashab al-Fouroud sont les héritiers primaires dont les portions exactes sont divinement mandatées avant que le reste n\'aille aux \'Asabah (héritiers résiduaires).', difficulty: 'hard'),
    QuizQuestion(id: 'hard_67', question: 'Quelle Qira\'ah (style de récitation coranique) est la plus largement récitée dans le monde aujourd\'hui ?', options: ['Warsh \'an Nafi\'', 'Qaloun \'an Nafi\'', 'Hafs \'an \'Asim', 'Al-Douri \'an Abou Amr'], correctAnswerIndex: 2, explanation: 'La récitation de Hafs transmise de l\'Imam \'Asim de Koufa est l\'impression et la récitation standard pour la grande majorité des Musulmans.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_68', question: 'Qu\'est-ce que le "Shirk al-Asghar" (Polythéisme mineur) ?', options: ['Adorer des idoles', 'Le polythéisme caché, comme le Riya (montrer de bonnes actions pour la louange humaine)', 'Nier l\'existence d\'Allah', 'Insulter un Prophète'], correctAnswerIndex: 1, explanation: 'Le Shirk mineur ne fait pas sortir quelqu\'un de l\'Islam mais annule sévèrement la récompense de l\'acte accompli pour l\'ostentation plutôt que pour Allah.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_69', question: 'Qu\'est-ce que l\'"Ikhfa" dans les règles du Tajweed ?', options: ['Prononciation claire de Noun', 'Cacher le son du Noun Sakina ou du Tanween en créant un son nasal (Ghunnah)', 'Rebondir la lettre', 'Fusionner complètement les lettres'], correctAnswerIndex: 1, explanation: 'L\'Ikhfa implique un état entre la prononciation claire (Izhar) et la fusion (Idgham), conservant un son nasal.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_70', question: 'Quel compagnon a célèbrement défendu le Prophète lors de la Bataille de Uhud, subissant de nombreuses blessures et attrapant des flèches à mains nues ?', options: ['Talhah ibn Oubaydullah', 'Sa\'d ibn Abi Waqqas', 'Abou Doujanah', 'Ali ibn Abi Talib'], correctAnswerIndex: 0, explanation: 'Talhah s\'est battu férocement pour protéger le Prophète, ce qui a entraîné une main paralysée et le Prophète l\'a appelé un "martyr vivant".', difficulty: 'hard'),
    QuizQuestion(id: 'hard_71', question: 'Qu\'est-ce que "Al-Wala\' wal-Bara\'" dans la théologie islamique ?', options: ['L\'équilibre de la crainte et de l\'espoir', 'La loyauté et l\'amour pour Allah et les croyants, et le désaveu du faux et de l\'oppression', 'La prédestination et le libre arbitre', 'La purification physique et spirituelle'], correctAnswerIndex: 1, explanation: 'Cette doctrine se concentre sur les allégeances internes, exhortant les Musulmans à aligner leur amour et leur désaveu purement sur les commandements d\'Allah.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_72', question: 'Quel événement historique s\'est produit comme réponse militaire directe à la violation du Traité de Hudaybiyyah par les Qurayshites ?', options: ['Bataille de Tabuk', 'Bataille de Hounayn', 'La Conquête de La Mecque (Fath Makkah)', 'Bataille de Mou\'tah'], correctAnswerIndex: 2, explanation: 'Lorsque les alliés des Qurayshites ont attaqué les alliés des Musulmans, le traité a été annulé, conduisant le Prophète à marcher sur La Mecque en 8 AH.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_73', question: 'Dans la classification du Hadith, qu\'est-ce qu\'un hadith "Mounqati\'" ?', options: ['Une chaîne continuellement liée', 'Un hadith avec une chaîne brisée à n\'importe quel endroit (narrateur manquant), sauf au niveau du Successeur', 'Un hadith parfaitement authentique', 'Un hadith fortement corroboré'], correctAnswerIndex: 1, explanation: 'Un hadith Mounqati\' (coupé) manque de continuité, ce qui le classe généralement comme faible en raison du narrateur manquant inconnu.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_74', question: 'Qu\'est-ce que le "Waqf" en droit islamique ?', options: ['Une taxe sur la terre', 'Une dotation religieuse ou caritative permanente et inaliénable de biens ou d\'actifs', 'Une procédure de divorce', 'Un bail temporaire'], correctAnswerIndex: 1, explanation: 'Le Waqf garantit que le corpus d\'une propriété est maintenu intact tandis que ses profits ou usages générés sont dirigés vers une cause caritative indéfiniment.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_75', question: 'Quel éminent savant a rédigé "Al-Moustasfa min \'Ilm al-Ousoul", une œuvre monumentale en Ousoul al-Fiqh ?', options: ['Ibn Rouchd', 'Al-Ghazali', 'Al-Shatibi', 'Ibn Hazm'], correctAnswerIndex: 1, explanation: 'Abou Hamid al-Ghazali a rédigé Al-Moustasfa, qui est considéré comme l\'un des quatre piliers fondateurs de la littérature des Ousoul al-Fiqh.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_76', question: 'Dans la finance islamique, qu\'est-ce qui décrit une transaction "Mourabaha" ?', options: ['Un prêt portant intérêt', 'Un partenariat où l\'un fournit le capital et l\'autre le travail', 'Une vente à coût majoré où le coût exact et la marge sont divulgués à l\'acheteur', 'Un contrat de jeu'], correctAnswerIndex: 2, explanation: 'La Mourabaha est une structure de financement islamique très courante agissant comme une vente transparente plutôt qu\'un prêt à intérêt.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_77', question: 'Quel est le seul compagnon à avoir rapporté un hadith sur le Dajjal (d\'un converti chrétien nommé Tamim Al-Dari) directement au Prophète, que le Prophète a ensuite raconté à la congrégation ?', options: ['Omar ibn Al-Khattab', 'Abou Hourayrah', 'Fatimah bint Qays (rapportant la narration du Prophète)', 'Anas ibn Malik'], correctAnswerIndex: 2, explanation: 'Dans une inversion unique, le Prophète a raconté l\'histoire du Dajjal et de la Bête du compagnon Tamim Al-Dari à la congrégation, enregistrée célèbrement dans le Hadith d\'Al-Jassasah.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_78', question: 'Quel est le terme juridique spécifique pour la période d\'attente d\'une femme après un divorce ou le décès de son mari ?', options: ['Khoul\'', 'Mahr', '\'Iddah', 'Zihar'], correctAnswerIndex: 2, explanation: 'L\'\'Iddah est une période d\'attente obligatoire qui garantit qu\'il n\'y a pas de grossesse et fournit une fenêtre pour la réconciliation dans les divorces révocables.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_79', question: 'Selon le Coran, quel peuple de Prophète a été détruit par un cri ou une explosion terrible (Al-Sayhah) ?', options: ['Prophète Nouh (Noé)', 'Prophète Lout (Lot)', 'Prophète Salih (Peuple de Thamoud)', 'Prophète Younous (Jonas)'], correctAnswerIndex: 2, explanation: 'Le peuple de Thamoud a été détruit par une explosion sonique dévastatrice (Al-Sayhah) après avoir tué la chamelle miraculeuse.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_80', question: 'Qui était le commandant militaire global des Musulmans à la bataille décisive d\'Al-Qadissiyyah contre les Perses ?', options: ['Khalid ibn Al-Walid', 'Sa\'d ibn Abi Waqqas', 'Amr ibn al-Aas', 'Abou Oubaida ibn al-Jarrah'], correctAnswerIndex: 1, explanation: 'Sa\'d ibn Abi Waqqas a dirigé la bataille malgré sa grave maladie, menant à l\'une des victoires les plus critiques de l\'histoire islamique.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_81', question: 'Lequel des éléments suivants n\'est PAS une condition nécessaire pour qu\'un hadith soit classé strictement comme "Sahih" ?', options: ['Continuité de la chaîne', 'Caractère intègre des narrateurs', 'Rapporté par au moins dix compagnons', 'Absence de défauts cachés (\'Illah)'], correctAnswerIndex: 2, explanation: 'Un hadith Sahih n\'a pas besoin de dix compagnons (c\'est un hadith Mutawatir). Un hadith Sahih peut techniquement être rapporté par une seule chaîne fiable.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_82', question: 'Qu\'est-ce que la "Shouf\'a" dans le droit islamique de la propriété et des contrats ?', options: ['Un paiement de dot', 'Le droit de préemption accordé à un copropriétaire ou voisin d\'acheter la propriété avant qu\'elle ne soit vendue à un étranger', 'Une fiducie caritative', 'Un contrat invalide'], correctAnswerIndex: 1, explanation: 'La Shouf\'a protège les partenaires et voisins de l\'introduction d\'un étranger indésirable dans leur propriété partagée ou leur voisinage immédiat.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_83', question: 'À quoi le terme "Mawali" fait-il référence dans le contexte de l\'histoire islamique primitive ?', options: ['Les généraux militaires', 'Les Musulmans non-arabes qui sont devenus des clients affiliés à une tribu arabe', 'Les habitants de La Mecque', 'Les collecteurs d\'impôts'], correctAnswerIndex: 1, explanation: 'À mesure que l\'empire s\'étendait, les non-Arabes ont embrassé l\'Islam et se sont intégrés dans la structure sociale en tant que Mawali (clients/affiliés) des tribus existantes.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_84', question: 'Qu\'est-ce que le "Tayamoun" dans la Sunnah ?', options: ['Jeûner un jour sur deux', 'La pratique de commencer par le côté droit dans les actions pures et nobles (comme mettre ses chaussures ou entrer dans une mosquée)', 'Prier la nuit', 'Donner la charité en secret'], correctAnswerIndex: 1, explanation: 'Le Prophète favorisait commencer par la droite (Tayamoun) dans toutes les bonnes choses, laissant la gauche pour l\'élimination des impuretés.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_85', question: 'Dans la classification du Hadith, qu\'est-ce qui distingue principalement un hadith "Hasan" (Bon) d\'un hadith "Sahih" (Authentique) ?', options: ['Un hadith Hasan a une chaîne brisée', 'Un hadith Hasan est fabriqué', 'Dans un hadith Hasan, la précision/mémoire du narrateur (Dabt) est légèrement inférieure à celle requise pour Sahih', 'Un hadith Hasan contredit le Coran'], correctAnswerIndex: 2, explanation: 'Un hadith Hasan est parfaitement valide pour déduire des lois, mais ses narrateurs sont connus pour être légèrement moins rigoureux dans leur mémorisation exacte que les narrateurs Sahih.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_86', question: 'Quelle Sourate mentionne explicitement le fils adoptif du Prophète Muhammad, Zayd, par son nom ?', options: ['Sourate Al-Baqarah', 'Sourate Al-Ahzab', 'Sourate Muhammad', 'Sourate At-Talaq'], correctAnswerIndex: 1, explanation: 'La Sourate Al-Ahzab (33:37) est le seul endroit dans le Coran où un compagnon (Zayd ibn Harithah) est mentionné explicitement par son nom.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_87', question: 'Qu\'est-ce que la "Moudarabah" dans la finance islamique ?', options: ['Facturer des frais de retard', 'Un partenariat où une partie fournit le capital et l\'autre fournit le travail/l\'expertise', 'Louer des terres agricoles', 'Vendre une dette'], correctAnswerIndex: 1, explanation: 'Dans un contrat de Moudarabah, les profits sont partagés selon un ratio pré-convenu, mais les pertes financières sont supportées uniquement par le fournisseur de capital.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_88', question: 'Quel compagnon a été envoyé comme espion dans le camp ennemi de la coalition pendant les vents glacials de la Bataille de la Tranchée ?', options: ['Ali ibn Abi Talib', 'Zoubayr ibn al-Awwam', 'Houdhayfah ibn al-Yaman', 'Sa\'d ibn Mou\'adh'], correctAnswerIndex: 2, explanation: 'Houdhayfah a été chargé par le Prophète de cette mission extrêmement dangereuse pour recueillir des renseignements sans révéler sa couverture.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_89', question: 'Que signifie la maxime fondamentale du Fiqh "Al-Yaqeen la yazoulou bil-Shakk" ?', options: ['La difficulté apporte la facilité', 'Le préjudice doit être supprimé', 'La certitude n\'est pas annulée par le doute', 'La coutume fait autorité'], correctAnswerIndex: 2, explanation: 'Cette maxime signifie qu\'un état confirmé (comme avoir le Woudou) ne peut pas être annulé par un simple soupçon ou doute.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_90', question: 'Quel savant classique est célèbre sous le nom de "Cheikh al-Islam" et a rédigé le massif "Majmou\' al-Fatawa" ?', options: ['Ibn Hajar Al-Asqalani', 'Ibn Taymiyyah', 'Imam Al-Nawawi', 'Ibn Qayyim Al-Jawziyyah'], correctAnswerIndex: 1, explanation: 'Taqi ad-Din Ahmad ibn Taymiyyah était un savant profondément influent des XIIIe/XIVe siècles connu pour ses écrits prolifiques et son recours strict aux textes anciens.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_91', question: 'Dans les Ousoul al-Fiqh, qu\'est-ce que l\'"Ijma\' Soukouti" ?', options: ['Consensus verbal', 'Consensus établi par le silence de tous les savants sur la connaissance d\'une règle, impliquant une approbation tacite', 'Consensus de la première génération uniquement', 'Consensus de Médine'], correctAnswerIndex: 1, explanation: 'L\'Ijma\' Soukouti (consensus tacite) se produit lorsqu\'une règle est rendue publique et qu\'aucun savant ne s\'y oppose sur une période raisonnable.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_92', question: 'Qu\'est-ce que le "Khamr" dans la jurisprudence islamique ?', options: ['Tout type de nourriture', 'Strictement le vin fait de raisins', 'Toute substance qui enivre et obscurcit l\'intellect, quelle que soit sa source', 'Le jeu d\'argent'], correctAnswerIndex: 2, explanation: 'Le Prophète a défini le Khamr largement : "Tout enivrant est Khamr, et tout Khamr est Haram."', difficulty: 'hard'),
    QuizQuestion(id: 'hard_93', question: 'Quel est le terme pour l\'expiation payée pour avoir tué accidentellement une personne en droit islamique ?', options: ['Qisas', 'Diyyah (Prix du sang)', 'Kaffarah', 'Zakat'], correctAnswerIndex: 1, explanation: 'La Diyyah est la compensation financière versée à la famille de la victime en cas de mort ou de blessure non intentionnelle.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_94', question: 'Lequel des éléments suivants décrit un "Hadith Qoudsi" ?', options: ['Un hadith rapporté par des anges', 'Un hadith où le sens vient d\'Allah, mais la formulation vient du Prophète', 'Un chapitre du Coran', 'Un hadith fabriqué'], correctAnswerIndex: 1, explanation: 'Contrairement au Coran (où le sens et la formulation viennent d\'Allah), un Hadith Qoudsi est un message divin formulé dans les propres mots du Prophète.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_95', question: 'Quel a été le premier traité formel entre Musulmans et non-Musulmans qui a établi Médine comme un État pluraliste ?', options: ['Traité de Hudaybiyyah', 'Constitution de Médine (Sahifat al-Madinah)', 'Traité de Najran', 'Serment d\'Aqabah'], correctAnswerIndex: 1, explanation: 'La Constitution de Médine a établi la défense mutuelle et les droits civils entre Musulmans, Juifs et tribus alliées.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_96', question: 'Quel compagnon a compilé le commentaire (Tafsir) et l\'histoire les plus complets et faisant autorité au début de l\'Islam, méritant le titre d\'"Imam des Moufassirin" ?', options: ['Abdullah ibn Masoud', 'Ibn Jarir Al-Tabari', 'Abdullah ibn Abbas', 'Ibn Kathir'], correctAnswerIndex: 1, explanation: 'Muhammad ibn Jarir Al-Tabari a compilé "Jami\' al-Bayan", le Tafsir ancien le plus important s\'appuyant sur des chaînes de narration.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_97', question: 'Quelle est la signification de "Qalqalah" dans le Tajweed ?', options: ['Fusionner les sons', 'Étirer les voyelles', 'Créer un son d\'écho ou de rebond sur certaines lettres consonantiques lorsqu\'elles sont non vocalisées (Sakin)', 'S\'arrêter brusquement'], correctAnswerIndex: 2, explanation: 'La Qalqalah s\'applique aux lettres Qaf, Ta, Ba, Jim et Dal (قطب جد) pour garantir qu\'elles soient clairement entendues lorsqu\'elles portent un Soukoun.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_98', question: 'Quelle bataille est unique parce que le Prophète a désigné trois commandants successifs (Zayd, Ja\'far et Abdullah) qui ont tous été martyrisés ?', options: ['Bataille de Badr', 'Bataille de Uhud', 'Bataille de Mou\'tah', 'Bataille de Hounayn'], correctAnswerIndex: 2, explanation: 'La Bataille de Mou\'tah contre les forces byzantines a vu les trois commandants désignés tomber avant que Khalid ibn Al-Walid ne prenne le commandement.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_99', question: 'Dans la méthodologie du Hadith, qui sont les auteurs des "Al-Koutoub al-Sittah" (Les Six Livres) ?', options: ['Boukhari, Mouslim, Abou Dawood, Tirmidhi, An-Nasa\'i, Ibn Majah', 'Malik, Chafi\'i, Ahmad, Abou Hanifa, Boukhari, Mouslim', 'Tabari, Qourtoubi, Ibn Kathir, Souyouti, Razi, Baghawi', 'Boukhari, Mouslim, Hakim, Bayhaqi, Darimi, Daraqoutni'], correctAnswerIndex: 0, explanation: 'Ces six collections forment le noyau canonique de la littérature du Hadith sunnite, largement acceptées pour leurs normes rigoureuses.', difficulty: 'hard'),
    QuizQuestion(id: 'hard_100', question: 'Qu\'est-ce que le "Takhrij" dans la science du Hadith ?', options: ['Écrire de nouveaux hadiths', 'Le processus de retracer un hadith jusqu\'à ses sources originales et d\'évaluer son authenticité en fonction de ses chaînes', 'Traduire le hadith en arabe', 'Appliquer un hadith à une règle juridique'], correctAnswerIndex: 1, explanation: 'Le Takhrij est le processus savant minutieux d\'extraire, référencer et analyser de manière critique un hadith à partir de collections de manuscrits originaux.', difficulty: 'hard'),
  ];
}
}